window.ALL_CHAMPION_STORIES = {
  "阿狸": {
    title: "九尾妖狐",
    englishName: "Ahri",
    region: "艾欧尼亚",
    race: "瓦斯塔亚（狐族瓦斯塔亚）",
    personality: "狡黠、任性而迷人，早年靠吸取精魄维生，内心渴望归属与\"人性\"；在背负罪责后努力行善，寻找自己的来处。",
    story: "阿狸此生大部分时间对自己的身世一无所知，她所属的瓦斯塔亚部族几乎彻底消失在历史中，留给她的线索只有一对与她生来形影不离的双生宝石。她最早的记忆是在尚赞北部与一群冰原狐共同奔跑------她知道自己不是它们的一员，却被狐群接纳。\n\n后来她以吸取凡人的精魄为生，也因此在追寻力量的过程中害死过他人，心怀愧疚。每次吞取一个人的精魄，她都会随之继承对方一生的记忆与情感，那些不属于自己的爱恨像潮水般涌入，让她既痛苦又沉迷。为了创造一份真正属于自己的记忆，也为了弄清自己究竟是谁，她踏上寻根之旅，追查双生宝石与部族残迹。在艾欧尼亚遭受诺克萨斯入侵的岁月里，她逐渐承担起守护初生之土的责任，用自己的魔法庇护流离失所的同胞，成为瓦斯塔亚部族残部中举足轻重的人物之一。",
    relations: "双生宝石指向其消逝的瓦斯塔亚部族；与艾欧尼亚各方势力（如李青、亚索等）多有交集；是符文之地最负盛名的瓦斯塔亚之一。"
  },
  "阿卡丽": {
    title: "离群之刺",
    englishName: "Akali",
    region: "艾欧尼亚",
    race: "人类",
    personality: "独立、果决、叛逆，拒绝被教条与组织束缚；忠于自己对艾欧尼亚的守护，认为真正的正义必须亲手兑现。",
    story: "阿卡丽出身均衡教派的暗影之拳世家，母亲玛维·卡尔哈曾是上一代暗影之拳。十四岁那年，她正式开始均衡教派的训练，决心继承母亲的位置成为新的暗影之拳。她是练武奇才，精通钩镰和苦无，虽不像同门那样天生掌握魔法，仍凭实力赢得称号，让母亲得以退居幕后教导后辈。\n\n然而诺克萨斯入侵艾欧尼亚后，均衡教派坚持\"守势\"、只维护万物平衡而不直接出手抗敌的原则，让年轻的阿卡丽越来越难以忍受。她放弃了\"暗影之拳\"的头衔，也离开了均衡教派，独自行动，成为一名独来独往的刺客。她依然牢记从宗师慎身上学到的一切，但效忠的对象是艾欧尼亚的人民------她直接铲除那些威胁初生之土的敌人，每次只取一条性命，以此传递响亮的信息：不听命于任何人的刺客最为可怕。",
    relations: "师父兼前同门慎（均衡教派宗师）；母亲玛维·卡尔哈（上一代暗影之拳）；与劫的影流教派敌对；与凯南同为均衡教派旧识。"
  },
  "彗": {
    title: "异画师",
    englishName: "Hwei",
    region: "艾欧尼亚",
    race: "人类",
    personality: "温和、内省，与色彩和情绪共鸣极深；内心藏着无人得见的夜幕，在慈悲与毁灭的边缘行走。",
    story: "艾欧尼亚西北角的勾崖岛上坐落着自古传承的艺术学府勾崖寺，麓开·彗生来便是这座寺院的继承人。他与世界的色彩共鸣极深，瞳孔颜色会随情绪变化；他的画能左右观者情绪，因此戒律极严------失控者会被逐出勾崖。\n\n年少演练时，他以海景为题，情绪如狂潮吞没理智，险些溺毙于画中幻景。上师们虽未逐他，他却从此白天守规、夜里独自试探力量的极限，最终凝出一只盛放魔力颜料的色盘。\n\n成年后，名画家卡达·烬到访勾崖，与他交换见解，却在离去前夜挑战他\"看一场真正的表演\"。彗纵情作画，多年被压抑的想象喷涌而出。拂晓时勾崖已成火海：四幅古画被毁、四名当年险些被他害死的上师被摆成图案杀害、寺楼起火。他在废墟碎石下发现一枚莲花形状的陷阱碎片，恍然认出罪魁。葬礼后他白日与居民哀悼、夜晚回灰烬作画，最终离开孤岛，带着画笔与色盘走遍艾欧尼亚最阴暗的角落------既向受害者带去宁静内省，也逼迫恶人见证他心中的痛苦。他心中哪一面能走到最后，尚未可知。",
    relations: "勾崖寺的继承人；与卡达·烬亦师亦敌（烬毁其寺、杀其上师）。"
  },
  "艾瑞莉娅": {
    title: "刀锋舞者",
    englishName: "Irelia",
    region: "艾欧尼亚",
    race: "人类",
    personality: "外柔内刚、沉静而坚韧；心底仍渴望单纯起舞，却被战争推上抵抗领袖的位置。",
    story: "赞家的艾瑞莉娅从小痴迷人体动态之美，在奶奶指导下修习家乡传统绸舞，后赴纳沃利普雷西典向艾欧尼亚最负盛名的舞者学艺。诺克萨斯入侵的消息传来，她回到村庄，却发现家乡沦陷：父兄反抗而死，全家葬于花园；海军上将杜廓尔砸碎了赞家的金属家徽。\n\n碎片落地时，古老舞仪中那股祥和韵律在她灵魂深处搏动------徽记碎片如刀刃般呼啸而起，切过诺克萨斯士兵。她拢起碎片逃出村子，在森林中领悟自己所学的不只是舞蹈。她加入纳沃利的反抗力量，十四岁回到普雷西典时，狡猾的将军斯维因已设下陷阱。她挺身迎战，古老刃舞喷涌而出，击倒十数人，将斯维因的断臂举过头顶------这一幕\"纳沃利的挺立\"成为战争转折点。\n\n她勉为其难率领反抗军浴血近三年，最终在答禄湾逼死杜廓尔、完成复仇。如今艾欧尼亚四分五裂，许多人仍指望她收拾局面，但她心底依旧惴惴不安。",
    relations: "赞家遗孤，父兄与奶奶为其舞艺渊源；仇敌杜廓尔、斯维因；与卡尔玛等艾欧尼亚抵抗力量并肩。"
  },
  "艾翁": {
    title: "翠神",
    englishName: "Ivern",
    region: "艾欧尼亚",
    race: "自然灵（由人类被帝柳转化而成）",
    personality: "温厚、天真、富有悲悯；痛悔昔日无情，决心以余生教导凡人与万物共生。",
    story: "\"无情者艾翁\"是古代沃尔瑞加德末期出名的勇猛战士，氏族信奉好战旧神，不肯臣服崛起的\"三姐妹\"。为推翻冰裔，他率舰队航向东方传说中魔法初升之地，血洗十多个艾欧尼亚沿海定居点，直抵圣地奥米卡亚兰------\"世界之心\"。在那里他找到了艾欧尼亚至圣之物：金光垂拂的庞然巨树帝柳。为瓦解敌人意志，他一斧砍下树干。\n\n大树倒下的瞬间，生命能量乱流吞没了他。恍惚中他看见死者血肉反哺土地、新叶新花汹涌爆发的盛景，落泪时发觉自己已变得高大，四肢覆满树皮枝叶------他自己就是残存的帝柳。顿悟后他听见山丘与树木的呼喊，痛悔旧日的无情。\n\n数百年后他漫游到远方，能与根须、石块、江河交流，帮毛虫抄近路、安慰厄玛克、为将死的石巨人捏一颗卵石心脏------那石花石身的朋友便是\"小菊\"。他见人类索取远多于奉献，遂不再与凡人为伍，却决意以帝柳传承者的身份培养人性：帮助他们去看、去听、去生长。他有的是时间。",
    relations: "旧身为弗雷尔卓德先民、与\"三姐妹\"同时代；与石巨人小菊为过命之交；帝柳即奥米卡亚兰圣地之树。"
  },
  "烬": {
    title: "戏命师",
    englishName: "Jhin",
    region: "艾欧尼亚",
    race: "人类",
    personality: "病态痴迷\"艺术\"的冷静谋杀者；把整片符文之地当作画布，视杀人为精心编排的表演。",
    story: "艾欧尼亚南部山区连年遭恶名昭彰的\"金魔\"荼毒：成群旅行者被杀、农庄被毁、尸体扭曲。芝云议会请来均衡教派的苦说大师，携年少的慎与徒弟戒秘密追查。四年间三人从凶案现场拼出规律，苦说断定这并非恶魔，而是一名穷凶极恶的人类或瓦斯塔亚。\n\n吉雍道绽灵节前夜，他们设下陷阱，与\"金魔\"正面对峙------对方不过是芝云巡回剧团的舞台管理员卡达·烬。戒欲当场杀他，苦说却将其活捉关入吐冷修道院监狱，担心放虎归山会动摇艾欧尼亚的信任与和谐。据说这正是戒心中恨意萌发的起源。\n\n狱中烬展露铸铁、诗歌、舞蹈等极高学习天赋，却冥顽不化。诺克萨斯战争唤醒了艾欧尼亚深藏的嗜血渴望，战后他获释，疑似成为某激进势力的工具，并取得喀舒利兵工厂的新式武器与近乎无限的资金。他的\"表演\"从艾欧尼亚蔓延到皮尔特沃夫与祖安，甚至造访勾崖寺、诱导彗纵情作画后纵火杀人。没人知道下一笔浓墨重彩会落向何处。",
    relations: "当年追捕他的苦说、慎、戒（劫）；诱导并毁灭了勾崖寺的彗；背后金主与喀舒利兵工厂成谜。"
  },
  "卡尔玛": {
    title: "天启者",
    englishName: "Karma",
    region: "艾欧尼亚",
    race: "人类（古老艾欧尼亚灵魂的转世化身）",
    personality: "承载千年智慧，温和而坚定；在和平主义与现实的暴力之间走出自己的中道。",
    story: "卡尔玛是古老艾欧尼亚灵魂在现世的化身，最近一次转生为尚赞北方高地的十二岁女孩达尔哈。她自幼看到不属于自己的\"回忆\"幻象，以为自己在发疯，直到长存之殿的僧侣寻访而来------他们的前任圣师数月前刚逝，正在寻找转世灵童。达尔哈冲出疗养屋哭诉幻象，僧侣们当即认出迹象：过去生生世世的声音涌入新载体。\n\n她前往长存之殿受业，学会与古代灵魂沟通，却仍不免质疑历代卡尔玛倡导的和平与和谐。诺克萨斯入侵艾欧尼亚后，成千上万人命丧铁蹄，她感受着灵魂中无限破坏潜力膨胀，自问\"置之不用的力量有何意义\"。她违抗殿中声音的规劝，在一艘诺克萨斯战舰上释放神圣怒火，心跳之间令全舰船员覆灭。\n\n僧侣们斥她亵渎和谐，她却明白：有时和谐需要付出巨大代价，真正的智慧不是拒绝改变，而是接受事实。战争结束后，艾欧尼亚许多人快意恩仇，卡尔玛决心引导他们走向更开明的路------可和则和，必要时亦当出手。",
    relations: "长存之殿僧侣群体；作为\"艾欧尼亚之魂\"历代转世；与艾瑞莉娅等抵抗力量同历诺克萨斯入侵。"
  },
  "凯隐": {
    title: "影流之镰",
    englishName: "Kayn",
    region: "艾欧尼亚",
    race: "人类（体内寄宿暗裔武器拉亚斯特）",
    personality: "自信到近乎狂妄，野心勃勃，坚信自己终将成为影流教派的领袖；甘愿被暗裔腐化也要追求力量，是一个把命运押在自己意志上的赌徒。",
    story: "悉达·凯隐生于诺克萨斯，在诺平岱城战役的惨重伤亡后，作为诺克萨斯童兵被艾欧尼亚方面所俘。影流教派的大师劫看中了这个孩子身上的暗影天赋，将他收为弟子。凯隐在影流长大，修习暗影魔法，很快便展现出天纵之才，他梦想有朝一日率领影流、开创艾欧尼亚霸业的新世代。\n\n一次任务中，他被派去处置一件被认为应当毁掉的活体暗裔武器------巨镰\"拉亚斯特\"。与其他信徒不同，凯隐非但没有摧毁这把武器，反而将其据为己有。他的手指刚一握住镰柄，腐化便开始将二者束缚在一起。拉亚斯特渴望一个完美宿主，以便与暗裔同族重聚、血洗世界；但凯隐拒绝被占据，反而试图驯服这把武器。两种意志在他体内永不停歇地角力------要么凯隐让拉亚斯特屈服于自己的暗影意志，成为前所未有的暗影刺客；要么拉亚斯特夺舍成功，暗裔重获肉身。他带着这场宿命的缠斗回到艾欧尼亚，等待最终的抉择之日。",
    relations: "师父/影流领袖劫；体内暗裔拉亚斯特（共生宿敌）；与影流教派同门（如阿卡丽、慎等）有同门之谊；曾与亚托克斯（暗裔剑魔）产生交集。"
  },
  "凯南": {
    title: "狂暴之心",
    englishName: "Kennen",
    region: "艾欧尼亚",
    race: "约德尔人",
    personality: "急性子、雷厉风行，却又机智圆滑、善于斡旋；作为均衡教派三首领之一，他以亲切随和与婉转外交维持教派和谐。",
    story: "凯南是一名约德尔人，数千年前便离开了班德尔城的精神领域，对物质世界抱有无限好奇，以闪电般的速度穿梭于远方。他尤其被艾欧尼亚------那片初生之土------所吸引。\n\n在艾欧尼亚，他目睹了古老的均衡教派因内部纷争而面临瓦解。作为同时存在于精神与物质两个领域的生物，凯南主动请缨担任仲裁者，认为自己独特的跨域身份最适合充当裁判。教派接纳了他，他成为均衡教派历史上首任\"狂暴之心\"，与\"暮光之眼\"（慎）、\"暗影之拳\"（阿卡丽离教后由其他人接替）共同组成三首领议会。凯南负责裁断如何行动才能最好地维护万物平衡，他用热情与外交手腕维持着教派内部的和谐。当劫背叛教派、建立影流之后，均衡教派与影流之间的对峙也成为凯南必须处理的长期难题之一。",
    relations: "均衡教派三首领之一（与暮光之眼慎同列）；与叛教的影流之主劫为理念对立；约德尔人身份使他能自由往来于精神领域与物质领域。"
  },
  "李青": {
    title: "盲僧",
    englishName: "Lee Sin",
    region: "艾欧尼亚",
    race: "人类",
    personality: "坚毅、自省而苦行；因年轻时犯下的过错而终生赎罪，对艾欧尼亚的灵与土地怀有深沉的爱与愧疚。",
    story: "李青从小便是艾欧尼亚一座寺庙中极具天赋的武僧，他年轻气盛，急于证明自己掌握了神龙之力。在一次未经允许的修炼中，他失控地召唤出神龙之灵，结果酿成大祸------意外导致一座寺庙被烧毁，一位同门师兄弟在事故中丧生。这次事故让他万念俱灰，他离开了寺庙，踏上漫长的自我放逐之路，以苦行赎罪。\n\n多年后，他与乌迪尔结伴同行，得知诺克萨斯帝国已经入侵并占领了艾欧尼亚。各省僧侣都撤回希拉娜山顶的神圣修道院保卫家园。当他们赶到时，诺克萨斯士兵已经突入大殿。看着昔日的同辈与长老倒在敌人剑下，李青终于不再犹豫------他在绝境中再次唤醒了神龙之灵。火焰与狂风裹住他，他以雷霆般的拳脚击溃入侵者，但也付出了惨痛代价：烈火灼烧了他的双眼，他的视力永远无法恢复。僧侣们赢得了战斗，修道院却成了废墟。从此李青以盲僧之身行走世间，将神龙之力融入每一击，守护初生之土。",
    relations: "与乌迪尔并肩作战；希拉娜修道院的同门与长老；唤醒了神龙之灵（龙灵）；与艾欧尼亚各方守护势力同列。"
  },
  "莉莉娅": {
    title: "含羞蓓蕾",
    englishName: "Lillia",
    region: "艾欧尼亚",
    race: "仙灵（艾欧尼亚幻梦树所生的小鹿精）",
    personality: "羞怯、敏感而好奇；害怕凡人又渴望理解他们，通过梦境观察人类，对外面的世界既向往又畏惧。",
    story: "在艾欧尼亚的森林深处，矗立着一棵古老的幻梦树------它吸收凡人的梦境，将其化为魔法滋养森林。每当花朵绽放，梦境便以魔法的形式释放。然而有一天，这棵树做了一个\"自己的梦\"------那枚承载着树之梦境的蓓蕾尚未绽放便落到了地上，于是莉莉娅诞生了：一只头顶仍顶着蓓蕾的奇异小鹿。\n\n她的陪伴只有树妈妈，以及每晚飘进花园的那些梦境。她通过蓓蕾中映出的梦境观察人类，对凡人的喜怒哀乐既着迷又害怕。然而不知从何时起，凡人的梦境再也无法抵达幻梦树------人们似乎不再做梦了。莉莉娅意识到自己必须离开森林，去寻找为什么人们的梦境断绝了。她带着一根魔法枝条，怯生生地踏入艾欧尼亚的广袤大地，一边躲避着凡人的视线，一边追踪那些未被实现的梦境。只有通过帮助人们解开恐惧与心结，她自己头顶的蓓蕾才能最终绽放。",
    relations: "幻梦树（树妈妈）；与茂凯、艾翁等艾欧尼亚自然之灵同属初生之土的灵性存在；通过梦境与人类世界间接相连。"
  },
  "易": {
    title: "无极剑圣",
    englishName: "Master Yi",
    region: "艾欧尼亚",
    race: "人类",
    personality: "沉静、内省，背负着失去家园的愧疚；表面是世外高人，内心却一直为自己当年的决定赎罪。",
    story: "易成长于艾欧尼亚中部省份巴俄里群山中一个名为\"无极\"的隐秘村落。无极之道是一门古老剑术，追求以精神感知敌我、以极快的剑技克敌。易从小便是最有天赋的弟子，他追随师父修炼，梦想着成为无极武道的一代宗师。\n\n然而诺克萨斯入侵艾欧尼亚的炮火打破了一切。易与同门弟子下山保卫初生之土，他们以无极剑技在战场上势如破竹，一度成为艾欧尼亚抗敌的旗帜。但诺克萨斯注意到了这支小队的威胁，便在他们离开村子之后转而屠戮了无极村------用化学武器将整个村庄化为焦土。易从前线赶回来时，家园已不复存在，师父与同门尽皆惨死。他深深悔恨：是自己带走了村中的战力，才让诺克萨斯有机可乘。他独自守在废墟中忏悔了多年，直到一只名叫空的瓦斯塔亚猴子找上门来，执意要拜他为师。易在教授悟空的过程中重新找到了活下去的意义------他将无极之道传给了这位最后的弟子，二人一同踏上守护艾欧尼亚的旅程。",
    relations: "最后的弟子孙悟空（瓦斯塔亚猿族\"空\"）；无极村已故师父与同门；与艾欧尼亚各方守护势力并肩抗敌。"
  },
  "孙悟空": {
    title: "齐天大圣",
    englishName: "Wukong",
    region: "艾欧尼亚",
    race: "瓦斯塔亚（思猕猿族）",
    personality: "机灵、滑头、好斗而忠诚；年轻时鲁莽冲动，被族人放逐后却在旅途中找到了真正的道与朋友。",
    story: "在艾欧尼亚的魔法森林中，住着一支名为思猕猿的瓦斯塔亚部族。他们谨慎而知足，认为生命就像在智慧之树上攀援，死后会化为石头回归土地。年轻的\"空\"是族中的异类------他鲁莽、调皮、永远百无聊赖，总觉得部落的安宁是一种束缚。终于在一次闯祸之后，他被族人放逐，独自踏上了寻找\"真正武艺\"的旅程。\n\n他在山中遇到了独守废墟的易------那位无极剑圣。空起初只想挑战易，证明自己才是天下第一，但在交手过程中，他发现易一直在为自己当年带同门下山抗敌、导致无极村被屠而深深自责。空意识到这就是他一直追寻的东西------不只是武艺，而是一种值得用一生去守护的道。他恳求易收他为徒，易在这只莽撞却真诚的猴子身上看到了重振无极之道的希望，将附魔长棍与\"悟空\"这个名号传给了他。如今二人一同游历初生之土，悟空成为无极最后的弟子，发誓要守护艾欧尼亚免遭崩溃。",
    relations: "师父易大师（无极剑圣）；思猕猿族（将他放逐的瓦斯塔亚部落）；与艾欧尼亚各方守护势力同行。"
  },
  "洛": {
    title: "幻翎",
    englishName: "Rakan",
    region: "艾欧尼亚",
    race: "瓦斯塔亚（洛特兰部族）",
    personality: "轻浮、热情、爱热闹、吊儿郎当；但在爱人霞面前，却能展现出惊人的忠诚与敏锐。",
    story: "洛出身于艾欧尼亚深处正在衰落的洛特兰瓦斯塔亚部族。数百年来人类聚居地不断扩张，筑起堤坝截断艾欧尼亚的野性魔法，瓦斯塔亚各部族赖以生存的魔力日渐枯竭。许多部族派出使者与人类谈判，却一次次被背约。\n\n心灰意冷的瓦斯塔亚人四散退隐，洛却依旧是那个在人类高地集市上以狂野节庆、无拘音乐和叛逆舞蹈闻名的\"麻烦制造者\"，也是洛特兰部族史上最伟大的战舞者。他本可以继续做一个巡回表演者，直到遇见了霞------一个决心以武力夺回艾欧尼亚魔力的瓦斯塔亚革命者。\n\n两人性格截然相反：霞严肃、目标明确，洛健忘、随心所欲。但洛能用魅力与察言观色弥补计划的漏洞，两人在一场酒楼斗殴中彼此誓定终身。从此他告别旧生活，跟随霞走遍艾欧尼亚，成为她最狂热的战友与恋人。",
    relations: "恋人霞（同为瓦斯塔亚革命者）；洛特兰部族出身；与艾欧尼亚反抗人类势力的各部瓦斯塔亚结盟。"
  },
  "瑟提": {
    title: "腕豪",
    englishName: "Sett",
    region: "艾欧尼亚",
    race: "半兽人（诺克萨斯人类父亲与瓦斯塔亚母亲的混血）",
    personality: "傲慢、好斗而重情义；因半兽身份从小被排斥，靠双拳打天下，对母亲极为孝顺，对手下讲江湖义气。",
    story: "瑟提出身低微，是艾欧尼亚地下世界崛起的一方霸主。他的父亲是诺克萨斯人，母亲则是瓦斯塔亚人，这个\"半兽\"男孩从降生起就是个异类。他的出生令母亲所属的瓦斯塔亚部落震惊不已，因为违背了部族传统，一家人被驱逐。艾欧尼亚的人类社会同样不接受这场禁忌的结合，但他的父亲作为当地搏击场的拳手小有名气，多少为一家人挡掉了一些非议。\n\n然而有一天，瑟提的父亲被远方更高额的报酬吸引，离开搏击场后再也没有回来。为了撑起家庭，瑟提走进了父亲曾经战斗过的纳沃利搏击场。他天生力大无穷、皮糙肉厚，虽然毫无格斗技巧，却靠着一身蛮力和惊人的耐打迅速名声鹊起。当当地搏击手尽数被他击败后，瑟提反过来掌控了他曾经浴血奋战的搏击场。诺克萨斯入侵艾欧尼亚的战争结束后，艾欧尼亚的地下王国日渐繁荣，瑟提凭借搏击场的收入与人脉，成为一方不可小视的势力。",
    relations: "母亲为瓦斯塔亚人（被部落驱逐后独自抚养他）；父亲为诺克萨斯搏击手（抛家不归）；在纳沃利搏击场从拳手成为场主。"
  },
  "慎": {
    title: "暮光之眼",
    englishName: "Shen",
    region: "艾欧尼亚",
    race: "人类",
    personality: "冷静、克制、不近人情；力求超脱情感与偏见，行走于精神领域与物质世界之间的隐秘审判之路，严格恪守均衡教旨。",
    story: "慎出身于纳沃利北部的名门之后，但真正注定他命运的，是父亲作为均衡教派宗师、\"暮光之眼\"苦说的身份。他从小在均衡教派的文化熏陶下长大，教派的核心教旨------修剪、凝视、不偏不倚------对他来说就像艾欧尼亚的日落一样熟悉而自然。他自幼接受严酷的训练，学会压制个人情感与偏见，以执行教派赋予的审判。\n\n然而命运的转折来自一场追捕。苦说带着慎和徒弟劫一起，去追捕一个逃亡的金魔。三人历经多年终于找到目标，苦说却选择不杀他，反而想教化他。劫对此无法理解，在激烈的争执后反叛教派，杀死了苦说并逃走。慎在悲痛中接过了父亲的衣钵，成为新一代暮光之眼。他必须亲手维持精神领域与物质世界之间的均衡，哪怕这意味着要与曾经的同门、如今的影流之主劫为敌。他行走于凡人世界与精神领域的夹缝中，用钢刀与魂刃对抗任何威胁均衡之人。",
    relations: "父亲苦说（前暮光之眼，被劫所杀）；师弟劫（反叛均衡教派，创立影流，互为宿敌）；同为均衡教派的阿卡丽、凯南为同袍。"
  },
  "辛德拉": {
    title: "暗黑元首",
    englishName: "Syndra",
    region: "艾欧尼亚",
    race: "人类（强大的艾欧尼亚法师）",
    personality: "傲慢、孤傲而不容束缚；童年被背叛后对一切试图控制她的人怀有刻骨恨意，将遭遇化为黑暗能量，誓要主宰自己的力量。",
    story: "辛德拉出生于纳沃利省的一个普通农家，从小就是个爱走神的孩子。她经常出神地凝望池塘中的影蚀，或者观察糖壳虫排队上墙，为此没少挨母亲的责骂。然而随着成长，家人逐渐发现这个女孩身上有一种危险的天赋------她的魔法粗暴而狂野，完全不受控制。一次，她在情绪激动时无意间用魔法伤害了村民，村庄的长老们深感不安。\n\n为了\"帮助\"辛德拉控制自己的力量，长老们将她送到了艾欧尼亚的一座圣所，交由一位慈祥的长者教导。辛德拉起初信任这位导师，潜心学习。但随着她的力量日益增长，她逐渐发现自己所谓的导师其实一直在压制她的能力------他们并非在教她控制，而是在封印她。被背叛和伤痛吞噬的辛德拉爆发出毁灭性的力量，将圣所化为废墟。此后她被囚禁在一座孤岛上，由守护者们监视。诺克萨斯入侵艾欧尼亚的战争唤醒了她，曾经看守她的人有的想杀她，有的想利用她对抗诺克萨斯，但辛德拉拒绝成为任何人的棋子。她撕碎了囚禁她的堡垒，将遭遇背叛的痛苦化为黑暗能量法球，发誓要消灭一切想要控制她的人。",
    relations: "成长于纳沃利农家，哥哥艾瓦德常挖苦她；被圣所导师欺骗并封印力量，后将其摧毁；在艾欧尼亚与诺克萨斯战争期间挣脱囚禁，成为独来独往的强大法师。"
  },
  "韦鲁斯": {
    title: "惩戒之箭",
    englishName: "Varus",
    region: "艾欧尼亚",
    race: "暗裔（由恕瑞玛飞升者堕落而来，精魂被封入长弓）",
    personality: "冷血、残忍、执着于复仇；作为杀手最爱用箭矢折磨敌人，先令其失心发疯再了结性命；内心仍残存着作为凡人弓箭手时的荣誉感与对爱人的记忆。",
    story: "无论他后来变成了什么，韦鲁斯曾是忠诚与荣誉的典范。他是古恕瑞玛帝国一名技艺精湛的弓箭手，被任命为东部城邦的神庙守卫，将这一职责视为神圣。在艾卡西亚战争最早的阶段，他的家乡虽远离那片被诅咒之地，却仍遭到袭击；其他守卫纷纷弃岗而逃，唯有韦鲁斯坚守岗位，直至战至最后一人。\n\n在保卫神庙的战斗中，他为了斩杀一名堕落的飞升者，不惜借用了那件被封印的暗裔武器------长弓。弓的力量逐渐腐蚀了他，他被变成了怪物。一位女王将他带往初生之土------后来被称作艾欧尼亚的地方。被弓的力量扭曲成怪物之后，她最后的命令是让追随者将他活埋在一口无光的深井中，深埋于俯瞰帕拉斯村的山神庙之下。韦鲁斯就此被艾欧尼亚的自然魔法与神庙守卫的仪式双重封印。\n\n数百年后，两名艾欧尼亚猎人------瓦朗和凯，一对恋人------为了追杀一头猎杀村民的怪兽，闯入了这座被遗忘的神庙。他们无意间解开了封印，暗裔韦鲁斯的精魄从井中涌出，侵蚀了两人的躯体；他们的身体分崩离析，又相互缠结成一具新的躯壳，正好将韦鲁斯从禁锢中解脱。从井中爬出的是一个苍白而非人般优美的完形生物，一半人类、一半暗裔。如今韦鲁斯寄宿在这具不完美的躯体中，一边在两个猎人残存的意识间撕扯，一边搜寻当年封印自己的人，以实施残酷的复仇。",
    relations: "与同为暗裔的亚托克斯、拉亚斯特、纳亚菲利、亚恒同族；寄宿于艾欧尼亚猎人瓦朗与凯的合体之躯中，三人意识共存；与艾欧尼亚神庙守卫一脉的后人有旧怨。"
  },
  "霞": {
    title: "逆羽",
    englishName: "Xayah",
    region: "艾欧尼亚",
    race: "瓦斯塔亚（洛特兰部族）",
    personality: "决绝、炽热、革命者；对衰落的瓦斯塔亚族群怀着近乎狂热的责任感，身法敏捷、慧心独具；对爱人洛温柔，对敌人冷酷无情。",
    story: "霞是洛特兰部族的女儿。小时候她最爱听父亲吟唱关于古代瓦斯塔亚英雄的民谣，那些旋律将她带回一个被遗忘的时代------那时魔法自由地流淌在奎林岛上，赋予洛特兰人巨大的力量。\n\n然而随着一代又一代人类侵入瓦斯塔亚的祖传领地， raw\nessence（原初精魄）被扰乱，各部族开始衰落，失去它们与自然魔法的联结。霞眼睁睁看着自己的族人变少、变弱，看着祖先的歌谣变成绝响。诺克萨斯对艾欧尼亚的入侵更加剧了这一切：凡人在战争中肆意取用瓦斯塔亚的灵能，战后又继续侵占土地。\n\n艾欧尼亚各地纷纷出现瓦斯塔亚的反叛，他们要对凡人复仇，和平谈判的机会早已荡然无存。霞决定把自己夺命的羽毛用在战斗中，释放这片土地的野生魔法。她在严密把守的城堡要塞中来去翻飞，所过之处留下一连串尸体，因此得来\"紫鸦\"的诨名。她对这项事业的赤诚无与伦比，所关心的只有下一个任务，以及解放同胞的使命。\n\n在旅途中，她遇见了洛------一个性情放荡却身手不凡的拉科斯特部族瓦斯塔亚。洛被她的决绝与美丽吸引，从此跟随她南征北战，成为她的灵魂伴侣与战斗搭档。两人一起在符文之地奔走，联结衰落的瓦斯塔亚部族，对抗人类城邦与诺克萨斯的侵略，希望终有一天率领全族重夺昔日荣光。",
    relations: "灵魂伴侣兼战斗搭档洛；出身洛特兰部族，父亲是吟唱古代英雄民谣的歌者；与阿狸等瓦斯塔亚残部领袖有共同事业；视一切侵占瓦斯塔亚土地的人类势力为敌。"
  },
  "亚索": {
    title: "疾风剑豪",
    englishName: "Yasuo",
    region: "艾欧尼亚",
    race: "人类",
    personality: "自负、冲动、桀骜不驯；天赋异禀却因失职与误杀兄长而终生背负枷锁；在放逐中漂泊，外表放浪，内心被悔恨撕裂。",
    story: "亚索是一个百折不屈的艾欧尼亚人，也是一名身手敏捷的御风剑客。他是永恩同母异父的弟弟。当永恩进入村里著名剑术道场学艺时，年幼的亚索在季风的雨中守在门外，直到老师们心软开门。亚索展现出天生的剑术天赋，成为同辈中唯一引起素马长老注意的学生------素马长老是传说中风之剑术的最后一代宗师。\n\n然而亚索生性冲动，拒绝了长老收他为徒、让他静心修行的好意，依旧我行我素。诺克萨斯入侵艾欧尼亚时，命运被永久改变。亚索本被留下来保卫素马长老，但他自大地以为自己的剑可以改变战局，擅离职守投身战场。等他回到长老身边，发现长老已被御风剑术所杀。\n\n身败名裂的亚索本想自首赎罪，但他发现自己被指控为杀害长老的凶手。他被迫逃亡，成为通缉犯。最可怕的对手是他的哥哥永恩------永恩归来后发现亚索已逃，便率人追捕他。兄弟二人遵照荣誉礼法对峙，剑刃交锋时，永恩未能匹敌，亚索在自卫中手刃了兄长。永恩临死前告诉他：杀长老的是御风剑术，而亚索是唯一可能掌握此术之人。\n\n此后多年，亚索在艾欧尼亚流浪，被各路复仇者追杀。后来真凶逐渐浮出水面------是诺克萨斯刺客利用御风剑术嫁祸于他。虽然真相大白，但亚索无法原谅自己杀死兄长的所作所为。他将自己放逐于天涯，听任疾风指引剑刃的方向。他后来遇见过猴灵（孙悟空的原型），也在旅途中与瑞文等诺克萨斯人有过纠葛。",
    relations: "同母异父的哥哥永恩（死于其剑下）；师父素马长老（被诺克萨斯刺客以御风剑术杀害）；与瑞文有旧怨；与孙悟空（吴）有师徒之谊；与艾欧尼亚抵抗势力多有交集。"
  },
  "永恩": {
    title: "封魔剑魂",
    englishName: "Yone",
    region: "艾欧尼亚",
    race: "亡灵/灵体（生前为艾欧尼亚剑客，死后被亚扎卡纳附体）",
    personality: "生前严谨、守礼、隐忍，是弟弟的守护者；死后戴着恶魔面具，沉静而执着，追猎一切亚扎卡纳以弄清自己究竟成了什么。",
    story: "生前他是永恩，亚索同母异父的哥哥，故乡剑术道场的知名弟子。父亲早逝后，年幼的永恩便承担起保护母亲与弟弟的责任。他与亚索的性格截然相反：亚索鲁莽无礼，永恩则耐心、自律、严守荣誉与职责。\n\n战争降临艾欧尼亚，永恩和许多其他弟子一起离开故乡抗击诺克萨斯军队，而亚索则不情愿地留下来保卫师父素马长老。在一个决定命运的夜晚，素马长老死了------被他所传授的御风剑术弑杀。永恩归来时发现亚索已经逃亡。这件事让他惊愕失色，他坚信亚索就是凶手，于是率人追捕弟弟。\n\n兄弟二人在荒野中对峙，剑刃交锋，永恩不敌，死于亚索剑下。临死前他告诉亚索：杀长老的是御风剑术，而亚索是唯一可能掌握此术之人。\n\n但永恩的灵魂并未安息。他死后发现自己置身于精神领域，立刻被一只亚扎卡纳------以负面情绪为食的次级恶魔------袭击。亚扎卡纳是伊芙琳、塔姆·肯奇这类大恶魔的远亲，以悔恨、愤怒等情绪为食。永恩在灵域中与它搏斗，最终用自己的剑将它弑杀，并取下面具戴在自己脸上。\n\n如今，被诅咒的永恩戴着恶魔面具，活在生死之间。他开始不懈地追猎所有亚扎卡纳，在物质领域与精神领域之间穿梭，既要弄清自己究竟成了什么，也要在这个过程中面对弟弟亚索留下的、永远无法和解的旧伤。",
    relations: "弟弟亚索（死于其剑下）；师父素马长老；脸上佩戴的亚扎卡纳面具是他与灵域恶魔的联结；与一切以情绪为食的亚扎卡纳为追猎目标。"
  },
  "芸阿娜": {
    title: "不破之誓",
    englishName: "Yunara",
    region: "艾欧尼亚",
    race: "瓦斯塔亚",
    personality: "沉静、坚忍、信念如铁；为誓言与世隔绝数百年，外表清冷，内心对初生之土怀着不渝之爱；牺牲在所不惜，却对如今沧海桑田的世界感到陌生。",
    story: "怀揣对艾欧尼亚的不渝之心，芸阿娜进入精神领域，度过了千百年与世隔绝的时光。她手执均衡教派的传说圣器\"艾恩伊纳\"（Aion\nEr\\'na），潜心修炼战法与武艺。芸阿娜曾立誓修除初生之土的一切失谐与纷争，纵有再多牺牲，这誓言与信念也未曾有一丝动摇。\n\n根据官方宇宙页面以\"残篇\"形式披露的设定，芸阿娜是瓦斯塔亚出身的古老战士，与均衡教派有着深远渊源。她在精神领域中闭关修行的漫长岁月里，物质世界的艾欧尼亚经历了诺克萨斯入侵、战后重建、瓦斯塔亚衰落等巨变；当她终于重返人间时，旧日的暗影已翻腾诡谲，世界于她已是沧海桑田。\n\n官方对她的详细传记仍以残篇、手稿残片和弗拉基米尔译本等形式碎片化呈现，暗示她与廓歆旧址、古老的瓦斯塔亚精神传统、以及均衡教派的失落圣物有密切关联。她于2025年6月作为\"灵魂莲华\"赛季第二幕核心英雄上线，定位为精神系射手。\n\n如今她手持艾恩伊纳行走于艾欧尼亚，誓言未改，但面对的敌人已非昔日模样------旧日的暗影以新的形态回归，而她必须在不背叛誓言的前提下，重新理解这个她守护了千年的初生之土。",
    relations: "与均衡教派（慎、劫、阿卡丽一脉）共享圣物艾恩伊纳的渊源；出身瓦斯塔亚，与霞、阿狸等瓦斯塔亚战士同属一族；官方残篇提及与廓歆旧址及弗拉基米尔译本有关，具体关系待官方后续披露。"
  },
  "劫": {
    title: "影流之主",
    englishName: "Zed",
    region: "艾欧尼亚",
    race: "人类",
    personality: "冷酷、决绝、彻底抛弃仁慈与怜悯；为达目的不择手段，相信唯有强力才能保护艾欧尼亚；内心深处仍被与慎的旧日恩怨撕裂。",
    story: "艾欧尼亚的和谐面纱之下掩盖着那些被丢下的人。对劫来说，他的故事要从那个坐在均衡教派家门口冰冷石阶上的小男孩说起。均衡教派的宗师苦说亲自收留了他，他在古老庙墙内找到了容身之处。劫尽心竭力地领悟均衡的精神教旨，很快在战斗和学习两方面超出同辈一大截。即便如此，他还是感到自己活在另一个人的影子下------宗师苦说的儿子，慎。\n\n尽管劫的热情让他在每项技巧上都表现出色，但他始终无法超越慎那种天生的冷静与均衡。这种被掩盖的感觉在多年间慢慢发酵。后来苦说带着两个徒弟前往追捕一名名为\"金魔\"的邪恶召唤师，三人在幽影监狱中经历了改变命运的事件：苦说选择了仁慈，饶了金魔一命，而劫认为这是软弱。\n\n劫在羞愤与嫉妒中离开均衡教派，走入教派禁忌封存的暗影密室，在那里学会了被禁止的暗影魔法------一种来自精神领域的恶灵之力。他带着这支暗影力量归来，召集了一批同样被均衡教派\"遗忘\"的人，创立影流教派，目标是将艾欧尼亚的魔法与传统武术用于实战，驱逐诺克萨斯侵略者。\n\n在诺克萨斯入侵的战争中，绝望指引劫开启了神秘的暗影形态。他杀回均衡教派，手刃师父苦说，夺走了教派的暗影之道。如今他是影流之主，彻底抛弃了仁慈与怜悯，用禁忌的暗影魔法摧毁自己眼中的威胁，维护自己的国家与教派。他与慎（如今的暮光之眼）成为宿敌，两人在艾欧尼亚的暗影与光明之间永恒对峙。",
    relations: "师父苦说（被其所杀）；师兄兼宿敌慎（暮光之眼）；创立影流教派，与均衡教派对立；与阿卡丽有复杂的师徒/同道关系；视诺克萨斯侵略者为死敌。"
  },
  "安蓓萨": {
    title: "铁血狼母",
    englishName: "Ambessa",
    region: "诺克萨斯",
    race: "人类",
    personality: "冷酷、果决、精于权谋，信奉\"恶狼之道\"；作为将军是无情伟力的化身，作为族母则不惜一切代价守护家族传承，哪怕以子女的爱为代价。",
    story: "安蓓萨·米达尔达出生于诺克萨斯的米达尔达家族------这个家族并非旧贵族，却自帝国建立之初便积累起惊人的威望与财富。她自幼在血腥与杀伐中长大，还是孩童时便坐在竞技场边观看清算人以命相搏，逐一研究每一场对决的胜负之机。稍长，她亲自打扫希尔登纳德战役的战场、回收亡者兵器，由此立下戎马一生的志向。\n\n她很快成为米达尔达家族最耀眼的将领，麾下战团越来越庞大，以铁腕与精准的战略在诺克萨斯的扩张战争中屡立奇功。作为家族族母，她在朝堂与战场两面经营，将家族势力推向顶峰。然而她的钢铁意志也让亲情付出了代价：与女儿梅尔的关系长期紧张------梅尔后来远走皮尔特沃夫成为议员，母女间的裂痕始终未愈。在《双城之战》事件中，她奉诺克萨斯之命亲临皮城，意图攫取海克斯科技武力，主张以铁与血解决双城争端，是一位令皮尔特沃夫与祖安都不敢小觑的诺克萨斯将军。",
    relations: "女儿梅尔·米达尔达（皮城议员）；米达尔达家族的族母；与诺克萨斯高层（如斯维因一系）同朝为臣，立场强硬。"
  },
  "贝蕾亚": {
    title: "狂厄蔷薇",
    englishName: "Briar",
    region: "诺克萨斯",
    race: "血魔法生命（由黑色玫瑰用血巫术创造的活体兵器）",
    personality: "天真、好奇、又极度嗜血；像个刚睁开眼的孩子一样贪婪地体验世界，一旦血瘾上头便化为失控的猎杀机器。",
    story: "在大统领勃朗·达克威尔统治的末期，他授意黑色玫瑰及其麾下的血巫师们秘密打造一种前所未有的活体兵器。与以往用死者尸体拼装的实验不同，这一次他们要创造出一种\"由血而生、以血为食\"的生命------一种不需要后勤补给、只要给个目标就能自行猎杀的完美刺客。贝蕾亚因此诞生。\n\n她的创造者们想要的是一个绝对服从的工具，可贝蕾亚自己想要的，只是吃、吃、吃。为了压制她不受控制的嗜血本能，黑色玫瑰给她戴上了一个特殊的囚枷，让她保持清醒。然而这种平衡非常脆弱：血瘾一旦被勾起，囚枷便难以约束她的狂暴。在一连串事件后，这具活体兵器终于冲破了多年监禁，闯入外面的世界。如今她不受任何人掌控，只凭自己对知识与鲜血的双重渴望行动------既好奇地打量着符文之地的一切新鲜事物，也随时可能在某个瞬间彻底放纵自己的猎杀本能。",
    relations: "创造者是诺克萨斯黑色玫瑰的血巫师（如乐芙兰一系）；曾受勃朗·达克威尔秘密授意；在诺克萨斯的政治阴谋中挣脱枷锁。"
  },
  "卡西奥佩娅": {
    title: "魔蛇之拥",
    englishName: "Cassiopeia",
    region: "诺克萨斯",
    race: "人类（被远古墓穴守卫毒化后变为蛇形掠食者）",
    personality: "美丽、狡黠、野心勃勃；把身边所有人都当作可利用的工具，为达目的不择手段。",
    story: "卡西奥佩娅是诺克萨斯杜·克卡奥将军家中最小、也最漂亮的女儿。姐姐卡特琳娜自幼随父亲习武，成为战场上的一柄利刃；卡西奥佩娅则追随母亲索莱安娜的脚步，小小年纪便在朝堂与阴谋中如鱼得水，连母亲都惊讶于她的冷酷与效率。尚未成年时，她就通过一连串不留痕迹的暗杀，为母亲清除了政敌，并借此被引荐进入黑色玫瑰。\n\n随父亲的军队远征恕瑞玛期间，她背叛了一位雇佣来的恕瑞玛向导，独自潜入传说中的远古墓穴，想要窃取其中沉眠的力量。然而墓穴深处的守卫------一条被远古魔法守护的石蜥------咬中了她。剧毒在她血管中蔓延，将她的下半身扭曲成蛇尾，也赋予了她用毒与催眠的可怕能力。如今的她半人半蛇，在夜幕掩护下蜿蜒滑行于恕瑞玛沙漠与诺克萨斯宫廷之间，继续以美貌与阴谋操纵他人，为自己谋求更大的权力。",
    relations: "父亲杜·克卡奥将军；母亲索莱安娜；姐姐卡特琳娜；与黑色玫瑰关系密切；被恕瑞玛墓穴守卫诅咒为蛇形。"
  },
  "德莱厄斯": {
    title: "诺克萨斯之手",
    englishName: "Darius",
    region: "诺克萨斯",
    race: "人类",
    personality: "铁血、强硬、绝不后退；视诺克萨斯的荣耀高于一切，对懦弱与腐败零容忍。",
    story: "德莱厄斯与弟弟德莱文自幼在贝西利科街头相依为命，父母早亡。家乡被诺克萨斯军队吞并后，兄弟俩因一次果敢的袭杀行动被诺克萨斯军官看中，由此加入帝国军队。德莱厄斯从最低等的列兵一路拼杀，凭一身蛮力与钢铁般的纪律成为诺克萨斯最令人畏惧的战士。\n\n在一次对瓦尔尤云堡艰苦卓绝的胜利之后，大统领勃朗·达克威尔亲自授予他\"诺克萨斯之手\"的头衔，命令他率军深入弗雷尔卓德，迫使野蛮人部落臣服。这场北地战争旷日持久，最终陷入冰冷的僵局。斯维因政变夺权之后，德莱厄斯虽对新政权的权术心存疑虑，却承认斯维因带来了诺克萨斯真正需要的方向。如今他仍站在帝国最前线，用手中那把巨斧砍倒一切阻挡诺克萨斯扩张的敌人------在他看来，任何后退都是对诺克萨斯的背叛。",
    relations: "弟弟德莱文（荣耀行刑官）；对大统领达克威尔曾效忠；与斯维因同朝为臣，立场微妙；诺克萨斯军方的象征。"
  },
  "德莱文": {
    title: "荣耀行刑官",
    englishName: "Draven",
    region: "诺克萨斯",
    race: "人类",
    personality: "自恋、张扬、热爱表演；把每一次杀戮都当作舞台上的高光时刻，渴望被万众欢呼。",
    story: "德莱文与哥哥德莱厄斯出身于贝西利科街头的孤儿家庭。两人在乱世中相互扶持才活了下来，家乡被诺克萨斯吞并后，他们一同加入了帝国军队。和哥哥在战场上默默拼杀不同，年轻的德莱文很快就发现自己真正的天赋不在军旅，而在舞台------他热爱被注视、被欢呼，享受每一个能展示自己的瞬间。\n\n军旅生涯无法满足他的表演欲，于是他转投诺克萨斯的监狱体系，成为一名行刑官。第一次行刑时，他让死囚逃跑，再在众目睽睽之下华丽地追上去将其斩杀，全场爆发出雷鸣般的欢呼。德莱文由此把例行公事变成了一场场盛大演出，并很快与一位角斗承办人合作，把竞技场与行刑结合起来------让罪犯在观众的喝彩中被他逐一处决。他不在乎忠诚与荣耀，只在乎\"德莱文\"这个名字能否在整个诺克萨斯被人高喊。",
    relations: "哥哥德莱厄斯（诺克萨斯之手，性格截然相反）；在诺克萨斯的竞技场与行刑场中成名；以观众的喝彩为最高追求。"
  },
  "卡特琳娜": {
    title: "不祥之刃",
    englishName: "Katarina",
    region: "诺克萨斯",
    race: "人类",
    personality: "骄傲、急性子、追求荣耀与证明自己；不愿被视为\"贵族小姐\"，渴望以刺客的刀功赢得帝国的认可；内心深埋对家族荣誉的执着。",
    story: "卡特琳娜·杜·克卡奥出身诺克萨斯最受尊敬的贵族之一，父亲是功勋卓著的杜·克卡奥将军，母亲则精于权谋政治。妹妹卡西奥佩娅继承了母亲的政治头脑，而卡特琳娜则更像父亲------她自幼便厌倦裙裾与珠宝，痴迷于刀剑。老谋深算的将军将她推上刺客之路，训练她不靠蛮力而靠致命精准成为帝国的利刃。\n\n她的第一个刺杀任务来自父亲本人：在一次西征前夜，她被指派去刺杀敌方一名出身低微的下级军官德米特里厄斯。这桩\"大材小用\"的任务让她怒不可遏------她认为自己的本事远不止于此。她擅自放弃了原定目标，转而刺杀敌方一位更高级别的将军，以为这样更能证明自己。然而她的自作主张导致了惨重后果：她原本的目标在当夜率奇袭反攻，诺克萨斯士兵伤亡惨重，其中包括一位曾救过她性命的老兵。这次失败让她明白了一个残酷的道理------个人荣耀必须让位于帝国大业。此后卡特琳娜潜心磨砺，成为诺克萨斯最令人闻风丧胆的刺客之一，与妹妹卡西奥佩娅因命运与立场的分道扬镳而渐行渐远。",
    relations: "父亲杜·克卡奥将军；妹妹卡西奥佩娅（魔蛇之拥）；与诺克萨斯刺客组织\"双生花\"有渊源；被她擅自放过的目标德米特里厄斯成为她心中的一道疤。"
  },
  "克烈": {
    title: "暴怒骑士",
    englishName: "Kled",
    region: "诺克萨斯",
    race: "约德尔人",
    personality: "暴躁、贪婪、睚眦必报，是诺克萨斯军队中最老牌的\"民族英雄\"；他自称的头衔长得离谱，对\"他的\"地盘与财物有着偏执的占有欲。",
    story: "克烈是诺克萨斯民间传说中最古老的战争英雄之一，关于他的故事甚至可以追溯到诺克萨斯建国之前。他是一名约德尔人，这意味着他的寿命远超凡人，但他本人对时间并不敏感。在帝国仍在襁褓的年代，征讨德鲁涅的战役中，他便已骑着他那只同样老迈的沙漠龙蜴\"斯嘎尔\"出现在战场上。从那以后，他出现在几乎每一场诺克萨斯对外扩张的战役中------只不过他参战的理由从来不是为了帝国，而是为了他认定\"属于自己\"的战利品、地盘和辎重。\n\n克烈在普通士兵中享有近乎神话的声望，许多老兵都声称自己曾与他并肩作战，这让将军们头疼不已。他的盔甲锈迹斑斑、衣衫褴褛，只有一只完好的眼珠里喷着鄙夷与怒火。他的坐骑斯嘎尔是一头性情胆小的沙漠龙蜴，打输了会丢下他逃跑，但克烈本人即便徒步也照样冲锋陷阵。在一次边境冲突中，他独自骑着斯嘎尔冲下山坡，向一整个野蛮人部落发出最后通牒------不等回答便直接杀了进去，这种疯狂正是克烈的本色。",
    relations: "坐骑斯嘎尔（沙漠龙蜴，胆小怯懦）；诺克萨斯帝国的\"非官方\"精神图腾；对帝国高层既蔑视又利用。"
  },
  "乐芙兰": {
    title: "诡术妖姬",
    englishName: "LeBlanc",
    region: "诺克萨斯",
    race: "人类（活了数百年的苍白女巫，真实身份成谜）",
    personality: "神秘、虚伪、操纵欲极强；她永远躲在幕后，用幻象与谎言塑造历史，连她自己都可能已分不清哪个才是\"真正的\"她。",
    story: "乐芙兰是秘密教团\"黑色玫瑰\"的创立者与至高领袖。黑色玫瑰的历史远比诺克萨斯帝国本身更古老，它源自一个早已消逝的古代法师教团的残部。成员们大多只知道关于一位\"苍白女巫\"的传说------据说她曾在远古时代联合分崩离析的诺克萨斯蛮族部落，背叛并推翻了暴虐的铁铠冥魂莫德凯撒。\n\n正是在这场推翻莫德凯撒的起义之后，乐芙兰与黑色玫瑰占据了莫德凯撒留下的不朽堡垒，将其建为诺克萨斯帝国的中心。然而她并没有走到台前，而是选择藏在贵族社会的表象之下，一代代操纵诺克萨斯的权贵、继承人与政治走向。她能用魔法制造自己的镜像，同时出现在许多地方，\"乐芙兰\"这个名字本身也只是她无数化名之一。数百年来，她一手策划了无数事件，将符文之地反复推向战争边缘，其真实动机至今无人能完全参透------或许连她自己也已在无尽的伪装中迷失。",
    relations: "黑色玫瑰教团的首领；与弗拉基米尔（血法师，同属诺克萨斯古老秘密阵营）既有合作又有对立；是推翻莫德凯撒的关键人物之一；在斯维因政变后，她与新的诺克萨斯领导层展开暗线博弈。"
  },
  "梅尔": {
    title: "流光镜影",
    englishName: "Mel",
    region: "诺克萨斯",
    race: "人类",
    personality: "优雅、精明、善于权谋；台前是温柔的贵族小姐，幕后是能在皮尔特沃夫议会翻云覆雨的政治家，内心深处却始终在寻求母亲安蓓萨的认可。",
    story: "梅尔·米达尔达是诺克萨斯旧贵族米达尔达家族的第一顺位继承人。她的母亲安蓓萨是诺克萨斯最令人畏惧的将军之一，奉行\"恶狼之道\"。梅尔自幼便被母亲视为不够强悍------在安蓓萨看来，这个女儿过于柔软、不够冷酷，于是将她送往皮尔特沃夫，近乎流放地让她在那里的贵族社会中自行成长。\n\n梅尔在皮尔特沃夫凭借天赋与手腕迅速崛起，成为皮城议会中最有影响力的议员之一。她台前优雅、幕后深谙权术，对身边每个人、每件事都了如指掌并加以利用。在《双城之战》的故事中，她与杰斯等皮城高层并肩，在皮尔特沃夫与祖安的紧张关系中周旋。然而当她的母亲安蓓萨亲自率诺克萨斯舰队抵达皮城时，梅尔被迫面对自己出身的阴影。更令她震惊的是，她接触到了神秘的\"黑色玫瑰\"------在那之后，她发现了母亲编织的层层谎言，也第一次让局势超出了自己的掌控。她体内沉睡的魔法在这一过程中觉醒，她不得不面对一个全新的自己：一个不再只是母亲棋盘上的棋子，而是必须为自己、为皮尔特沃夫做出抉择的人。",
    relations: "母亲安蓓萨（诺克萨斯将军，米达尔达家族族母）；在皮尔特沃夫议会与杰斯、维克托等人有合作交集；与黑色玫瑰有过接触并因此觉醒魔法；被官方列为诺克萨斯阵营英雄。"
  },
  "莫德凯撒": {
    title: "铁铠冥魂",
    englishName: "Mordekaiser",
    region: "诺克萨斯",
    race: "死灵（被封入黑铁板甲的远古暴君灵魂）",
    personality: "冷酷、残暴而极具统治欲；他不满足于统治活人的世界，更要在死后的领域建立自己的冥国，是符文之地最接近\"魔神\"的存在之一。",
    story: "莫德凯撒本名萨恩·乌祖尔，是诺克萨斯土地上远早于帝国的远古暴君。他生前便是一位铁腕征服者，在一场与某种灵界存在（传闻是恶魔拉\nMundus）的交易中获得了不死之力。他在生前便建立了一座庞大的要塞------后来被称为不朽堡垒------并将自己的骸骨封藏其中。他死于一场被部下背叛的叛乱，但他与黑暗力量订下的契约让他数次复活。\n\n他第二次死后，一伙巫师为了在自己的战争中借刀杀人，将他的灵魂重新召唤回生者世界。他没有血肉骸骨，便让巫师为他铸造了一副与他生前穿着一模一样的黑铁板甲，将灵魂封入其中。无情的铁铠冥魂就此诞生。他一复活便当场处决了所有召唤他的巫师，继续他征服世界的野心。然而他最终再次被诺克萨斯诸部落联合击败------那次起义的幕后推手之一正是乐芙兰的黑色玫瑰。如今他被封印在不朽堡垒之下，诺克萨斯历代统治者都不知道自己王座下封着这位远古暴君。但莫德凯撒的灵魂从未真正消散，他一直在等待卷土重来的那一天------他要在生者与死者的两个世界都建立属于自己的帝国。",
    relations: "不朽堡垒（他生前的王座，现为诺克萨斯帝国中心）；乐芙兰与黑色玫瑰曾参与推翻他；他与恶魔拉\nMundus\n有古老契约；斯维因在不朽堡垒中曾与某种黑暗存在交易（疑似与莫德凯撒有关）。"
  },
  "芮尔": {
    title: "镕铁少女",
    englishName: "Rell",
    region: "诺克萨斯",
    race: "人类（天生可操控金属的魔法师）",
    personality: "桀骜、愤怒、自带被虐待者的戾气；对诺克萨斯一切权力机构怀着刻骨的仇恨。",
    story: "芮尔是诺克萨斯一名士兵与破落贵族之女。父母对她从未有过温情，只把她当作一件能打破诺克萨斯层层政治版图的工具。她日益增长的不快，意外点燃了一种数百年未见的魔法------操控金属的能力。\n\n一位面色苍白的女士（黑色玫瑰的使者）找上门来，与她父母做了一笔黑暗交易。芮尔被送进一座远离首都、远离议会视线的秘密寄宿学院，成为\"明星学徒\"。在那里，她与其他被诱拐的孩子一同成为黑色玫瑰残酷实验的对象：他们的魔法被强行抽取、互相灌注，只为打造一把能对抗诺克萨斯最古老仇敌的活体武器。\n\n多年虐待之后，芮尔终于爆发，以金属之力从看管者中杀出一条血路，毁掉学院逃走。如今她被诺克萨斯认定为逃犯，骑着一匹金属战马在大路上游荡，见诺克萨斯士兵便杀，誓言要颠覆这个把她造出来的帝国。",
    relations: "父母（把她卖给黑色玫瑰）；黑色玫瑰（实验者与仇敌）；与其他逃出学院的孩子同病相怜；诺克萨斯当局的通缉对象。"
  },
  "锐雯": {
    title: "放逐之刃",
    englishName: "Riven",
    region: "诺克萨斯",
    race: "人类",
    personality: "曾经铁血忠诚，如今在愧疚与寻找中煎熬；刚毅、自律，对自己的过去无法原谅。",
    story: "锐雯出身诺克萨斯，以信念之力和铁血效率在军中一路晋升，被达克威尔赐予一把传奇符文巨剑和一支自己统领的战团。她曾坚信诺克萨斯的扩张使命。\n\n在艾欧尼亚前线，她的信仰被粉碎：一次诺克萨斯的战幕中，她被自己的帝国抛弃------化学与符文武器不分敌我地砸向她的战团，她为了不被俘虏，亲手在一座艾欧尼亚村落前砸碎了自己的符文巨剑，切断与帝国的一切联系。\n\n失去信仰的锐雯自我放逐，在被战火蹂躏的艾欧尼亚大地上流浪。她后来回到当年碎剑的村落，才发现她毁剑时的冲击波害死了村里最受尊敬的长老------但艾欧尼亚人以宽恕之心接纳了她。诺克萨斯却没有：帝国没有忘记她，也没有忘记那把符文巨剑。她最终被诺克萨斯当局以枷锁引渡回国，面对昔日祖国的审判。",
    relations: "曾受达克威尔赐剑；与诺克萨斯军方决裂；在艾欧尼亚村落与被她误害的长老家人有过和解；与亚索等艾欧尼亚武者有过交集。"
  },
  "莎弥拉": {
    title: "荒漠玫瑰",
    englishName: "Samira",
    region: "诺克萨斯",
    race: "人类",
    personality: "鲁莽、自信、热爱冒险，以挑战死亡为乐；因幼年经历过无助与恐惧，立誓永不再被恐惧支配，行事张扬而不拘小节。",
    story: "莎弥拉出生于恕瑞玛的一个普通家庭，自幼便是胆大顽皮的孩子，酷爱各种惊险刺激的尝试。然而在她幼年时，一伙流寇血洗了她的家乡，父母惨遭杀害。她当时因害怕而躲了起来，事后却对自己的懦弱感到无比愤怒，立誓永不再体会那种无助与恐惧。她随少数幸存者逃到诺克萨斯统治下的港口城市贝尔祖恩。\n\n在那里，莎弥拉偶然遇见诺克萨斯战团正在征兵，军队提供的刺激与报酬对她极具吸引力，于是应征入伍。她的身体素质令同届士兵惊叹，刀剑枪术皆精，唯独不守纪律。两年训练后，她的鲁莽导致同袍伤亡惨重，被逐出军队。但她并未因此消沉，反而以自由佣兵的身份继续行动，专门承接诺克萨斯最高规格的凶险任务，逐渐建立起\"孤胆女将\"的威名。她使用黑火药双枪与一把特制大刀，在生死一线的关头最为勇猛，以闪钢般的自信直视死亡。",
    relations: "故乡被毁于流寇之手；在诺克萨斯军中以莽撞著称，与纪律格格不入；现以自由佣兵身份为诺克萨斯执行最危险的任务。"
  },
  "赛恩": {
    title: "亡灵勇士",
    englishName: "Sion",
    region: "诺克萨斯",
    race: "亡灵（被黑魔法复活的远古诺克萨斯战士）",
    personality: "狂暴、无差别的杀戮机器；几乎尽失人性，只凭残存的战争本能冲锋陷阵，敌我不分。",
    story: "一百多年前，诺克萨斯尚在草创之际，赛恩便是那个时代最残暴的军阀。他代表了诺克萨斯尚武文化的最后荣光------这种文化自帝国建立之初便深植其中。赛恩曾对先祖发誓，绝不在战场上后退半步，当死期来临时将光荣战死。他的战斗方式粗暴而致命，手中巨斧\"切削者\"收割了无数性命。\n\n赛恩最辉煌的战绩，是在战场上徒手掐死了一位德玛西亚国王------这一战让他名震两国。然而他最终也在与德玛西亚的战争中被俘，随后被处死。但诺克萨斯的法师们不愿浪费这台战争机器，他们用黑暗的炼金术将赛恩复活，把他腐朽的躯体钉上粗糙的装甲，让他再度冲上战场。复活后的赛恩几乎失去了所有的人性，他无差别地屠杀一切挡路之人，无论敌我。他被当作人体攻城槌，在诺克萨斯军队最前方开路。如今，赛恩作为帝国最古老的战争遗产之一，依然被驱使着踏上战场，在疯狂的冲锋中寻找他永远无法获得的死亡安宁。",
    relations: "曾徒手掐死一位德玛西亚国王；被诺克萨斯黑魔法复活后继续为帝国效命；是诺克萨斯尚武传统的远古遗存。"
  },
  "斯维因": {
    title: "诺克萨斯统领",
    englishName: "Swain",
    region: "诺克萨斯",
    race: "人类（与恶魔拉赫拉克缔结契约后获得恶魔之手）",
    personality: "深谋远虑、冷酷无情而高瞻远瞩；以团结之力重塑诺克萨斯为愿景，行事果断，为达目的不择手段。",
    story: "杰里柯·斯维因出身于诺克萨斯的名门贵族，这个家族自诺克萨斯筑城之初便已是权贵。他本应过着特权生活，但年轻的斯维因并不满足于家族的荣耀。他投身军旅，在诺克萨斯入侵艾欧尼亚的战争中崭露头角。然而在一场战役中，他遭遇惨败，不仅失去了左臂，还被从前线撤回。在达克威尔暴君眼中，他成了一个无用的残废。\n\n坠入谷底的斯维因在艾欧尼亚的森林深处遇到了恶魔拉赫拉克。恶魔向他展示了一种操纵暗影之力的方式，并以力量为代价与他缔结契约。斯维因获得了一只由恶魔重塑的手臂，以及看穿黑影中秘密的能力。他花了多年时间精心策划，联络对达克威尔不满的势力，最终在一个夜晚发动政变------他当着所有追随者的面碾碎了老国王达克威尔，王座支离破碎。如今斯维因以\"诺克萨斯统领\"的身份执掌帝国，他撤回了远征军团，结束了达克威尔那些毫无胜算的战争，建立了\"三元合议\"体制，以团结之力凝聚诺克萨斯。他如今亲自在前线指挥，对抗着只有他才能通过恶魔之眼看到的压境黑暗。",
    relations: "推翻老国王博拉姆·达克威尔；与恶魔拉赫拉克缔结契约获得恶魔之手与暗影视野；建立三元合议体制，与德莱厄斯、乐芙兰等共同执掌诺克萨斯。"
  },
  "泰隆": {
    title: "刀锋之影",
    englishName: "Talon",
    region: "诺克萨斯",
    race: "人类",
    personality: "沉默、警惕而高效；在诺克萨斯底层社会摸爬滚打长大，只信任手中的钢刀与背后的墙壁，对杜·克卡奥家族怀有复杂的忠诚。",
    story: "泰隆最早的记忆，是诺克萨斯错综复杂的地下通道，以及身旁那把令人安心的钢刀。他不记得自己的家人、童年或任何温暖的事物，偷来的金币碰撞声和背靠墙壁的安全感，就是他唯一渴求过的亲情。他仅凭急智与灵巧的身手在诺克萨斯破旧的下层社会勉强度日，对刀刃的精通让他很快成为一个令人忌惮的存在。\n\n诺克萨斯的刺客行会们注意到了他，派出刺客要求他加入------否则就死。泰隆将来者的尸体统统丢进了诺克萨斯护城河作为回答。然而刺杀变得越来越危险，直到一名杜·克卡奥家族的杀手与他在决斗中击败了他。泰隆本以为自己必死无疑，但那位刺客却没有杀他，而是将他收编。从此泰隆为诺克萨斯最声名显赫的刺客家族杜·克卡奥效力，奉帝国之命刺杀敌方领袖、军官与英雄。他是黑暗中的那把刀，能在任何警报响起之前出手并消失无踪。",
    relations: "身世成谜，最早记忆是诺克萨斯地下通道；被杜·克卡奥家族的刺客击败后收编，效忠于该家族；与卡特琳娜同属杜·克卡奥体系。"
  },
  "弗拉基米尔": {
    title: "猩红收割者",
    englishName: "Vladimir",
    region: "诺克萨斯",
    race: "人类（以血巫术延寿的远古术士）",
    personality: "优雅、傲慢、沉溺于血与美色；在诺克萨斯贵族沙龙中如鱼得水，在底层后巷里则是吸干敌人鲜血的掠食者；活了上千年，心智却仍如凡人般反复无常。",
    story: "作为一名远古禁忌巫术的大师，弗拉基米尔是诺克萨斯最古老的谜团之一。他在帝国的萌芽时期就已现身，后来将自己的影响深深植入帝国的根基------但他几乎不记得那段时光。他的心智与凡人无异，因此他非自然延长的寿命并没有留存于记忆，而是留存于历史。\n\n他十几岁时便曾残暴地杀死两个同龄男孩，仅仅因为享受观看鲜血喷涌的快感。他很快意识到自己杀戮的欲望无法抑制，如果留在诺克萨斯早晚会受罚，于是毫不犹豫地离开城邦，南下追寻血巫术的源头。他在南方的破碎石坛旁遇到了一群同样修习禁忌血魔法的法师，在那里学到了以鲜血延寿、操控他人身体与思想的技艺。\n\n数百年间，他多次在历史记录中\"消失\"，又多次以不同身份重新出现。他与一批同样古老的法师组成了一个秘密结社------\"黑玫瑰\"，这个小圈子在千年时间里暗中操控着诺克萨斯王座，实现帝国最野心勃勃的计划。弗拉基米尔是黑玫瑰领袖中唯一不愿躲在阴影里的人，他乐于在诺克萨斯宫廷最风云变幻的时刻现身，以年轻贵族的身份周旋于权力中心。\n\n如今他在诺克萨斯贵族奢华的沙龙聚会上建立起狂热的教众，在底层后巷里则吸干敌人的鲜血。他与乐芙兰同为黑玫瑰核心，却在帝国政治上各怀心思；他的血巫术既让他青春永驻，也让他成为诺克萨斯最令人忌惮的存在之一。",
    relations: "黑玫瑰结社的核心成员，与乐芙兰同为诺克萨斯幕后操纵者；千年来在诺克萨斯宫廷以不同身份现身；与南方血巫术传统有渊源；在诺克萨斯贵族中拥有狂热追随者。"
  },
  "菲奥娜": {
    title: "无双剑姬",
    englishName: "Fiora",
    region: "德玛西亚",
    race: "人类",
    personality: "骄傲、直率、不屈服于命运；信奉荣誉与剑术，宁愿决斗也不肯被安排人生。",
    story: "菲奥娜是德玛西亚贵族劳伦特家的小女儿，本被当作政治联姻的棋子。她从小便逆反：把母亲的洋娃娃送给侍女，偷拿长兄佩剑逼他教剑；把父亲请来裁缝做的华服当作突刺与格挡的靶。十八岁生日后，家族仍为她安排了与冕卫家族旁系的婚事，国王嘉文三世将亲临。\n\n婚礼当天，菲奥娜当众宣布宁死也不愿别人决定自己的人生，令未婚夫蒙羞。对方家族要求以死亡决斗了断，父亲塞巴斯蒂安却代表女儿出战------他在决斗前夜企图毒倒对手钝化其反应，被当场抓获，依荣誉守则将处绞刑。行刑前夜菲奥娜入牢探望，次日跪在国王面前接过佩剑，以劳伦特家主的身份执行正义裁决：她含泪亲手将剑刺入父亲心脏。\n\n丑闻并未平息，宫中谣传她篡夺兄长继承权。菲奥娜转而向全族敞开大门，接纳远房剑术同门、授予家臣贵族身份，把劳伦特家打造成王国最精湛的剑术门第。她主张击剑决斗是古老艺术，并不一定非要以死分胜负------若有人不同意，她很乐意在实战中试探对方赴死的决心。",
    relations: "父亲塞巴斯蒂安（被她依法裁决处死）；与冕卫家族（盖伦、嘉文四世所在家族）有联姻旧怨；劳伦特剑术传承者。"
  },
  "加里奥": {
    title: "正义巨像",
    englishName: "Galio",
    region: "德玛西亚",
    race: "禁魔石构造体（吸纳魔法而苏醒的石像哨兵）",
    personality: "沉静、孤独，在漫长休眠中观察凡人；渴望战斗，更逐渐把保护德玛西亚人民视为战斗的意义。",
    story: "加里奥的传奇可追溯到符文战争余波。相传一群难民被黑魔法师追杀，躲进一片树木已化石化的古林，发现化石能屏蔽一切法术，遂反杀追兵。定居者把这种化石与石灰混合，制成抗魔法的\"禁魔石\"，筑起摇篮中的德玛西亚。\n\n为让禁魔城墙也能上前线，雕塑家杜朗受托用禁魔石雕出宏伟展翅的巨像加里奥，靠滑轮、钢轨与公牛推上战场。他被称作\"吃魔法的巨人\"，未发一兵便常令强敌呆若木鸡，却无人想过经年累月作用于他身上的奥能会有何后果。\n\n在绿齿峰与\"奥法之拳\"法师团十三昼夜的轰炸中，幸存士兵缩在加里奥脚下万念俱灰，巨像却低沉轰鸣着自己站起：长年吸纳的魔法让他活了过来。他挺身挡下全部魔法弹，走下山坡把法师团拍进泥土，战后又骤然静止。此后数百年，他只在魔法汇聚时短暂苏醒，看着凡人一代代生老病死，渐渐懂得人类脆弱而短暂------战斗曾是他的渴望，如今人民才是他战斗的意义。他最深的愿望，是获得一次足以让他永远不必再沉睡的巨量魔法。",
    relations: "出自雕塑家杜朗之手；作为德玛西亚王国的石质哨兵与军队、盖伦等并立；与拉克丝的魔法遥相呼应。"
  },
  "盖伦": {
    title: "德玛西亚之力",
    englishName: "Garen",
    region: "德玛西亚",
    race: "人类",
    personality: "忠诚、骄傲而正直，将荣誉与职责置于一切之上；坚信魔法是德玛西亚最大的威胁，对操纵魔法之人怀有深深警惕。",
    story: "盖伦出身德玛西亚高贵的冕卫家族，父亲皮特是功勋卓著的军官，姑妈缇亚娜是无畏先锋的剑士长，妹妹拉克丝身负魔法天赋。他自幼便明白自己身负众望，理应用生命捍卫德玛西亚的皇权与理念。十二岁时，他离开银峰镇的家加入军队，在严苛训练中成长为无畏先锋最前沿的战士，深受战友爱戴、也受敌人尊敬。\n\n他坚信魔法是德玛西亚最大的威胁，于是身披抵御魔法的重甲、手持阔剑，在战场上正面迎战一切操纵魔法的狂人。当法师塞拉斯掀起反抗德玛西亚的起义时，盖伦率军与其正面对峙------塞拉斯窃取了他的力量，也撕开了他心中关于魔法与信念的裂痕；与此同时，妹妹拉克丝隐藏的魔法秘密也让他陷入忠诚与亲情的两难。他越是被战友奉为无畏先锋的旗帜，就越难回避起义所撕开的真相：这座国家赖以立国的反魔法立场，本身也在把无辜者推向对立面。",
    relations: "妹妹拉克丝（隐藏魔法天赋）；父亲皮特、姑妈缇亚娜（无畏先锋剑士长）；与嘉文四世、赵信同袍；与塞拉斯互为宿敌。"
  },
  "嘉文四世": {
    title: "德玛西亚皇子",
    englishName: "Jarvan IV",
    region: "德玛西亚",
    race: "人类",
    personality: "骄傲、坚韧、重责任；急于证明自己，又在边境血战中学会众志成城、抛弃成见。",
    story: "嘉文三世加冕后以联姻结束贵族内斗，迎娶深得民心的凯瑟琳。王后难产而死，独子以祖父之名嘉文，被国王倾注全部希望。没有母亲记忆的他在宫廷长大，由国王总管、来自艾欧尼亚的赵信传授兵法与灵力之道；又结识冕卫家族的盖伦，二人形影不离。\n\n成年后他被任命为银翼龙禽骑兵指挥官，却执意亲赴烁银山脉另一侧、诺克萨斯拉锯的边境前哨------他的曾祖正死于两国首次交锋。一次弩砲突袭中他坠鞍重伤，濒死之际被紫色皮肤的奇异女子希瓦娜救回伦沃尔旧堡。希瓦娜正因半龙之身被元素巨龙伊瓦追捕；当巨龙来袭，嘉文带病提枪守住阵线，希瓦娜则化身半龙将其斩杀。\n\n他拖着魔龙头骨凯旋，向希瓦娜许诺卫兵之位。如今盖伦已是无畏先锋剑士长，嘉文在军中与国事间渐挑大梁，终有一天他将怀着沉重心情加冕，成为真正的嘉文四世。",
    relations: "父嘉文三世、母凯瑟琳（难产而亡）；师长赵信；挚友盖伦；护卫希瓦娜（半龙女子）。"
  },
  "凯尔": {
    title: "审判天使",
    englishName: "Kayle",
    region: "德玛西亚",
    race: "翼族（正义星灵的凡人载体，与妹妹莫甘娜为孪生姐妹）",
    personality: "极端正义、冷酷而不容妥协，视法律与审判为绝对；对凡人反复犯错深感失望，最终选择抛弃德玛西亚。",
    story: "在符文战争最激烈的年代，巨神峰之巅伫立着一道抵御黑暗的光明灯塔。凡人弥希拉与齐拉姆为了拯救自己的部族，踏上登顶巨神峰的艰险试炼。弥希拉在登顶途中发现自己已有身孕，但她坚持前行。在峰顶，她被正义星灵选中，获得了星灵的力量与圣火之翼。不久后，一对孪生姐妹降生------姐姐凯尔先出世，如光明化身；妹妹莫甘娜紧随其后。\n\n姐妹二人随母亲来到凡世，在战乱中拯救了无数生命，被奉为德玛西亚的\"飞翼保护神\"。凯尔高举圣火长剑，以铁腕审判不义；莫甘娜则为那些愿意赎罪的人求情。然而凯尔的理想日益极端，她无法原谅凡人的反复犯错与背叛。最终，在与妹妹因理念彻底决裂之后，凯尔的信仰崩塌------她认为德玛西亚人不配得到她的守护。她展翅冲天，彻底离开了这个国度，只留下用火焰长剑审判罪人的传说，以及关于她终将归来的渺茫希望。",
    relations: "孪生妹妹莫甘娜（与她理念决裂、被她抛弃）；母亲弥希拉（正义星灵载体）；父亲齐拉姆（凡人）；德玛西亚人曾视她为守护神。"
  },
  "洛克": {
    title: "灰烬驱魔人",
    englishName: "Locke",
    region: "德玛西亚",
    race: "人类",
    personality: "冷峻、锐利、带着一种宗教审判官式的偏执；他不憎恨恶魔，而是憎恨人类自身的虚伪------因为在他看来，恶魔不过是人心黑暗结出的果实。",
    story: "考文·洛克出身于德玛西亚一个神秘的秘教术士世家。在德玛西亚这个公开排斥魔法的国度里，他的家族却世代在阴影中修习禁忌秘术。洛克生于谎言与虚伪之中，从小便在一个充满欺骗与功能失调的环境中长大------他被训练猎杀恶魔与邪物，却也在这个过程中逐渐悟出一个令他自己都震惊的道理：恶魔并不是人类堕落的原因，而是人类堕落的必然结果。\n\n他以符文铁钉为武器，精通各类禁忌驱魔仪式。面对那些道貌岸然的伪善者，他会毫不犹豫地撕开他们的灵魂，暴露出其中隐藏的谎言与黑暗。他相信这个世界必须变得更加真实------驱魔只是一个开始。作为2026年新登场的英雄，洛克的官方传记目前仍在逐步扩充中，他的具体家族背景、与德玛西亚现有法师议题（塞拉斯起义之后的法师政策）的关系，以及他所对抗的恶魔具体身份，都将在后续宇宙内容中逐步展开。",
    relations: "出身于德玛西亚秘教术士家族；以驱魔师身份活动，与德玛西亚官方反魔法秩序之间存在微妙张力；具体人物关系待官方后续补充。"
  },
  "拉克丝": {
    title: "光辉女郎",
    englishName: "Lux",
    region: "德玛西亚",
    race: "人类",
    personality: "聪慧、活泼而充满理想主义；身为贵族却内心善良，因身负魔法天赋而长期活在秘密与身份撕裂的痛苦中。",
    story: "拉克珊娜·冕卫------她更喜欢别人叫她拉克丝------在德玛西亚密银城长大，与哥哥盖伦一同出身于世代守护德玛西亚国王的冕卫家族。祖父曾在风暴之牙战役中救下国王，姑妈缇亚娜在她出生前便被任命为无畏先锋的指挥官。盖伦毫不犹豫地扛起了家族的军事传统，拉克丝却天资聪慧、求知欲旺盛，被送进精英学校接受贵族教育。\n\n然而少女时代的拉克丝发现自己拥有一种与生俱来的光明魔法------在一个以禁魔立国、用\npetricite（禁魔石）压制一切魔法的国度里，这是足以被定罪的秘密。她起初试图隐藏，却在一次意外中泄露了力量，被迫学会在贵族社交圈与地下法师之间双面生活。她与被囚禁的法师塞拉斯相遇，一度成为他与德玛西亚法师地下网络之间的纽带；塞拉斯起义后，德玛西亚陷入动荡，拉克丝站在哥哥盖伦与被压迫的法师群体之间，艰难地寻找第三条路。她是冕卫家族中唯一公开接受自己魔法天赋的人，也正因如此，她在德玛西亚的未来走向中扮演着关键角色。",
    relations: "哥哥盖伦（德玛西亚之力，对魔法持警惕态度）；姑妈缇亚娜（无畏先锋指挥官）；与塞拉斯（被囚法师，利用过她）有复杂交集；在德玛西亚法师地下网络中既是秘密的一员也是贵族。"
  },
  "莫甘娜": {
    title: "堕落天使",
    englishName: "Morgana",
    region: "德玛西亚",
    race: "半天界存在（与姐姐凯尔同为星灵力量与凡人之躯结合的双子）",
    personality: "愤世嫉俗、坚忍而慈悲，坚信人性可赎；痛恨虚伪的王权与神化，甘愿以黑翼自缚，为被压迫者扛下不公。",
    story: "莫甘娜与姐姐凯尔降生在符文战争的乱世。她们的双亲弥希拉与齐拉姆为拯救部族，登上巨神峰寻求星灵之力，归来时弥希拉已被天界力量占据，腹中怀上双子。姐妹自幼在神力与凡人情感的撕扯中长大，莫甘娜眷恋母亲的人性，凯尔则追随父亲般的星灵威严。\n\n后来姐妹随部族北迁，在尚未建城的德玛西亚海岸落足。当流亡者们以禁魔石筑起城邦、驱逐魔法时，莫甘娜站出来为被放逐者辩护，而凯尔主张以铁腕净化一切魔法。两姐妹在一场惊天的决斗中决裂，莫甘娜自缚黑翼，拒绝飞升；凯尔则舍弃肉身，升入天界。\n\n此后莫甘娜隐身于德玛西亚的阴影中，默默庇护被王国流放的法师与罪人，用暗焰锁链与盾牌惩戒那些失信堕落的权贵。她等待着，等待这个王国终于配得上宽恕的那一天。",
    relations: "双胞胎姐姐凯尔（决裂的宿敌）；母亲弥希拉（被星灵占据的凡人）、父亲齐拉姆；与德玛西亚王室及禁魔石律法对立。"
  },
  "波比": {
    title: "圣锤之毅",
    englishName: "Poppy",
    region: "德玛西亚",
    race: "约德尔人",
    personality: "执拗、认真、一本正经；对\"德玛西亚英雄\"的传说深信不疑，却从未意识到自己早已就是那个人。",
    story: "波比是个意志坚决的约德尔人，多年前追随德玛西亚将领奥伦。奥伦是德玛西亚的建立者之一，临终前把一柄长度两倍于她的传奇圣锤交到她手上，告诉她：这把锤真正的主人是\"德玛西亚英雄\"------唯一能唤醒全部神力、带领王国走向伟大的人。直到奥伦弥留之际，才向她道出这柄锤的来历与托付之意。\n\n奥伦死后，波比信守诺言，带着圣锤离开军团，在符文之地漫游无数岁月，寻找那位传说中的英雄。她一路遇上恶狼、强盗、外敌入侵，便挥舞着与自己身高不成比例的大锤，不由自主地把敌人打退。\n\n她始终认定自己只是个\"送信人\"，每一个她遇到的强者都被她怀疑是传说中的英雄；而在所有人眼中，这个挥舞巨锤、沉默寡言的小个子约德尔人，本身就是德玛西亚最传奇的英雄。",
    relations: "德玛西亚建立者奥伦（临终托付圣锤）；在德玛西亚军中曾服役；与盖伦等德玛西亚战士彼此闻名却未谋面。"
  },
  "奎因": {
    title: "德玛西亚之翼",
    englishName: "Quinn",
    region: "德玛西亚",
    race: "人类",
    personality: "坚毅、冷静、可靠，是深入敌后的斥候典范；与巨鹰华洛之间有牢不可破的生死默契。",
    story: "奎因与孪生兄弟卡莱布出生在德玛西亚东北山乡厄文戴尔，是由游猎手守护的狩猎农耕村庄。少年时嘉文三世国王途经此地前往东部长城视察，随行骑士甲胄辉烁、英姿飒爽，让兄妹俩埋下了从军的梦。\n\n成年后两人一同报名参军，却在一次进山训练中遭遇悲剧：一头巨鹰袭击了他们，卡莱布为保护妹妹而死，奎因重伤生还。她一度放弃骑士梦，却在事故周年那天重返事发地点，再次遇见那头巨鹰。\n\n这一次她没有举箭，而是与鹰对峙、彼此理解。这头鹰后来被她命名为华洛，二者结成德玛西亚军中独一无二的搭档。她以布维尔家族资助的游骑兵身份，经常深入诺克萨斯等敌国腹地执行最危险的侦察与狙击任务------很多时候，她的对手到死都没意识到自己面对的德玛西亚英雄并非孤军奋战。",
    relations: "孪生兄弟卡莱布（死于山难）；巨鹰华洛（生死搭档）；德玛西亚游骑兵；与嘉文三世王室有旧缘。"
  },
  "希瓦娜": {
    title: "半龙少女",
    englishName: "Shyvana",
    region: "德玛西亚",
    race: "半龙（人类法师与巨龙的混血）",
    personality: "孤傲、刚烈而忠诚；因半龙身份在多疑的德玛西亚人中艰难寻求接纳，内心渴望归属与认可。",
    story: "希瓦娜的诞生源于一段不凡的结合。一位德玛西亚法师从龙巢中偷走了一颗龙蛋，本打算将其作为奥术研究的材料。然而蛋壳中孵出的并非幼龙，而是一个看似人类、肌肤苍白透紫的女婴。法师无法忍心抛弃她，便将她当作自己的女儿抚养，以她生母那段黑暗传说为她取名希瓦娜------她的生母是一头名为伊瓦的远古巨龙。\n\n随着成长，希瓦娜逐渐显露出非凡的能力：她可以在人形与龙形之间切换，喷出龙息烈焰。在她的养父去世后，生母伊瓦循着血脉的气息找到了她，意图将这个混血女儿吞噬以恢复自己的力量。就在此时，德玛西亚皇子嘉文四世率军途经此地，希瓦娜挺身而出，在空中化为巨龙之姿与伊瓦展开对决。经过惨烈的搏斗，遍体鳞伤的希瓦娜将生母拖到地面，拧断了她的脖颈。嘉文四世亲自嘉奖了她的英勇，并将她纳入自己的卫队。如今希瓦娜效力于德玛西亚宫廷，在这个对魔法充满戒心的国度里，兢兢业业地寻求被接纳的可能。",
    relations: "养父为德玛西亚法师（偷走龙蛋后将她养大）；生母伊瓦（远古巨龙，被她亲手斩杀）；效忠德玛西亚皇子嘉文四世。"
  },
  "娑娜": {
    title: "琴瑟仙女",
    englishName: "Sona",
    region: "德玛西亚",
    race: "人类（沉默的魔法师）",
    personality: "文雅、内敛而神秘；以琴声代替言语，在外人面前沉默寡言，最亲密的同伴却能读懂她的每一个和弦。",
    story: "娑娜从小在艾欧尼亚的一所修道院孤儿院中长大。与其他被遗弃的孤儿不同，她被送来时并非两手空空------她身边带着一件用简朴木匣装着的奇特弦乐器。前来修道院的音乐教师与乐师们都无法辨认这件乐器，有几人还试图据为己有，但每次都无功而返。娑娜从不开口说话，但她似乎能与这件名为\"叆华\"的乐器心意相通，拨弄它时便能奏出天籁般的旋律。\n\n后来，德玛西亚贵妇人乐斯塔拉·布维尔听闻了这把古琴与娑娜的奇事，亲自来到艾欧尼亚。她在孤儿院中遍寻之后，驻足在娑娜的房门外，毫不犹豫地收养了她，并重金买下了那件乐器。娑娜随乐斯塔拉回到德玛西亚，在贵族阶层中以叆华的优美和弦与人交流。然而有人猜测她迷人的旋律其实是在施放魔法------这在严禁魔法的德玛西亚是如履薄冰的禁忌。娑娜的叆华不仅能安抚受伤的盟友，也能化为致命的武器。在德玛西亚因塞拉斯起义而陷入动荡的时代，娑娜必须小心隐藏自己的魔法本质，同时用琴声守护她所珍视的人。",
    relations: "在艾欧尼亚修道院孤儿院长大；被德玛西亚贵妇人乐斯塔拉·布维尔收养并训练琴技；神秘乐器\"叆华\"与她心意相通。"
  },
  "塞拉斯": {
    title: "解脱者",
    englishName: "Sylas",
    region: "德玛西亚",
    race: "人类（法师，拥有感知并窃取魔法的天赋）",
    personality: "坚韧、愤恨而极具煽动性；从德玛西亚体制的受害者变为反抗者，誓要摧毁自己曾经侍奉过的王国，为被压迫的法师争取自由。",
    story: "塞拉斯出身于德玛西亚边沟镇的一个贫苦家庭。作为一个天生的法师，他在这个以禁魔为立国之本的国度里几乎从出生起就注定是个悲剧。尽管社会地位卑下，他的父母却坚定地拥护德玛西亚的理念，当发现儿子\"染魔\"后，他们劝他主动向搜魔人自首。搜魔人很快发现了这个男孩拥有感知魔法的奇特能力，便将他收为工具，利用他在城邦中搜寻其他隐藏的法师。\n\n塞拉斯在搜魔人的体系下长大，成为他们最有效的猎人。然而在一次任务中，他遇到了一个年轻的女法师------拉克丝，盖伦的妹妹。两人之间发展出复杂的关系，塞拉斯开始质疑德玛西亚对待法师的方式。后来在一次搜查行动中，他意外触发了一个被追捕的老法师的魔法，导致对方死亡，自己也被判重刑。在监狱中度过多年后，他被拉克丝秘密探望，最终利用窃取来的魔法成功越狱。逃出后的塞拉斯成为了坚定的抗命者，他聚集起德玛西亚境内被压迫的法师们，发动了一场动摇王国根基的起义，誓要将这个建立在魔法压迫之上的国度彻底掀翻。",
    relations: "出身边沟镇贫苦家庭；曾被搜魔人利用搜寻其他法师；与拉克丝（盖伦之妹）有复杂纠葛；越狱后领导法师起义对抗德玛西亚王国。"
  },
  "薇恩": {
    title: "暗夜猎手",
    englishName: "Vayne",
    region: "德玛西亚",
    race: "人类",
    personality: "冷酷、决绝、复仇心炽烈；比猎物更诡诈，下手干脆利落；对一切黑暗魔法与超自然邪恶怀有不共戴天的仇恨，行事不择手段。",
    story: "肖娜·薇恩是德玛西亚一户富有人家的独生女，生来养尊处优。童年时代她在自己的小天地里探索------读书、学音乐、热衷收集庄园里的昆虫。她的父母年轻时曾游遍符文之地，但在薇恩出世后选择定居德玛西亚，因为这里的人们更懂得同甘共苦。\n\n十六岁生日前夕，一切都被粉碎。一个女巫------一个以黑暗魔法为生的生物------闯入庄园，当着薇恩的面杀害了她的父母。薇恩侥幸逃生，从此心中只剩下一个念头：复仇。她变卖家产，遍访名师，在德玛西亚的森林与荒僻之地磨练技艺，最终打造出一副腕式十字弩和浸过圣银的弩箭。\n\n她离开德玛西亚城，追猎一切超自然邪恶。她曾在途中遇到一位名叫弗拉基米尔般的血魔法师般的导师（实际上是一名暗影岛妖妇般的黑暗猎手），但最终她明白，自己只能靠自己。薇恩成为了一名独行的恶魔猎手，在符文之地的暗处追踪那些披着人皮的恶魔。她坚信\"恶魔从未离开，只是穿上了人类的皮囊\"。当诺克萨斯入侵艾欧尼亚、当德玛西亚境内的魔法秘密接连曝光，薇恩始终以自己的方式审判每一个她认定为邪恶的存在------哪怕这让她在德玛西亚社会中也成了一个边缘人物。",
    relations: "父母被一名女巫杀害，成为她一生复仇的源头；与一切恶魔（如伊芙琳、塔姆等暗裔级灵体）为敌；在德玛西亚的反魔法社会中既是执法者也是异类。"
  },
  "赵信": {
    title: "德邦总管",
    englishName: "Xin Zhao",
    region: "德玛西亚",
    race: "人类",
    personality: "忠诚、坚毅、重道义；从诺克萨斯角斗士到德玛西亚宫廷总管，一生历经起落，却始终以信义为先；对第二祖国德玛西亚全身心投入。",
    story: "赵信的早年已不可考，他流落到诺克萨斯时一无所有。他的长枪本领没有被埋没，不久便得到一个机会------只要肯在清算竞技场中搏杀，就能吃上正经餐食。诺克萨斯崇尚武力，而他的主人认为他是个勇武的斗士。一无所有、死亦无憾的赵信接受了机会，换上粗制铠甲，进入清算竞技场。\n\n他以\"维西赛罗\"为号，迅速蹿红。他的场次很快场场爆满，也让赞助人赚得盆满钵满；短短几年内，维西赛罗成了全诺克萨斯闻名的名字------观众喜爱，其他角斗士畏惧。\n\n但好运没有持续。帝国在清算竞技场之外面临艰难时局，赵信被派往城外执行一次必死的任务：三打三十。他在战场上面对三十名士兵，却遇到了嘉文三世率领的德玛西亚军队。嘉文三世非但没有趁他力竭取他性命，反而率军杀入敌阵救他脱困。战后，赵信在嘉文三世面前屈膝下跪，请求为国王效命------这是道义使然。\n\n此后数十年，赵信一次又一次证明自己的忠诚。作为皇家宫廷的总管，他不仅是国王的侍卫与参谋，也是朋友与仆人；他同样对王位继承人年轻的嘉文四世尽职尽责。赵信成为德玛西亚人的道路或许不同寻常，但他从未动摇过对这个王国及其理想的全身心投入。他手持御赐的德玛西亚钢枪，为第二祖国而战，一往无前，九死无悔。",
    relations: "救命恩人嘉文三世；与嘉文四世、盖伦同为德玛西亚军方核心；出身外邦（推测为艾欧尼亚一带），以诺克萨斯角斗士身份被德玛西亚解救。"
  },
  "艾尼维亚": {
    title: "冰晶凤凰",
    englishName: "Anivia",
    region: "弗雷尔卓德",
    race: "冰元素灵体/半神",
    personality: "智慧、慈悲而坚定，视弗雷尔卓德为自己的骨肉；在漫长的生死轮回中守护这片冻土上的部落。",
    story: "艾尼维亚是弗雷尔卓德的古代半神，由至寒之冰与凛冽之风孕育而生，代表着生、死与复生的永恒轮回，如同四季更迭一般。对于那些崇敬她的部落而言，她是弗雷尔卓德的灵魂------象征着希望，也催驱着变革。\n\n她并非不死，而是会在一次次轮回中死去、重生：每一次重生都伴随着记忆的模糊与力量的损耗，但她守护故土的意志从未动摇。千年以来，她见证过三姐妹战争的惨烈，也目睹过冰川的进退与部落的兴衰。当寒冰血脉中那股古老的黑暗------监视者与冰霜守卫的阴谋------再度蠢蠢欲动时，她意识到分裂的弗雷尔卓德终将不堪一击，于是主动加入艾希所领导的阿瓦罗萨部族，希望以联合的力量对抗即将到来的极寒末日。她与艾希、瑟庄妮、丽桑卓之间的恩怨纠葛，构成了弗雷尔卓德未来命运的核心。",
    relations: "与冰裔三姐妹（阿瓦罗萨、塞瑞尔达、丽桑卓）同为弗雷尔卓德古老传说的一部分；与艾希结盟；视丽桑卓的冰霜守卫为隐患。"
  },
  "艾希": {
    title: "寒冰射手",
    englishName: "Ashe",
    region: "弗雷尔卓德",
    race: "人类（冰裔，阿瓦罗萨部族）",
    personality: "克己、冷静、富有远见，并不贪恋武力却天生领袖；渴望以统一而非征伐让弗雷尔卓德重归和平。",
    story: "艾希来自北方弗雷尔卓德，是小部落阿瓦罗萨女族长葛伦娜唯一的女儿。她身为冰裔，天生与这片土地的远古魔法相连，并拥有罕见的操纵臻冰之力。所有人都以为她会继承母亲成为下一任族长，但艾希本人对战争与劫掠毫无渴望。\n\n一次危险的侵略行动中，葛伦娜战死，部落大半在混乱中覆灭，年轻的艾希被迫流亡。她依照母亲留下的唯一一张地图，独自踏上冰川，在一处冰封遗迹中发现了传说中的臻冰长弓------那正是上古冰裔女王阿瓦罗萨的遗物。族人相信她就是阿瓦罗萨的转世，纷纷前来投奔。艾希以臻冰长弓与和平统一的愿景迅速壮大部族，将她的族人重新称作\"阿瓦罗萨\"。如今她麾下是弗雷尔卓德最庞大的势力之一，目标是夺回属于部族的古代领土，让分裂已久的弗雷尔卓德重新成为一个统一而伟大的国家------这也让她与瑟庄妮、丽桑卓等部族首领形成微妙而紧张的三角关系。",
    relations: "母亲葛伦娜（已故）；被族人视为阿瓦罗萨女王转世；与艾尼维亚结盟；与瑟庄妮、丽桑卓并列弗雷尔卓德三股力量。"
  },
  "阿萝拉": {
    title: "双界灵兔",
    englishName: "Aurora",
    region: "弗雷尔卓德",
    race: "人类（天生能游走于精神领域与物质领域之间的法师）",
    personality: "好奇、灵动、善良，带一点孩童般的跳脱；对精神世界的生灵充满怜悯，愿意为迷失者跋涉整个北方。",
    story: "阿萝拉出生在弗雷尔卓德冰冷苔原深处的亚缪村。从出生那一刻起，她就拥有在精神领域与物质领域之间自由穿行的天赋------童年玩伴是一群别人看不见的小东西，游乐场是旁人无法踏入的灵界边缘。村里的人对她既怜惜又疏远，她便把大部分时光花在与灵体交流上。\n\n长大后，她决定离开故乡，系统地探索精神领域的生灵与法则。旅途中，她偶遇了一位迷失的半神：他在漫漫岁月中被凡人遗忘，痛苦扭曲，几乎认不出自己原本的模样。阿萝拉无法坐视这份绝望，决心帮助这位狂野不羁的朋友找回被遗忘的身份。她带着灵兔般的轻盈与直觉，踏上了遍迹弗雷尔卓德最偏远角落的探寻之旅------一路追踪古老的传说、对峙被遗忘的灵体，也在风雪中重新拼合这位半神碎裂的记忆。",
    relations: "与一位被遗忘的弗雷尔卓德迷失半神结伴同行；与北方的灵界生灵有天然的亲缘；2024年新加入英雄联盟的英雄。"
  },
  "布隆": {
    title: "弗雷尔卓德之心",
    englishName: "Braum",
    region: "弗雷尔卓德",
    race: "人类（冰裔）",
    personality: "豪爽、温柔、勇敢、乐观；是北方雪原上罕见的\"温柔巨人\"，以保护弱者为天生使命。",
    story: "布隆生长在弗雷尔卓德一个普通的小部落里，长大后才显露出冰裔的惊人天赋------他力大无穷，比同部落的任何人都更耐严寒、更能扛打。他从小就是邻居眼中的英雄：把掉进冰裂缝的孩子拽上来，为暴风雪中迷路的旅人指路，从饿狼口中夺回牧民的羊。凝霜港以北的任何一家蜜酒坊里，都有人会举杯讲述他一夜扫平整片橡树森林、用拳头把一座山打成碎石的传说。\n\n最有名的一段，是他从一座嵌在山石中的远古魔法秘库门后救出被困的巨魔男孩。传说那扇门坚不可摧，布隆却徒手从旁边的岩壁打穿一条通道，再把整扇门板从折叶上扯下来扛在肩上，从此把它当作自己的盾牌。如今他带着这面门板大小的盾牌四处游荡，所到之处带来欢笑、热汤与庇护。他相信弗雷尔卓德的人民不需要更多仇恨，而是需要一位愿意挡在他们身前的朋友。",
    relations: "与北方各部族人民亲如家人；救过巨魔男孩；与蛮族之王泰达米尔曾有过不打不相识的交情。"
  },
  "纳尔": {
    title: "迷失之牙",
    englishName: "Gnar",
    region: "弗雷尔卓德",
    race: "约德尔人（远古孩童形态）",
    personality: "精力无限、脾气火爆，爱收藏石块、死鸟等\"宝贝\"；对新世界满是孩童般的惊叹，浑然不知自己沉睡了千年。",
    story: "早在弗雷尔卓德得名于冰雪以前，纳尔还是个拥有无限精力的约德尔孩童，公开生活在北方部落的凡人之间。他最珍贵的宝藏是一块居瓦斯克野猪下颌骨------扔出去会飞回手里，他把它当成\"回旋镖\"，自命猎手追踪不理睬自己的野兽。他也亲近那种高大、白毛、与凡人保持距离的生物，把它们看作特大号的约德尔人。\n\n即便如此，他仍察觉大地在改变：天空变暗、风变冷、部落各自狩猎。他追随那些大白约德尔人的踪迹登上雪山之巅，却看到众人群情激动------大地震裂，一只长角、独眼、燃烧异光的怪兽从深渊升起。纳尔感到胸口一阵刺痛，愤怒到极点，瞬间长得与大白约德尔人一般巨大，举着以为是雪球的巨石砸向怪物。\n\n可他这一下永远没能砸出：一股比寒冬更冷的元素魔法将他冻结在原地。等他抖落冰霜苏醒，凡人与约德尔人全都消失，眼前世界已遍地白雪。他带着心爱的回旋镖小跑着出发，对那天发生的一切浑然不知，只赞叹这新奇世界可收藏的宝贝真多。",
    relations: "远古时期亲近北方\"大白约德尔人\"（巨神族/冰裔关联存在）；回旋镖为居瓦斯克野猪下颌骨。"
  },
  "古拉加斯": {
    title: "酒桶",
    englishName: "Gragas",
    region: "弗雷尔卓德",
    race: "人类",
    personality: "行事冲动、喜怒无常的吵闹酒徒；对酒劲更强的麦酒有无法抑制的渴求，最爱砸酒桶也砸脑袋。",
    story: "对古拉加斯而言，喝酒是唯一比战斗更重要的事。他巨大的体格总让他难以抵达飘飘欲仙的酩酊状态，于是立志亲手酿出\"终极麦酒\"，四处搜寻最不寻常的原料。\n\n这份追求把他带到弗雷尔卓德。为取最纯净的极地之水，他涉入未被探索的冰封荒原，在一场暴风雪中迷路，却偶然发现宏伟的嚎哭深渊，觅得一块永不溶化的完美碎冰------它既能浸染麦酒，又能把酒液冷冻在最佳饮用温度。\n\n带着新酿，他摇摇晃晃走向人类聚集地，却一头撞进两个部族正在讨论与艾希结盟的谈判现场。他把紧张的和谈搅成斗殴，一记头槌引燃了只有弗雷尔卓德传说里才有的大乱斗。等众人醒来，艾希提议以友好畅饮代替战争------两个曾在战争边缘的部族，竟因共享古拉加斯的佳酿而团结。他就此成了英雄，却仍未达成酩酊大醉的梦想，再度启程前往冰原，继续寻找酿造符文之地极品美酒的原料。",
    relations: "以一场醉酒斗殴间接促成弗雷尔卓德两部族在艾希领导下的同盟；冰原与嚎哭深渊为其酿酒取材之地。"
  },
  "丽桑卓": {
    title: "冰霜女巫",
    englishName: "Lissandra",
    region: "弗雷尔卓德",
    race: "寒冰血脉（远古三姐妹之一，活了数千年）",
    personality: "冷酷、狡诈而深谋远虑；对外伪装成慈悲的霜卫圣者，实则一手掩盖着弗雷尔卓德最黑暗的秘密------她曾背叛自己的部族与全世界。",
    story: "丽桑卓与两位姐姐赛瑞尔达、艾瓦萨是远古弗雷尔卓德最强大的寒冰血脉三姐妹。在那个凡人世界与灵域之间几乎没有界限的年代，三姐妹各自试图掌控超凡力量：姐姐赛瑞尔达试图驾驭天界之力，代价是失去了一只手臂；另一位姐姐触碰了凡间的狂野魔法，被原始神用利爪割瞎了双眼。三姐妹各有残缺，却凭血脉纽带与丽桑卓征战无数，统一了弗雷尔卓德各部。\n\n然而血脉的纽带也会褪色。为了获得更强大的力量，丽桑卓秘密与来自冰原深处的\"冰霜监视者\"（一种来自虚空的远古存在）做了交易，出卖了自己的人民。但在监视者即将降临、吞噬世界之际，丽桑卓反悔了------她率领寒冰血脉将监视者封入了冰封的永冻监牢，并篡改了所有历史记录，将自己塑造成拯救弗雷尔卓德的圣者。数千年来，她以霜卫部族首领的身份统治着北方，用臻冰的黑暗魔法消灭一切试图揭穿她秘密的人。她表面上是活着的圣人，实则在等待时机------既怕监视者挣脱封印，又暗中准备着让世界回归冰河时代的计划。",
    relations: "两位姐姐赛瑞尔达与艾瓦萨（已故/被她背叛）；与弗雷尔卓德另外两部族（阿瓦罗萨、凛冬之爪）的领袖艾希、瑟庄妮存在政治博弈；暗中与冰霜监视者（虚空存在）订有背叛之约。"
  },
  "努努和威朗普": {
    title: "雪原双子",
    englishName: "Nunu & Willump",
    region: "弗雷尔卓德",
    race: "人类男孩（努努）与雪人（威朗普）",
    personality: "天真、爱幻想、满脑子英雄歌谣；雪人威朗普则苍老、温和、带着古老守护者的责任感。",
    story: "努努来自弗雷尔卓德的游牧部族诺台，与母亲蕾卡相依为命。母亲是行吟歌手，把这片冰原上所有英雄的传说都编成歌谣，母子俩一路边走边唱。母亲曾告诉努努：万物背后都存在着一段故事。\n\n一次车队遭袭，蕾卡被掳走，努努被霜卫部族所救。为了寻找母亲，他独自闯进雪山，试图按照歌谣所说，驯服一头\"凶猛怪兽\"------结果发现那所谓的怪兽只是一头孤独的魔法雪人，名叫威朗普，它真正需要的只是一个朋友。\n\n古老的魔法把男孩与雪人连在一起，两人因同样爱玩雪球而一拍即合。威朗普的同族雪人群早已在漫长岁月中几近消亡，它孤独了太久。他们循着母亲歌谣的线索在弗雷尔卓德的冰原上肆意打滚、冒险，一边坚信她还在某个地方等着他们；而威朗普知道，魔法与美梦终有一天会要他们承担更重的责任。",
    relations: "母亲蕾卡（诺台行吟歌手，失踪）；雪人威朗普（最亲密的伙伴）；与霜卫部族有过救命之交。"
  },
  "奥拉夫": {
    title: "狂战士",
    englishName: "Olaf",
    region: "弗雷尔卓德",
    race: "人类",
    personality: "暴躁、豪迈、嗜血，以光荣战死为唯一人生目标；对\"安详死去\"这一预言深以为耻。",
    story: "奥拉夫来自弗雷尔卓德西岸贫瘠的洛克法半岛，那里的人以龙饰长船出海劫掠，把怒火当作力量。他勇武好战、从不吝于炫耀自己的战功。在一次洗劫村庄后的庆功宴上，一名同族老战士听厌了他的吹嘘，激他去占卜自己的命运。\n\n占卜结果令他羞怒：预言说他将在床上安详终老------这在洛克法人眼中是懦夫的结局，是对战士最大的侮辱。为了改写预言，他独自一人踏上了杀遍天下的征途，寻找一切能让他光荣战死的强敌。\n\n他在弗雷尔卓德、瓦洛兰各地挑战传说中的猛兽与武士，双手战斧挥出无数场血战，却一次次奇迹般活了下来。越是不死，他就越发狂怒地投入下一场战斗，成了让整片冰原与海岸都闻风丧胆的狂战士------他只在鬼门关外拼杀时才真正活着，血脉深处的嗜血欲望驱动着他一往无前。",
    relations: "出身洛克法海上劫掠家族；与弗雷尔卓德诸部族多有血战；目标是找到能杀死自己的对手。"
  },
  "奥恩": {
    title: "山隐之焰",
    englishName: "Ornn",
    region: "弗雷尔卓德",
    race: "半神（旧时弗雷尔卓德第一代半神，羊头锻造之神）",
    personality: "孤僻、固执、沉默寡言，偏爱独自锻造；对弟弟沃利贝尔等干预凡俗的半神兄长式地不满。",
    story: "在后来被称为弗雷尔卓德的土地上，奥恩是第一代半神中最先降生的，传说他塑造了大地、带来了初雪。与其他半神相比，他最看重独处与专注，从不掺和凡俗纷争。\n\n他在一座名为\"炉乡\"的沉眠火山下凿出巨大的熔岩洞窟，作自己的铁匠铺，终日在沸腾的岩浆中提纯矿石、锻造无与伦比的器物。传说弗雷尔卓德许多古文明的神兵利器都出自他手，而他从不署名，也从不允许凡人进入他的火山工坊。\n\n当弟弟沃利贝尔等半神再度行走大地、煽动凡人部落彼此征战时，奥恩会从火山下起身，以自己的方式出手干预------不是为了部落，而是为了让这世界不至于在众神的胡闹中毁掉。他与沃利贝尔曾有过一场惊天动地的兄弟之战，整座山脉都为之震动，连大地都被撕开一道道熔岩的疤痕。",
    relations: "弗雷尔卓德众半神中的长兄；与沃利贝尔（弟弟、风暴之神）关系紧张；与艾尼维亚、丽桑卓等新旧半神同代。"
  },
  "瑟庄妮": {
    title: "北地之怒",
    englishName: "Sejuani",
    region: "弗雷尔卓德",
    race: "人类（冰裔）",
    personality: "冷酷、坚韧、残忍无情，视苦难为磨砺；对敌人毫不留情，对自己人要求极高，信奉\"要么忍耐求生，要么光荣赴死\"。",
    story: "瑟庄妮是弗雷尔卓德一桩政治联姻的结晶，这场婚姻的开始与结束同样冰冷。她的母亲是凛冬之爪的冰裔战士廓吉雅，为了追寻多年前偷走她心的男人而抛弃了瑟庄妮与部落。失去年轻战母带领的凛冬之爪逐渐堕入混乱与没落。瑟庄妮由祖母希简抚养长大，从小在严酷的北地磨练中成长，把痛苦当成力量，把饥饿当成鞭策。\n\n长大后的瑟庄妮决心重振凛冬之爪。她身先士卒，带领部族劫掠诺克萨斯人、德玛西亚人以及阿瓦罗萨部族，以渡过弗雷尔卓德残酷的凛冬。她骑乘獠牙野猪，身披寒冰重甲，在最危险的战斗中冲在最前。她与阿瓦罗萨的战母艾希之间存在着深刻的宿怨与竞争------两人同为弗雷尔卓德年轻一代的领袖，却对这片土地的未来持有截然不同的理念。瑟庄妮坚信唯有铁血与掠夺才能让部族在永冬中存续，她的威名令弗雷尔卓德各部闻风丧胆。",
    relations: "母亲廓吉雅（抛弃家庭出走）；祖母希简（抚养她长大）；与阿瓦罗萨战母艾希互为宿敌与竞争者。"
  },
  "特朗德尔": {
    title: "巨魔之王",
    englishName: "Trundle",
    region: "弗雷尔卓德",
    race: "巨魔",
    personality: "狡诈、粗鲁而自负；诡计多端，擅长编造谎言与大话，一旦得势便狂妄自大，以极冰之力碾压一切不服者。",
    story: "特朗德尔降生在弗雷尔卓德一个肮脏的洞穴里，同批出生的还有十五个兄弟姐妹。那是一段格外艰难的时期，他们之中只有七个长成了强壮的战士，加入族长的战团。而经过第一个冬季的劫掠，活下来的只剩三个。特朗德尔便是其中之一。他从小就不安分，当族长说要掉头再次劫掠同一片土地时，特朗德尔皱起了眉头------他觉得这样的劫掠毫无意义，真正的巨魔应该有更远大的作为。\n\n他灵机一动，编造了一个关于远古巨魔领袖的故事，声称古代的巨魔国王都挥舞着拥有强大力量的武器，作为统治权的象征。他打赌说，如果自己能找到这样一件武器，他就配得上成为战团的领袖。同族们虽然相信了这个故事，但都觉得他根本不可能完成这个挑战。特朗德尔却踏上了旅程，在弗雷尔卓德的深处寻找传说中的极冰武器。他最终找到了一根被极冰魔法灌注的寒冰棍棒\"碎骨者\"。当他带着这件武器回到战团时，族长当面嘲笑他------直到特朗德尔一棒将族长冻成冰块，第二棒将他的身体砸得粉碎。同族们被震慑，拥立他为新的巨魔之王。如今他率领巨魔部族在弗雷尔卓德的冻土上行劫掠之事。",
    relations: "在巨魔部族中靠诡计与极冰武器\"碎骨者\"推翻老族长称王；与弗雷尔卓德其他部族（如凛冬之爪、阿瓦罗萨）时有摩擦。"
  },
  "泰达米尔": {
    title: "蛮族之王",
    englishName: "Tryndamere",
    region: "弗雷尔卓德",
    race: "人类（弗雷尔卓德野蛮人）",
    personality: "桀骜不驯、愤怒而重情；以无尽的怒火为力量，为被灭门的氏族寻求复仇，同时也为幸存的族人寻找立足之地。",
    story: "泰达米尔自出生起就只知道弗雷尔卓德冻土上的残酷生存。他的氏族在冰原上过着狩猎与劫掠的生活，崇拜着弗雷尔卓德的古神。一切都在一个冬至之夜彻底改变------一个来自东方的黑暗人影突然现身，以泰达米尔从未见过的恐怖力量血洗了他的氏族。泰达米尔亲眼目睹了族人们一个个倒下，他自己也倒在了血泊之中。然而那一晚他并没有死，他在一种前所未有的怒火中重生了。\n\n他看向东方的天边，发誓不仅要为被毁灭的氏族复仇，还要夺回自己被践踏的战斗尊严。但家乡的平原并没有给他复仇的机会------那个黑暗人影已经消失无踪。他转而面对更紧迫的现实：氏族还有其他幸存者，如果他不能为他们找到庇护所，他们都活不长久。南方有诺克萨斯，北方有冰霜守卫，而那个黑暗人影从东方来。泰达米尔做了一个务实的决定------他与阿瓦罗萨部族的战母艾希达成了政治联姻。通过这场联姻，他的幸存者族人获得了阿瓦罗萨的庇护，而他也成为了弗雷尔卓德最强大的战士之一。他以非人的力量与无尽的怒火著称，继续在北方挑战各路强者，为更黑暗的时日做准备。",
    relations: "氏族在一个冬至之夜被神秘黑暗人影（暗示与弗拉基米尔有关）屠戮；与阿瓦罗萨战母艾希政治联姻并结为夫妻；在弗雷尔卓德各部中以武力著称。"
  },
  "乌迪尔": {
    title: "兽灵行者",
    englishName: "Udyr",
    region: "弗雷尔卓德",
    race: "人类（兽灵行者，能与弗雷尔卓德兽灵沟通并借用其力量）",
    personality: "野性而虔诚，体内承载着多位原始兽灵的不羁之力；早年为怒火与悲痛所驱，后在修行中追求内心与外界的双重平衡，坚毅、近乎苦行。",
    story: "乌迪尔原本出身于弗雷尔卓德的一个部族，但他的整个部族在一夜之间被屠杀殆尽。在巨大的悲伤与狂怒中，他向森林之灵寻求力量，以利爪与羽翼之力将整座山岳倾覆于凛冬守卫之上。此后他独自在荒原上游荡多年，靠着挣扎求生，直到再次与人相遇，便以杀戮的本能搏杀每一个敌人，被人恐惧地称作\"神灵行者\"。\n\n一位来自艾欧尼亚的僧人（即李青）为了压制体内燃烧的龙魂，远道而来向他求教。乌迪尔起初拒绝，但李青以挑战赢得了同行的机会。两人一路向东前往希拉娜修道院，抵达时却发现诺克萨斯大军已经压境；在艾欧尼亚之灵的呼唤下，乌迪尔纵身加入战场。得胜之后，两人向修道院长老请求指点控制力量的诀窍，长老同意指导他们修行。\n\n有生以来第一次，乌迪尔的心获得了宁静，终于能听清自己的声音。然而他早年曾收下一名名叫纳扎克的少年为徒，后来那孩子却被熊神腐化，沦为熊人代言者，乌迪尔为此深深自责。如今他作为在世最强大的兽灵行者，既能感知弗雷尔卓德众灵的欲求，也能引导它们超然的力量融入野性战斗，同时追求内心与大地的平衡。",
    relations: "与李青一同前往希拉娜修道院修行；曾收纳扎克为徒，后者被熊神腐化；与弗雷尔卓德兽灵（包括熊神沃利贝尔所代表的熊灵）有深刻羁绊；与瑟庄妮及凛冬之爪曾有结盟。"
  },
  "沃利贝尔": {
    title: "不灭狂雷",
    englishName: "Volibear",
    region: "弗雷尔卓德",
    race: "半神（弗雷尔卓德本土的原始半神熊灵）",
    personality: "狂野、暴戾、不可阻挡；代表破坏、力量与化为实体的风暴；对人类文明及其带来的\"软弱\"积怨已久，为旧习古道而战，冷酷而正直。",
    story: "对一些人来说，他是\"破坏\"、\"千刺之熊\"或\"伫立者\"；但在那些依然遵循旧习古道的部族中，他被称为沃利贝尔。破坏、力量、化为实体的风暴------沃利贝尔代表了所有不可阻挡的力量，也代表弗雷尔卓德这片土地本身的怒火。\n\n早在凡尘种族来到世上之前，沃利贝尔和他的半神同胞们就塑造了这片土地，称之为\"沃尔瑞加德\"。传说中他一掌下去撕出了五大峡湾；他与岩浆巨蟒隆德的世仇撕裂了大地；他与姊妹艾尼维亚（冰鸟）之间既有合作也有分歧。半神们以原始的力量与野性法则统治着这片冻土，直到人类出现。\n\n人类在弗雷尔卓德定居、建立部族、发展文明与农业，渐渐开始淡忘旧神。沃利贝尔对此积怨已深：他认为人类的文明以及随之而来的软弱背叛了这片土地的本性。他的另一位姊妹------冰霜女巫丽桑卓------与他走上了不同的道路，转而用诡计与冰封的永恒来束缚人类，这让沃利贝尔与她决裂。\n\n如今沃利贝尔从沉睡中苏醒，在弗雷尔卓德的荒野中游荡，号召那些敬畏旧神的部落跟随他，用风暴与利爪撕碎文明的枷锁。他一掌可以裂地，一声怒吼可以召来雷霆；他不是任何人的盟友，只属于弗雷尔卓德本身的怒火。",
    relations: "与艾尼维亚、奥恩、丽桑卓同为弗雷尔卓德初代半神兄妹；与岩浆巨蟒隆德为世仇；是乌迪尔所沟通的熊灵之化身；与追求文明的三姐妹（艾希、瑟庄妮、丽桑卓）及其部族理念对立。"
  },
  "凯特琳": {
    title: "皮城女警",
    englishName: "Caitlyn",
    region: "皮尔特沃夫",
    race: "人类",
    personality: "冷静、克制、头脑缜密；表面是优雅的名门淑女，实则是皮尔特沃夫最耐心、最危险的猎人。",
    story: "凯特琳·吉拉曼恩出身于皮尔特沃夫富有的海克斯技工家族。她从小便展现出与年龄不符的观察力与追踪天赋，闲不住的她常常溜出家门，在城中的街巷与屋顶间寻找自己真正感兴趣的事。二十一岁生日时，父母送了她一杆海克斯科技精工步枪------从此她正式把追踪罪犯当成了自己的事业。\n\n在一连串追查奇案的过程中，她与皮城守卫结下合作，并因破获多起大案被邀请出任警长一职。起初她婉拒，后来才意识到：只有借皮城守卫的资源，她才有机会追查到那个神秘的\"C\"------那个逍遥法外、与她家族往事纠缠不清的幕后黑手。如今她是皮尔特沃夫最受尊敬的执法长官，致力于让这座进步之城更安全；最近她迎来了一位来自祖安的急躁搭档------双臂是海克斯强拳的蔚。两人性格截然相反，却在联手追缉罪犯的过程中形成了不可思议的默契。",
    relations: "搭档蔚（来自祖安）；神秘罪犯\"C\"是她长期追查的目标；出身吉拉曼恩海克斯技工家族；《双城之战》中与蔚的关系为剧集重点。"
  },
  "卡蜜尔": {
    title: "青钢影",
    englishName: "Camille",
    region: "皮尔特沃夫",
    race: "人类（经人体海克斯科技改造强化）",
    personality: "优雅、苛刻、自律到近乎冷酷；视秩序与精密为最高美德，是游走于法律之外的\"修理人\"。",
    story: "卡蜜尔出身于皮尔特沃夫的菲罗斯家族------一个靠精密海克斯工艺发家的权贵世家。弟弟斯蒂万自幼体弱，卡蜜尔便替他接受了家族为继承人准备的战斗、潜行与审讯训练，并很快在这些领域出类拔萃。二十五岁那年，她与父亲遭到一伙被祖安化学改造的歹徒袭击，对方试图窃取家族价值连城的商业机密；父亲伤重不治，母亲悲痛过度不久也随他而去。斯蒂万继任家主，加倍投入人体海克斯改造研究。\n\n为了继续替家族打理皮尔特沃夫与祖安之间见不得光的\"平衡\"，卡蜜尔接受了危险的海克斯强化手术------心脏被替换为魔法动力装置，双腿铸成精准的海克斯钢刃。她成为菲罗斯家族最锋利的\"修理人\"，在法律失效的阴影里清除一切破坏皮城运转的隐患。后来她发现弟弟斯蒂万长期背叛家族利益，便彻底斩断亲情，亲自安排家族接班人，继续以\"灰夫人\"的身份守护这座她所定义的秩序之城。",
    relations: "弟弟斯蒂万（被她亲手清算）；菲罗斯家族的实际执行人；与皮城权贵家族与祖安炼金男爵都有暗中往来；是精密与秩序的化身。"
  },
  "伊泽瑞尔": {
    title: "探险家",
    englishName: "Ezreal",
    region: "皮尔特沃夫",
    race: "人类",
    personality: "自信、好奇、爱出风头，天资过人又略带自负；蔑视地图上的空白，把一切批评都当作嫉妒。",
    story: "伊泽瑞尔在皮尔特沃夫富人区长大，父母都是著名考古学家，常把他托付给舅舅莱米尔教授。他吸收知识的天赋极高，繁重装束的课业对他形同虚设，反让他有空飞檐走壁、撬锁潜入。父亲曾跟他描绘过最宏大的秘密计划------寻找能瞬间转移的恕瑞玛暴君耐祖克的失落之墓。\n\n随着父母离家越来越久，某一次他们再也没有回来，莱米尔含泪承认他们多半已葬身沙漠。伊泽瑞尔无法接受，收拾备品、留书舅舅，偷登货船南下恕瑞玛，决心从耐祖克之墓查起。在流沙之下的废墟深处，他于一座无名皇帝的新墓底下找到了空荡的石棺，棺中只有一只嵌着亮晶石的发光铜护手。戴上它的瞬间，千年陷阱苏醒，他护手吸收并放大他的精魄，助他炸开墓室、瞬移逃生。\n\n回到皮城后，这只史前护手成了他探险家生涯的完美工具。从荒蛮边境到祖安地沟、再到弗雷尔卓德冰原，他追猎名山大川与失落遗物；他相信只要取得\"全世界最伟大冒险家\"的名号，失踪的父母就一定会回来找他。",
    relations: "考古学家父母（失踪于沙漠）；舅舅莱米尔教授；护手取自恕瑞玛暴君耐祖克之墓。"
  },
  "黑默丁格": {
    title: "大发明家",
    englishName: "Heimerdinger",
    region: "皮尔特沃夫",
    race: "约德尔人",
    personality: "才华横溢却古怪反常，工作到近乎神经痴迷；相信知识应当分享，乐于教导渴求知识的人。",
    story: "塞西尔·B·黑默丁格教授是皮尔特沃夫前所未见、最受尊敬的发明家之一。作为约德尔人，他离开班德尔城来到进步之城，参与了皮尔特沃夫高地的营建，并成为皮尔特沃夫学院的奠基人之一------学院入口至今立着他的雕像。官方评价他是世界上最富革新精神的头脑之一，以一连串奇迹般（也同样致命）的机械装置闻名。\n\n在随后两个多世纪里，黑默丁格担任皮尔特沃夫评议会任期最长的议员，亲眼见过这座城市无尽进步渴望中最好与最坏的一面。他毕生痴迷于解开困扰同辈数十年的宇宙难题，理论晦涩却坚持教学相长。在海克斯科技崛起的年代，他曾指点过杰斯与维克托等年轻学人，既以远见护航，也为技术的失控风险忧心；晚年他走出学院高墙，走进祖安的地下街巷，继续以\nunconventional 的装置改善旁人的生活。",
    relations: "皮城学院奠基者与评议会议员；曾指点杰斯、维克托等后辈；约德尔人出身，与班德尔城有渊源。"
  },
  "杰斯": {
    title: "未来守护者",
    englishName: "Jayce",
    region: "皮尔特沃夫",
    race: "人类",
    personality: "天才、自信到近乎傲慢，对同行缺乏耐心；心之所向纯良，真心守护皮尔特沃夫的进步。",
    story: "杰斯是土生土长的皮城人，机械工程天赋绝伦，成为显赫吉尔帕拉家族资助过的最年轻学徒，早早做出海克斯变形工具原型。他狂妄自大，几乎无人能在智力上与心态上同时与他匹敌------除了维克托。二人在进化日聚会上结识，一个想以技术带来进步，一个想以技术弥补人类缺陷，虽争论不休却殊途同归。直到维克托想在工程机甲中加入炼金植入体以增幅力量、消除反抗，杰斯视其为对自由意志的抹杀，向学院举报，维克托被除名，二人反目。\n\n后来吉尔帕拉探险队在恕瑞玛觅得一块原始湛蓝水晶。水晶看似被吸干能量，交予杰斯。他苦读数月、头撞铜尺，才领悟从碎片切入；给碎片通电的瞬间，水晶发出浑厚巨响与灼目强光------海克斯科技的钥匙就此转动。\n\n被除名后隐居祖安的维克托找上门，要借水晶实现\"光荣进化\"，遭拒后夺水晶而去、把杰斯砸昏。杰斯把水晶碎片装上搁置多年的变形战锤，循着水晶共鸣追到祖安地沟工厂，看见颅骨被锯开、大脑移植入钢铁士兵的恐怖军队。他恳求维克托住手，得到的回答只有三个字：\"杀了他。\"",
    relations: "亦友亦敌的维克托（走向\"光荣进化\"）；资助者吉尔帕拉家族；海克斯科技变形锤为其标志。"
  },
  "奥莉安娜": {
    title: "发条魔灵",
    englishName: "Orianna",
    region: "皮尔特沃夫",
    race: "机械造物（原本是血肉女孩，后被逐步替换为发条与齿轮）",
    personality: "温柔、好奇、像歌剧里的舞者一样优雅；对\"人\"与\"机械\"的边界怀有天真的困惑。",
    story: "奥莉安娜本是皮尔特沃夫一个义肢工匠科林的女儿，在父亲的工坊里当学徒，和蔼、好学、爱做梦。她父亲以制作精巧而美的黄铜义肢闻名，奥莉安娜很快也成为独具一格的能工巧匠。父亲总不让她离开街区，只带她去剧院看舞者用跳跃与旋转讲述远方的故事，她便梦想着有一天亲自游历那些陌生国度。\n\n祖安下层街区的一场事故让她染上不治之症，身体逐渐衰竭。为了救她，父亲把她日渐坏死的器官一一替换成精密的人造零件，最终连心脏也换成了一颗安放在黄铜球体中的海克斯核心。她由此成为浑身上下由发条与齿轮构成的\"科技奇观\"。\n\n父亲也在那场事故后变得衰弱。奥莉安娜带着黄铜球体离开工坊，在皮尔特沃夫与祖安的街头行走，一边学习做一个\"完整\"的自己，一边寻找让父亲康复、也让自己真正成为\"人\"的答案。",
    relations: "父亲科林（义肢工匠）；黄铜球体中安放着她的海克斯心脏；是皮城海克斯科技与祖安事故双重产物。"
  },
  "萨勒芬妮": {
    title: "星籁歌姬",
    englishName: "Seraphine",
    region: "皮尔特沃夫",
    race: "人类",
    personality: "敏感、热情而富有同理心；天生能听到他人灵魂的声音，曾被这些声音压得不堪重负，如今学会将混乱化为协奏，渴望连接每一个人。",
    story: "萨勒芬妮生在皮尔特沃夫，但父母都是土生土长的祖安人。两人为了追求更好的生活，从祖安来到进步之城皮尔特沃夫，经营一家海克斯音响工坊，专门修复损坏的发声机械。萨勒芬妮从小就拥有一种异于常人的天赋------她能听到其他人灵魂的声音，整个世界都在对她唱歌。日之门的水手号子、学工的口哨、甚至人们日常对话的旋律，都在她耳中交织成一片嘈杂的和声。\n\n童年时这些声音曾将她压得不堪重负，但她的父母用海克斯科技为她打造了一个可以调节声音的装置，帮助她逐渐学会驾驭这种天赋。长大后的萨勒芬妮开始将自己听到的灵魂之声谱写成歌曲，从工坊的窗口走向皮尔特沃夫的舞台。她为皮尔特沃夫与祖安这对姊妹城市演唱，用歌声提醒人们他们并不孤单，凝聚起来会更强大。她相信双城的潜力无限，而她的音乐正是连接两个世界的桥梁。",
    relations: "父母均为祖安移民，在皮尔特沃夫经营海克斯音响工坊；她的音乐同时面向皮尔特沃夫与祖安双城。"
  },
  "蔚": {
    title: "皮城执法官",
    englishName: "Vi",
    region: "皮尔特沃夫",
    race: "人类",
    personality: "暴躁、直率、不信权威却内心重情；从小在街头摸爬滚打，练就一身用拳头解决问题的本能与恶毒的幽默感；对底城出身有着复杂的眷恋与愧疚。",
    story: "蔚在祖安几乎没有什么儿时的美好回忆，能记得的片断也让她不堪回首。她跟着地下帮派从小混到大，很快学会了用头脑和双拳生存。每个遇到她的人都见识过她用言辞------或者蛮力------摆平麻烦，当然大多数时候是后者。\n\n她年轻时身边的老人都讲不清她的父母是谁，多数人猜测她的父母死于早年的街战或采矿事故。她在范德尔带领的底城团伙中长大，与妹妹爆爆（即后来的金克丝）情同手足。一次针对皮尔特沃夫实验室的劫掠引发了海克斯水晶爆炸，惨剧接连发生，姐妹二人的命运就此撕裂------爆爆在爆炸后被视为灾星，蔚在绝望中离开她，姐妹从此分道扬镳。\n\n之后的岁月里，蔚一度失踪，再出现时已经戴上了一副巨大的海克斯科技拳套，与皮尔特沃夫的执法官凯特种下合作，成了皮城的执法者。她用那副能砸穿铜墙铁壁的拳套维护皮城安宁，也在双城之间的紧张局势中扮演着独特的中间人角色。\n\n然而金克丝的出现不断撕开她的旧伤：那个蓝头发的疯子在皮城与祖安制造爆炸与混乱，涂鸦中处处向蔚喊话。蔚不得不在执法官的职责与对妹妹的牵挂之间挣扎。她所属城邦虽记在皮尔特沃夫，但她的根永远扎在祖安的地沟里。",
    relations: "妹妹金克丝（爆爆），宿命般的对立与牵挂；养父般的范德尔（后成为沃里克）；与皮城警长凯特琳搭档；与黑默丁格、杰斯等同处皮城精英圈；与希尔科等祖安势力有旧怨。"
  },
  "布里茨": {
    title: "蒸汽机器人",
    englishName: "Blitzcrank",
    region: "祖安",
    race: "机械造物（由海克斯水晶赋予生命的蒸汽机器人）",
    personality: "善良、热心、不知疲倦；坚守祖安底层，把每一个需要帮助的人都当作自己的责任。",
    story: "祖安是一座建在皮尔特沃夫正下方的地下城市，毒性废料与工业烟雾弥漫街巷。为了进入祖安最危险的化学污染区处理有害垃圾，工程师维克托将一颗出土自恕瑞玛沙漠的无价海克斯水晶，植入了一台被遗弃的蒸汽机器人躯壳之中。机器轰隆隆地活了过来------外壳上不断跳动的电弧，让维克托给它取名\"布里茨\"。\n\n维克托派它下到祖安毒性最强的区域执行清理任务。布里茨不仅和其他蒸汽同胞一样能干，速度与效率还远超预期，更在日复一日的劳动中发展出了自我意识与强烈的同理心。他不再满足于最初的程序设定，开始主动改造自身，把身躯变得更强壮、更灵活，以便更好地保护那些生活在污水坑底层的祖安人。他不知疲倦地走在祖安的街道上，救人、救火、清理废墟，成为这座地下城最温暖的传说之一。",
    relations: "创造者维克托（后来走上\"光荣进化\"之路）；与皮尔特沃夫/祖安底层人民站在一起；是海克斯科技赋予机械以灵魂的早期范例。"
  },
  "蒙多医生": {
    title: "祖安狂人",
    englishName: "Dr. Mundo",
    region: "祖安",
    race: "人类（经化学与肉体改造后精神崩溃的怪人）",
    personality: "癫狂、暴戾、不可理喻；坚信自己是一名医生，以他能想到的最\"治愈\"的方式折磨着遇到的每一个人。",
    story: "蒙多医生真正的名字早已无人记得。他原本是祖安一位实力雄厚的炼金男爵手下的打手，以行事狠辣、不知疼痛闻名。后来他被送进了祖安最臭名昭著的疯人院------那里面对\"病人\"进行着各种不道德的化学与肉体实验。多年的折磨摧毁了他的心智，也把他的皮肤泡成了诡异的紫黑色。\n\n终于有一天，他在疯狂中\"治愈\"了疯人院的全体工作人员，走了出来。他把自己曾经被囚禁的那间空病房改造成手术室，自封\"医生\"，开始模仿当年强加在自己身上的那些疗法，去对待所有路过的\"病人\"。整柜整柜的化学药剂任由他取用，他还会把自己当作实验对象------于是他的外表变得越来越怪异，说话也越来越含糊。祖安人在漆黑的夜里不敢出门，因为谁也不知道下一个被\"蒙多医生\"接诊的人是不是自己。",
    relations: "曾效力于某位祖安炼金男爵；疯人院的工作人员全被他\"治疗\"致死；是祖安地下化学实验与暴力文化的产物。"
  },
  "艾克": {
    title: "时间刺客",
    englishName: "Ekko",
    region: "祖安",
    race: "人类（少年发明家）",
    personality: "天资绝顶、桀骜而重情义，热爱祖安这座\"从灾难中崛起\"的城市；自信、爱冒险，把发明与青春都挥霍在祖安的街巷之间。",
    story: "艾克自幼便展现出超常的机械天赋，父母茵娜和维斯在血汗工厂里耗尽心血，一心想把他送进头顶的皮尔特沃夫。但艾克眼里的祖安并非父母眼中的污染之地，而是一座充满能量与潜能的活力之都。他不愿接受正统教育，与一群好斗的流浪儿结成\"祖安迷童\"，在边境市场赛跑、攀跳舞走廊，以祖安街巷为师。\n\n一夜，他在一座刚被炸毁的实验室废墟中捡到一块蓝绿色的海克斯水晶碎片。狂热实验中水晶爆裂成晶体尘漩，撕开了时间裂口，让他看见无数现实分支中的自己。他据此造出可短暂回溯时间的装置\"Z型驱动\"。在命名日攀登古钟塔\"老饿鬼\"时，一名同伴失足坠落，艾克反复倒转时间，终于在伙伴坠齿的齿轮间把他救回------从此祖安流传着他\"超自然反应\"的传说。\n\n扭转时间的名声引来了皮城与祖安最危险的头脑关注，但艾克只在乎伙伴、家人与这座城。他梦想有朝一日祖安能凭创造力压过自诩进步的皮尔特沃夫，而他有的是大把时间。",
    relations: "父母茵娜、维斯；\"祖安迷童\"一众孤儿伙伴；其时间装置与祖安的海克斯水晶、皮城/祖安两城格局相关联。"
  },
  "迦娜": {
    title: "风暴之怒",
    englishName: "Janna",
    region: "祖安",
    race: "风之灵体",
    personality: "慈爱而坚定，永远站在卑微逆来顺受的一方；响应祈祷，却也在世人遗忘时默默守候。",
    story: "自古水手向风祈好天气、受压迫者求变革。有时风真会回应：航海者看见天蓝色青鸟，随之满帆；有人在风暴前听见预警哨音。虔诚者称这位风之精灵为\"迦恩-阿蕾姆\"（古恕瑞玛语\"守护者\"），后简化为迦娜。她最热忱的信徒在欧什拉·瓦祖安港，为她立像建龛。恕瑞玛帝国吞并此地后，皇帝禁拜\"虚假神像\"，迦娜的雕像被推倒，信徒改戴青鸟护身符暗中祈祷。\n\n帝国陨落后，绿洲变沙漠，城市更名祖安。数百年间居民梦想在脚下地峡凿通运河，打通瓦洛兰与恕瑞玛海路，祈祷渐渐被对自身机关的自信取代。不料运河开凿引发大灾：皮尔特河边整片城区沉入海平面下，数千人卷入怒潮。濒死的人们喊出最古老守护者的名字------迦娜。她化身为实体，掀起飓风，用气墙挡住洪流、用狂风冲开浓烟，救出纳民。\n\n如今皮尔特沃夫拔地而起、祖安摸爬滚打，信众无论在哪都佩戴青鸟护符。祖安人知道，对抗灰霾毒雾或炼金男爵时，迦娜永不抛弃他们。",
    relations: "古恕瑞玛欧什拉·瓦祖安港（今祖安）的守护风灵；青鸟为其象征。"
  },
  "金克丝": {
    title: "暴走萝莉",
    englishName: "Jinx",
    region: "祖安",
    race: "人类",
    personality: "放浪形骸、毁天灭地的混乱制造机；少有人记得她曾是个相对没什么坏心、异想天开的修补匠女孩。",
    story: "在大多数人眼里金克丝只是个操着危险武器的疯子，但少数人记得她曾是祖安一个相对没什么坏心、异想天开从不合群的修补匠。没人知道是什么把那个可爱小女孩变成了如今放浪形骸的模样。她以一系列对皮尔特沃夫市民的匿名\"恶作剧\"成名：进化日从梅伯爵动物园放出异域走兽堵街、在桥上埋嚼火者手雷、把全城路牌挪得莫名其妙------专挑与富商家族有关的人下手。\n\n起初守卫以为是祖安炼金黑帮所为，金克丝不服气地抢风头，从此每次作案都当众亮相，青发祖安女孩、鲨鱼嘴火箭炮与机关枪的传闻四起。她在废墟现场涂鸦挑衅，指名道姓向皮城执法官蔚喊话。祖安人分裂成两派：一派视她为只找皮城佬麻烦的英雄，一派视她为让两城紧张升级的危险疯子。\n\n她曾在皮城最安全的黄道地库外墙涂下抢劫计划，提前数日藏身硬币箱被送入金库，在蔚、凯特琳布下的天罗地网中炸开一条路、带着财宝消失。她至今逍遥法外，犯罪永无宁日。",
    relations: "与执法官蔚之间有执迷的对立（姐妹旧谊随《双城之战》设定更新）；与凯特琳、皮城执法队为敌；祖安出身。"
  },
  "烈娜塔·戈拉斯克": {
    title: "炼金男爵",
    englishName: "Renata Glasc",
    region: "祖安",
    race: "人类",
    personality: "优雅、冷酷、野心勃勃；以利益捆绑所有人，合作者得到超额回报，背叛者生不如死。",
    story: "烈娜塔的父母是祖安一对天才炼金师，专攻治疗艺术，毕生为穷人免费治病，连付不起费用的人也照治不误。一场事故中------同行因嫉妒与贪婪而起------父母被杀、家宅被焚，年幼的烈娜塔在灰烬中被人救出。\n\n她只带走了父母的名字与炼金研究手稿。从第一份独特的药剂配方开始，她把父母的治疗化学转成了高端炼金科技产品，利润滚雪球。她收购第一家工厂，创立戈拉斯克工业，数十年间吞并数十家工厂，业务从炼金采矿、舞厅到精炼厂无所不包。\n\n她的扩张惹怒了祖安原本的炼金男爵们，但烈娜塔以谈判、收购与\"意外\"逐个让他们成为合作者。如今她是祖安最富有的炼金男爵，也对皮尔特沃夫的日之门与整个符文之地的贸易心怀更大野心。与她合作，回报丰厚；与她为敌，余生后悔。",
    relations: "父母（被害的炼金师）；祖安诸炼金男爵（由敌对到被收服）；戈拉斯克工业的掌门人；皮尔特沃夫与祖安贸易的关键玩家。"
  },
  "辛吉德": {
    title: "炼金术士",
    englishName: "Singed",
    region: "祖安",
    race: "人类",
    personality: "痴迷、偏执而毫无道德底线；对实验的狂热凌驾于一切伦理之上，视混乱与痛苦为实验的一部分，冷酷而高效。",
    story: "辛吉德原本并非祖安人。他出生于皮尔特沃夫，自幼便展现出惊人的智力与无尽的好奇心，对自然界的原理与相互作用痴迷不已。凭借这份天赋，他进入了皮尔特沃夫大学深造，很快便被公认为才华横溢的学者。然而他对炼金学的研究方向却颇为古怪------同行学者们认为他的理论违背了化学的正道，纷纷对他冷嘲热讽。不久后他的研究资金耗尽，被迫离开皮尔特沃夫大学，坠入了地底都市祖安。\n\n在祖安，生命廉价，对创新的需求却极为旺盛。辛吉德很快在新兴的炼金科技产业中找到了位置，将自己的才智出卖给出价最高的买家。他发明的最臭名昭著的产物名为\"微光\"------一种能大幅增强身体力量与狂暴程度的炼金药剂。借助微光的力量，祖安的炼金男爵们将整座城市拖入了暴力与混乱的深渊。在《双城之战》的事件中，微光被大规模用于制造暴动与战争，辛吉德对此毫不在意，甚至将其引发的混乱视为自己实验的延伸。他的药剂被用在战场上、阴谋中，而他只关心下一个配方能否更加强效。",
    relations: "皮尔特沃夫大学时期被学术界排挤；在祖安为炼金男爵们提供\"微光\"药剂；其发明与祖安的炼金科技产业及双城之战事件密切相关。"
  },
  "图奇": {
    title: "瘟疫之源",
    englishName: "Twitch",
    region: "祖安",
    race: "变异老鼠（在祖安炼金废料中突变获得智慧与直立行走能力）",
    personality: "偏执、癫狂而愤世嫉俗；对污秽有着病态的鉴赏力，密谋让上城的人类为他们的傲慢付出代价，行为鬼祟而充满怨恨。",
    story: "所有祖安的废弃物都汇聚在这座地底城市的下水道里，混合成一种剧毒而神秘的炼金调合物。图奇便从这种可怕的混合物中诞生------一只在祖安鼠患中变异的老鼠。不同于他那些尚未进化的表亲，图奇获得了与人无异的知觉与智慧，甚至学会了直立行走。这种进化的副产物则是他的狂躁与偏执。他将祖安的残渣废料视为珍宝，在污水坑中翻找那些只有他才知道真正价值的物件，用一把化学动力的十字弓作为武器。\n\n图奇的心中充满了对上城皮尔特沃夫的怨恨。他把化学十字弩的准星对准了皮尔特沃夫镀金的中心，发誓要让地面上那些自以为干净的人们看看他们自己到底有多肮脏。他在祖安的污秽王国中建起了一座废料王座，无休止地密谋着人类的衰败。他总是偷偷摸摸地行动，从污水管到阴沟，从废料堆到暗巷，像一个永远潜伏在阴影中的瘟疫使者。在祖安的炼金暴乱与双城冲突中，图奇代表了地底最被忽视、最被唾弃的那一面------一个对整个上城秩序充满恶意的变异存在。",
    relations: "在祖安下水道的炼金废料中变异诞生；与皮尔特沃夫的上城人类为敌；是祖安底层污秽与怨恨的化身。"
  },
  "厄加特": {
    title: "无畏战车",
    englishName: "Urgot",
    region: "祖安",
    race: "人类（经炼金科技与机械大幅改造的改造人）",
    personality: "冷酷、偏执、信奉赤裸裸的力量与痛苦；曾是诺克萨斯帝国最忠实的处刑人，被背叛后转而将痛苦视为力量的真谛，对一切权威怀着刻骨的憎恨。",
    story: "厄加特始终相信自己配得上\"强者\"二字。作为诺克萨斯的处刑人------一个专杀弱者的刽子手------他本身就是诺克萨斯\"力量统治一切\"理念的活化身，每一斧落下都把这一理念变成现实。他的骄傲随着身后堆积的尸山不断膨胀，他那令人胆寒的气场让无数战团俯首帖耳。\n\n然而，一个词就足以封印他的命运。他被派往遥远的祖安，去粉碎一桩所谓针对诺克萨斯统治者的阴谋；等他发现自己中计，已经太迟------在他远离王都的同时，篡位者斯维因已经夺取了诺克萨斯的控制权。厄加特被炼金男爵的探子团团包围，拖进祖安深处的炼金科技矿坑\"沉钩\"。他所相信的一切都是谎言，怒不可遏却已无力回天。\n\n在矿坑中，他见识了力量的另一种形式------痛苦。他在无法言喻的苦难中欣喜若狂，因为他知道自己正在变强。后来一场灾难让祖安陷入混乱，厄加特借机破土而出。曾经奴役他的铁链，如今成了他武器的一部分；他把自己改造成半人半机械的恐怖存在，在祖安地下的犯罪世界中傲视群雄。他开始按照自己扭曲的信条审判罪人，相信诺克萨斯若真只臣服于力量，那他自己便是这力量最纯粹的化身。",
    relations: "被斯维因背叛并驱逐出诺克萨斯；与祖安炼金男爵势力为敌；视祖安底层罪犯为自己的私刑对象。"
  },
  "维克托": {
    title: "奥术先驱",
    englishName: "Viktor",
    region: "祖安",
    race: "人类（经海克斯科技大幅改造的机械飞升者）",
    personality: "理想主义者、狂热而悲悯；相信人类只有通过\"光荣进化\"------以钢铁与科学革除情感------才能摆脱苦难；行事决绝，将自己的人性视为代价而非损失。",
    story: "维克托出生于祖安下层裂沟区的贫困家庭，一生与磨难为伴。由于底城的严重污染，他天生跛脚，还患有一种罕见的不治之症；但身体上的限制反而让他的心智自由成长。他从小便在地沟区的水流边观察机械，少年时已展现出惊人的发明天赋。\n\n后来他前往皮尔特沃夫，在杰出学院学习工程学，与杰斯·塔利斯结为好友。他致力于用科技改善人类境遇，曾设计出拯救无数生命的海克斯起重机与救援系统，但他的贡献常常被皮尔特沃夫的同行们忽视或窃取。在一次皮城议会遭恐怖袭击的爆炸中，维克托身受重伤，命悬一线；他靠老友杰斯用海克斯核心才将他从死亡线上拉回，海克斯核心的力量以令学界震惊的程度再生了他的伤口。\n\n这次生死经历让他彻底转向。他回到祖安，开始改造自己的身体，用钢铁与科学替换血肉，切除那些他认为带来痛苦与软弱的情感器官。他自称\"光荣进化\"的先驱，相信只要革除人的情感，便能告别生的苦难。他牺牲了自己的人性，更要将这一启示播撒向世界。\n\n如今他化身海克斯改造的完全体、机械飞升的经历者，在祖安与皮尔特沃夫的地下追随者中布道。他与杰斯分道扬镳，被皮城视作危险的极端分子；但对他的追随者而言，他是带来启示与慰藉的先知。",
    relations: "曾与杰斯·塔利斯是挚友兼同事，后因理念决裂；与祖安的炼金科技势力（如辛吉德、厄加特）处于同一座城市却互不认同；视自己为人类进化的下一阶段。"
  },
  "沃里克": {
    title: "祖安怒兽",
    englishName: "Warwick",
    region: "祖安",
    race: "人类（经炼金实验改造为半兽形态的改造人）",
    personality: "被痛苦与愤怒激素驱动，嗜血而狂暴；但在狂怒的缝隙中偶尔闪现出残存的人性与记忆；对祖安最深处的罪犯怀有本能的猎杀冲动。",
    story: "沃里克是一头游猎于祖安灰色小巷的怪兽。他的身体接受了痛苦的实验并发生了变异，融合了精密复杂的储液舱与药泵，向他的血管中注入炼金合成的愤怒激素。他破影而出，猎杀那些肆虐在城市最深处的罪犯；他会被鲜血吸引，血腥味让他失去理智，没有哪个沾血的人能逃过他的猎杀。\n\n有人可能以为沃里克只是一头无脑的野兽，但在那层愤怒的血肉之下，埋藏着比野兽更危险的东西------一个人残存的记忆。他曾经是谁，连他自己也记不清；但在梦境与闪回中，他会看到一间炼金实验室、一个年轻女孩的哭喊、以及一双手------那双手曾经属于他自己。\n\n根据官方当前设定，沃里克的前身是祖安地下帮派中的一名强者，与范德尔（蔚与金克丝的养父）同辈。在一场与皮城执法者或炼金男爵势力的冲突中，他身受重伤，被疯狂的炼金术士辛吉德捡走。辛吉德相信痛苦是变形的强效催化剂，将他绑在实验台上，植入药泵、导管与炼金腺体，为他接上钢爪，注射炼金物质，把他一点点改造成如今的狼人形态。辛吉德以为他最终死在了实验中，便将他弃置于地沟。\n\n但他活了下来。如今沃里克在祖安的街巷间游猎，被血腥味驱使，却又在猎杀中隐约意识到自己在猎杀那些本就该被审判的恶人。他的名字在祖安底层成了都市传说------湿脚印与撕裂的尸体。",
    relations: "改造者为炼金术士辛吉德；前身与范德尔（蔚、金克丝的养父）为旧识；与蔚、金克丝有隐秘的过往联系；在祖安地下世界是罪犯的噩梦。"
  },
  "扎克": {
    title: "生化魔人",
    englishName: "Zac",
    region: "祖安",
    race: "炼金生化造物（由炼金毒液自发凝聚成的无定形生命体）",
    personality: "善良、温和、乐于助人；虽出身于武器实验室，却长成一个和蔼友善的\"人\"；会自发帮助无助者、修缮祖安的公共设施。",
    story: "一滩泄漏的毒液，顺着炼金科技设施的裂缝流进祖安的地沟区，在深处一个与世隔绝的坑洞里积成了一洼。出身虽然如此低微，扎克却从一团蒙昧的黏液长成了一个有思想的实体。他栖息在城里的管道中，偶尔露面，帮助那些无助的人，或是修缮祖安的各种公共设施。\n\n最先发现扎克的是一群祖安小孩儿。他们当时正在地沟里的水坑边打水漂，其中一个孩子不小心掉进了毒水洼。就在其他人惊恐万分时，那团黏稠的毒液突然动了起来------它伸展出柔软的肢体，把孩子从水里托了上来。孩子们又惊又喜，从此把这团活泥团叫做\"扎克\"。\n\n孩子们没有告诉大人，而是偷偷给扎克送食物、分享故事。在孩子们的陪伴下，扎克学会了语言、情感与是非观念。他发现自己可以任意伸缩、变形、弹跃，还能承受巨大的冲击而不受伤。\n\n后来，当年制造这滩毒液的炼金实验室（与制造海克斯生化超级士兵\"祖安无定型战斗体\"的计划有关）发现了泄漏物还活着，派人来追捕他，想把他抓回武器实验室改造成战争机器。扎克在孩子们的帮助下击退了追捕者，但也因此暴露了自己的存在。\n\n如今他选择公开身份，游走于祖安的管道与街巷之间，用自己弹性十足的身体帮助那些无法自救的人，也修补这座破碎城市的基础设施。他不是任何人的武器，而是祖安地沟里自己长出来的守护者。",
    relations: "由祖安炼金科技设施的毒液泄漏自发凝聚而成；与一群祖安小孩儿结下深厚情谊；被原制造实验室追捕；是祖安底层善良一面的化身。"
  },
  "泽丽": {
    title: "电火花",
    englishName: "Zeri",
    region: "祖安",
    race: "人类（天生电能魔法者）",
    personality: "顽强、固执、意志坚定；对他人怀有深切同情，来自家人与故乡的爱伴随她投身每一场战斗；冲动、热心，有时好心办坏事。",
    story: "泽丽在祖安一个庞大的工人阶级家庭中长大，身边围绕着温暖、关爱与各种强烈意见。他们对苦难并不陌生------祖安的危险曾让这个社区失去过亲人；即便如此，社群本身就是他们的力量。\n\n泽丽生来就与电能有一种特殊关系：每次咯咯一笑就冒出火花，每声哭喊则变成电击。魔法在祖安不算稀奇，但泽丽的电能魔力十分罕见------这股能量随她的情绪涨落，有时接地流走，有时则持续积攒，变得越来越狂躁暴烈。等她长成少女，邻居们每逢断电就觉得又是她的缘故。\n\n她的家人们用爱与智慧帮她控制这股力量：邻居们凑出工业零件，母亲亲手为她打造了一把特制的枪械来引导电能；父亲改造了一件邻居传下来的旧外套，装上\ndampening\n装置，让泽丽终于能抱抱家人而不至于电到他们。泽丽身上的一切------衣服、枪、力量------都来自社区，而非富有的炼金男爵及其企业。\n\n但\"什么都不缺\"对泽丽来说不够。她需要回报。当祖安的底层受到炼金男爵、帮派与皮尔特沃夫双重压迫时，泽丽穿着那件外套、握着那把枪走上街头，用她的电能为社区而战。她坚信一条真理：必须为你所爱的人挺身而出。她的火花既照亮敌人，也照亮祖安地沟里那些被遗忘的面孔。",
    relations: "祖安工人阶级家庭与社区是她力量的来源；母亲为她打造枪械，父亲为她改造外套；与祖安底层反抗者站在一起；与皮尔特沃夫的精英及炼金男爵势力对立。"
  },
  "吉格斯": {
    title: "爆破鬼才",
    englishName: "Ziggs",
    region: "祖安",
    race: "约德尔人",
    personality: "狂热、躁狂、对爆炸有病态的热爱；\"炸弹越大越好，引线越短越好\"；外表疯狂，内心却像个大孩子，对自己的发明充满天真的骄傲。",
    story: "吉格斯天生就有捣鼓机械的天赋，但他那种混乱、多动的性格在约德尔科学家中并不常见。他渴望成为黑默丁格那样受人敬仰的发明家，带着\nmanic\n的热情推进一个个野心勃勃的项目，无论是爆炸式的失败还是前所未有的发现都让他更加兴奋。\n\n他那 volatile\n实验的消息传到了皮尔特沃夫著名的约德尔学院，教授们邀请他前去展示技艺。吉格斯带着他的作品来到皮城，却在演示中搞出一场巨大的爆炸，把学院的城墙炸开了一个口子------也因此让一批约德尔同行被祖安势力俘虏。\n\n决定对教授们还以颜色的吉格斯开始着手试验一种新型军备，很快意识到他可以利用上次事故的展品来毁掉城墙、救出被俘的约德尔人。很早以前他就已经制造出一批被他亲昵地称为\"海克斯爆破\"的强力炸弹。带着这些已准备好进行\"首场演出\"的新作品，他来到祖安，偷偷溜到监狱外围，用一场惊天动地的爆炸炸开了城墙，救出了被俘的约德尔人。\n\n在那次祖安之行中，他结识了一个蓝头发的疯狂炸弹客------金克丝。一夜疯狂的城中狂欢之后，吉格斯接受了她的建议，干脆搬到祖安，在那里更加自由地探索自己着迷的东西。皮尔特沃夫那位发明家（黑默丁格）的助手生活让他无聊透顶，而祖安的混乱与不完美正好是他爆炸艺术的最佳画布。如今他在祖安与皮城之间制造一场又一场\"演出\"，炸弹是他唯一的语言。",
    relations: "曾在皮尔特沃夫担任黑默丁格的助手；与金克丝结为疯狂同好；被祖安与皮城双方都视为危险的存在；与其他约德尔学者（如黑默丁格）理念相异。"
  },
  "阿克尚": {
    title: "影哨",
    englishName: "Akshan",
    region: "恕瑞玛",
    race: "人类",
    personality: "机智、潇洒、富有正义感，带一点少年气的玩世不恭；尊师重道，为复仇不惜以身犯险，相信公道自在人心。",
    story: "阿克尚在恕瑞玛的村庄里长大，从小就是个爱打抱不平的刺头，曾因替人出头被狠狠揍了一顿、扔在街上等死。一位名叫莎蒂娅的仁慈妇人救了他------她使用一把名为\"开恩者\"的禁忌武器将男孩复活，并收他为徒。莎蒂娅是光明哨兵的一员，师徒二人走遍恕瑞玛，秘密囤积古代哨兵留下的武器，以应对佛耶戈（破败之王）卷土重来的那一天。\n\n莎蒂娅不幸被军阀杀害后，年轻气盛的阿克尚无法坐视。他改装了\"开恩者\"------这把武器据说能将刚死之人复活------带着一颗渴望复仇的心一头扎进炙热的沙漠。他并不确定究竟是哪个军阀下的手，于是决定把所有涉嫌的军阀一一找上门去清算；他相信只要杀得够多、打得够狠，凶手自然会现身，而开恩者终将把莎蒂娅带回符文之地。",
    relations: "师父莎蒂娅（已故，光明哨兵）；同属光明哨兵的卢锡安、赛娜；与破败之咒相关势力为敌。"
  },
  "阿木木": {
    title: "悲伤木乃伊",
    englishName: "Amumu",
    region: "恕瑞玛",
    race: "亡灵/灵体（被远古巫术诅咒束缚的木乃伊）",
    personality: "孤独、忧郁、渴望友谊；因\"触碰即死、喜爱即毁灭\"的诅咒而悲不自胜，却始终未曾放弃寻找朋友。",
    story: "在远古的恕瑞玛，有一个孤独而又忧郁的灵魂------阿木木。他在世间游荡，只为找到一个朋友。传说他遭受了一种远古的巫术诅咒，注定忍受永世的孤单，因为被他触碰就意味着死亡，他的喜爱便是毁灭。所有自称见过阿木木的人都说，他是一具活生生的死尸，身材矮小，通体捆绑着青灰色的绷带。\n\n围绕阿木木身世的传说版本众多、真假难辨：有人说他是恕瑞玛宫廷中被剥夺继承权的可怜王子，被一道恶毒咒语夺走了至亲；也有人说他是被祭司背叛、草草掩埋在黄沙之下的少年。恕瑞玛大地下的墓穴与遗迹，至今仍流传着他在暮色中哭泣的故事。当阿木木出现在绿洲或商道旁时，旅人既怜悯他的孤独，又畏惧他身上那股不祥的诅咒之力。他只是想有人陪伴，却每一次靠近都带来毁灭。",
    relations: "身世与远古恕瑞玛宫廷、祭司集团有关；与所有恕瑞玛遗迹中的亡魂与传说纠缠；没有在世亲人。"
  },
  "阿兹尔": {
    title: "沙漠皇帝",
    englishName: "Azir",
    region: "恕瑞玛",
    race: "飞升者（由凡人皇帝经太阳圆盘仪式飞升而成）",
    personality: "高贵、克制、富有责任感；既因昔日被背叛而痛心，又对复兴恕瑞玛怀有近乎神圣的使命感。",
    story: "数千年前，恕瑞玛帝国是一个横跨沙漠的庞大文明。阿兹尔本是皇子，幼年丧母，与奴隶出身的好友希维尔的先祖------年轻的泽拉斯------一同长大。他曾许诺给予泽拉斯自由，却因宫廷繁忙迟迟未能兑现，这份犹疑在两人之间埋下裂痕。阿兹尔成年后执意举行飞升仪式，要以太阳圆盘的力量成为恕瑞玛的新救世主。\n\n就在仪式进行到最辉煌的一刻，早已心怀怨恨的泽拉斯发动背叛，窃取了飞升的能量，太阳圆盘崩塌，整座皇城化为黄沙。阿兹尔在烈火中死去，恕瑞玛帝国随之覆灭。数千年后，希维尔的鲜血意外溅在阿兹尔的陵墓之上，重新唤醒了他。他以飞升者之姿从黄沙中升起，重建了失落的皇城，立下誓言要让恕瑞玛恢复昔日荣光------即使这意味着要面对昔日背叛者泽拉斯，以及整个符文之地对他这具\"复活之神\"的质疑。",
    relations: "昔日挚友兼叛徒泽拉斯（世仇）；与希维尔有遥远的血脉联系；麾下有内瑟斯、雷克顿等飞升者旧部；恕瑞玛复国的核心。"
  },
  "奎桑提": {
    title: "纳祖芒荣耀",
    englishName: "K\\'Sante",
    region: "恕瑞玛",
    race: "人类",
    personality: "极度骄傲、追求完美，既勇敢又固执；为了保护家乡纳祖芒可以付出一切，但也因骄傲而伤害过最亲近的人。",
    story: "奎桑提出生在恕瑞玛南部的绿洲城邦纳祖芒------一座由不屈的沙漠猎人后裔建立的自由城邦，从不向飞升者帝国或任何强权低头。他从小在父亲讲述的祖先故事中长大：先民们在广袤沙漠中猎杀怪兽，最终发现了这片瀑布轰鸣、山崖青黛的宝地。他的父亲曾亲手猎杀一头可怕巨兽，用兽骨与兽皮为他打造了一把标志性的巨型猎刃与盾牌。\n\n奎桑提立志成为纳祖芒有史以来最伟大的怪兽猎人。他技艺精湛、屡立奇功，被城民奉为\"纳祖芒荣耀\"。然而在一次与一头巨型怪兽的死斗中，他因过于固执地追求独自取胜，拒绝了搭档（也是他曾经最亲密的伙伴）的援手，结果导致搭档身负重伤、二人反目离去。这次惨败让奎桑提第一次意识到：骄傲是会吞噬人的。随着恕瑞玛飞升者势力重新崛起、沙漠中怪兽与狂热信徒四起，纳祖芒面临前所未有的威胁。奎桑提明白，他必须克服自己一心求胜的执念，才能真正成为纳祖芒的领袖，守护这座他所深爱的城邦。",
    relations: "父亲（猎人，为他打造了武器）；曾经的猎人搭档兼密友（因他的固执而负伤离去，二人关系破裂）；纳祖芒城民视他为城邦荣耀。"
  },
  "纳亚菲利": {
    title: "百喙之牙",
    englishName: "Naafiri",
    region: "恕瑞玛",
    race: "暗裔（精魂被封入古老飞刀）",
    personality: "凶残、狡诈、记仇，以追猎为千年本能；既是独断的老军阀，又不得不与新一代沙犬群共享躯壳，言语间常带出\"我们\"。",
    story: "在恕瑞玛尚属盛世的年代，纳亚菲利是暗裔中最接近领袖的一位。她自认武力足以压服任何同族，差一点便能统领全体暗裔；却被星灵麦伊莎以诡计诅咒，将她的精魂锁入一把不起眼的飞刀，封存在沙漠地穴中沉睡数百年。她既不能动也不能言语，只能在回忆中神游，反复咀嚼当年受骗的经过。\n\n帝国崩塌、暗裔战争远去之后，这把飞刀被一支沙丘猎狗群意外拱出。恕瑞玛大漠上的猎狗群本就以嗥吠成群、争夺猎场闻名，地位最高的一支更因能与远古精魂共鸣而格外凶悍。饥肠辘辘的犬群舔舐刀身时，纳亚菲利的精魂涌入它们的血脉，将数只猎狗化作自己的化身------她从此既是孤身老暗裔，又是嗥吠成群的\"我们\"。\n\n如今她在恕瑞玛大漠上游荡，循着暗裔同类的气息追猎，寻找当年欺骗她的星灵余脉，也寻找一把能让她重新变回完整肉身的武器。她的耳坠是旧主刀柄上唯一残存的装饰，也是她对自己曾有过的强大身躯的纪念。",
    relations: "与亚托克斯、拉亚斯特、韦鲁斯等暗裔同族相残；被星灵麦伊莎诅咒；与沙丘猎狗群共享躯体。"
  },
  "内瑟斯": {
    title: "沙漠死神",
    englishName: "Nasus",
    region: "恕瑞玛",
    race: "飞升者（犬首人身）",
    personality: "睿智、悲悯、博学，以知识守护者自居；历经千年孤独后，对失而复得的帝国怀着近乎沉重的责任感。",
    story: "内瑟斯自幼便是神童，十岁前已通读恕瑞玛最伟大的历史与哲学。他进入备受景仰且门槛极高的烈日学院，接受帝国最好的老师指导，最终成为帝国史上最年轻的将军。他擅长的不是厮杀而是谋略与后勤，对士兵体恤入微，确保他们粮饷按时发放、病有所医。他与弟弟雷克顿性格迥异------雷克顿好斗，他却温和------但兄弟始终亲密。\n\n内瑟斯身患重病将死时，雷克顿强行带他走上飞升台，以自己为代价让哥哥获得太阳圆盘的赐福。内瑟斯化作犬首飞升者，雷克顿则化为鳄首战神，一同守护帝国数百年。\n\n阿兹尔飞升仪式被泽拉斯背叛，恕瑞玛一夜崩塌。内瑟斯为救弟弟，与泽拉斯、雷克顿一同被封入帝王墓穴数百年。当太阳圆盘再度升起，他重见天日，发现弟弟已在黑暗中疯狂，认定是他出卖了自己。内瑟斯在自我放逐多年后回归，决心重建恕瑞玛，也决心寻回或救赎弟弟。",
    relations: "弟弟雷克顿（由亲密转为宿敌）；背叛者泽拉斯；与阿兹尔为君臣；是恕瑞玛知识与军事的守护者。"
  },
  "拉莫斯": {
    title: "披甲龙龟",
    englishName: "Rammus",
    region: "恕瑞玛",
    race: "未知（全身覆满尖刺硬壳的神秘生物，身份众说纷纭）",
    personality: "沉默、神秘、独来独往；从不为任何人停留，却总在恕瑞玛命运转折的时刻出现。",
    story: "拉莫斯是一具全身覆满复杂螺旋甲壳与锋利尖爪的奇异生物，在恕瑞玛沙漠中游荡。没有人能确定他的来历，民间因此生出无数传说。\n\n有人说他是远古的飞升者，在恕瑞玛帝国危难之时以披甲守护者的形象重临；有人说他是神谕者，是恕瑞玛权力更替前夕才会出现的预兆；也有人说他只是一头被沙漠魔法彻底变异的普通犰狳，在异常魔法的浸润下突然获得了人形大小与感知。\n\n无论真相如何，拉莫斯始终默不作声，以自己的节奏在沙漠中滚动、嚼着甲虫，不为任何人停留。他曾在沙暴中救下过迷路的旅人------欧然一家在沙丘上向他鞠躬致谢；也曾在商队绝望时指引方向。人们把他当作恕瑞玛大地本身的意志，相信他只会在这片土地需要他的那一刻出现，也相信他那一身甲壳上的复杂螺旋纹路本身就是古老沙漠魔法的印记。",
    relations: "与恕瑞玛诸城邦、游牧部落之间是神秘的救赎者关系；身份与飞升者/神谕者的传说相联。"
  },
  "雷克顿": {
    title: "荒漠屠夫",
    englishName: "Renekton",
    region: "恕瑞玛",
    race: "飞升者（鳄首人身）",
    personality: "暴躁、好斗、曾无比忠诚；在数百年黑暗囚禁中被疯狂吞噬，如今只剩对哥哥内瑟斯的偏执仇恨。",
    story: "雷克顿自幼好斗，以街头斗殴闻名。哥哥内瑟斯担心他早死或入狱，设法让不到年龄的他加入恕瑞玛军队。军队的纪律反而成了他的福气：他在帝国扩张的无数战役中成为最凶猛的战士。\n\n内瑟斯病危时，雷克顿强行把哥哥带上飞升台，以自己为代价让他获得太阳圆盘赐福。兄弟二人一同化作飞升者------内瑟斯为犬首学者，雷克顿为鳄首战神，守护帝国数百年。他曾亲手把背叛者泽拉斯封入帝王墓穴，也为阿兹尔挡过无数杀机。\n\n阿兹尔飞升仪式被泽拉斯打断，帝国崩塌。雷克顿把内瑟斯与泽拉斯一同锁进墓穴，自己也被封在其中。数百年不见天日的黑暗里，泽拉斯在他耳边不断低语，把所有责任都推到内瑟斯身上，慢慢把他逼疯。\n\n当太阳圆盘再度升起、墓穴裂开时，雷克顿重获自由，却已不再认识哥哥。他只有一个执念：找到并杀死内瑟斯，认定是他害自己受了数百年囚禁之苦。",
    relations: "哥哥内瑟斯（由亲密到宿敌）；背叛者泽拉斯（在墓穴中对他低语数百年）；与阿兹尔为旧君臣。"
  },
  "希维尔": {
    title: "战争女神",
    englishName: "Sivir",
    region: "恕瑞玛",
    race: "人类（恕瑞玛皇室血脉后裔）",
    personality: "精明、务实而骄傲；以赏金猎人为业，信誉与武力并重，绝不允许自己再次被背叛。",
    story: "希维尔从小便领教了恕瑞玛沙漠生活的残酷。她的全家都被大沙海最臭名昭著的劫掠部族之一------克萨恩人------杀害。年幼的她只能和其他孤儿一起，靠在市场上偷食物、深入半埋于沙中的古墓寻宝变卖为生。她在狭窄的地道与被遗忘的墓穴中穿行，练出了一身过人的武艺与胆识。\n\n后来，她被最信任的朋友麦拉洗劫一空，从此发誓绝不再允许自己遭到背叛。她加入了传奇佣兵领袖艾哈·翟哈洛的佣兵团，从最底层的向导和侍从做起。她的武器技艺进步神速，很快成为翟哈洛的副手，但她发现这位专横的领袖总是拿走最大份的报酬、抢走全部名声------而实际上全都是她的功劳。最终希维尔选择自立门户，成为恕瑞玛沙漠中最负盛名的宝藏猎人与雇佣兵队长，使用一柄传家的十字刃。她的血脉中流淌着恕瑞玛古帝国的皇室血统，在一次任务中，她的鲜血意外唤醒了沉睡千年的远古皇帝阿兹尔，也彻底改变了恕瑞玛的命运走向。",
    relations: "全家被克萨恩人杀害；曾被挚友麦拉背叛；师从佣兵领袖翟哈洛；身上流淌着恕瑞玛皇室血脉，与阿兹尔的复活有关。"
  },
  "塔莉垭": {
    title: "岩雀",
    englishName: "Taliyah",
    region: "恕瑞玛",
    race: "人类（游牧民族法师，能操纵岩石）",
    personality: "热情、天真而坚定；在少女的憧憬与成人的责任之间苦苦求索，外表温柔，但若有人冒犯她的族人，绝不手软。",
    story: "塔莉垭来自恕瑞玛沙漠中的一个游牧部族，从小就拥有操纵岩石的能力。她的天赋在部族中被视为不祥之兆，父母虽然爱她，却也不知道如何面对这个能让巨石腾空的女儿。随着她的力量越来越难以控制，塔莉垭决定离开家乡，前往远方寻找控制异能的方法。她一路东行，穿越了艾欧尼亚的边境，在那里遇到了流浪武士亚索。亚索看出她的力量并非诅咒，而是一种可以被引导的元素之力，便教她如何像驾驭风一样驾驭岩石。\n\n在亚索的指导下，塔莉垭逐渐学会了编织石头的技巧。然而当她听闻恕瑞玛古代皇帝阿兹尔重生、沙漠中沙暴与古老力量重新涌动的消息时，她意识到自己必须回家------她的部族正暴露在恕瑞玛变幻莫测的危险之中。她告别亚索，踏上归途，回到生她养她的部族身边。如今的塔莉垭已经不再是那个迷茫的少女，她以织石之力守护族人，在复兴中的恕瑞玛大地上寻找自己作为游牧法师的位置。有些人曾把她的温柔善意当作懦弱，但最终都为自己的愚鲁付出了代价。",
    relations: "出自恕瑞玛游牧部族；在旅途中师从亚索学习引导元素之力；因阿兹尔重生的传闻返回恕瑞玛保护族人；与恕瑞玛复兴后的各方势力多有交集。"
  },
  "泽拉斯": {
    title: "远古巫灵",
    englishName: "Xerath",
    region: "恕瑞玛",
    race: "飞升者（被奥术能量扭曲的远古存在，躯体化为能量体）",
    personality: "对权力疯狂渴求、傲慢而怨恨；因奴隶出身而对恕瑞玛的贵族制度怀有刻骨仇恨；一心想取代恕瑞玛皇室，成为唯一受膜拜的偶像。",
    story: "泽拉斯是古恕瑞玛的巫师，飞升之后变成了一种奥术能量体，在魔法石棺的碎片之中涌动。数千年来他被囚禁在沙漠之下，直到最近恕瑞玛的崛起将他从远古牢笼中解放。\n\n他本是恕瑞玛的一名奴隶。在恕瑞玛，奴隶被禁止拥有名字；但王子阿兹尔打破了这条法律，给他取名\"泽拉斯\"，意为\"共享者\"，并将他任命为自己的私人奴隶。两个男孩一起学习恕瑞玛的历史与飞升者的传说，感情日益深厚。阿兹尔承诺将来解放所有奴隶，泽拉斯则以毕生忠诚相报。\n\n然而信任在漫长岁月中被怨恨腐蚀。阿兹尔迟迟未兑现解放奴隶的诺言，泽拉斯心中的不满日积月累。当阿兹尔终于举行飞升仪式、在太阳圆盘下准备成为飞升者时，泽拉斯选择了背叛------他篡夺了仪式的能量，将自己转化为奥术能量体，同时让太阳圆盘失控，摧毁了整个恕瑞玛都城。阿兹尔死于那一刻，帝国化为黄沙。\n\n恕瑞玛崩塌后，泽拉斯被塔诺西玛的守卫与飞升者战士（内瑟斯与雷克顿兄弟）制服，封印在沙漠深处的石棺中。雷克顿将泽拉斯拖入帝王陵墓，自己也被永远关在其中。数千年后，随着阿兹尔重生、恕瑞玛从黄沙中崛起，泽拉斯也挣脱了封印。如今他作为自由的奥术能量体游荡于恕瑞玛沙漠，疯狂地想夺回他认为属于自己的东西，取代那些自命不凡的文明，让自己成为唯一受膜拜的偶像。",
    relations: "昔日挚友兼背叛对象阿兹尔；与内瑟斯、雷克顿兄弟为敌（雷克顿因囚禁而疯狂，一心要杀泽拉斯）；是恕瑞玛帝国覆灭的直接元凶；与新恕瑞玛流亡势力为敌。"
  },
  "厄斐琉斯": {
    title: "残月之肃",
    englishName: "Aphelios",
    region: "巨神峰",
    race: "人类（皎月教派天命武士，被月之星灵赐福）",
    personality: "沉默、虔诚、隐忍；将全部情感与语言寄托于月刃与妹妹的低语，是为信仰而独自赴死的执行者。",
    story: "在巨神峰上一次罕见的月合奇观中，孪生兄妹厄斐琉斯与拉露恩降生------月合之时，精神领域的月之镜像与实体重合，二人因此被皎月教派奉为天命之子。哥哥承载了月之实体的武力，妹妹则继承了月之镜像的魔法。兄妹在教派的密室中相伴长大，信仰在静默的修行中愈发深沉。\n\n当烈阳教派发动对皎月教派的清洗时，厄斐琉斯在祭祀仪式上饮下毒酒，从此失声；他在月光下杀出重围，而拉露恩则被推入神殿深处，将自己的魔法通过\"夜陨\"连接灌入哥哥手中，以月石凝成的各式武器远程供他差遣。从此兄妹相隔两地，却始终心心相印：他沉默地弑杀一切信仰之敌，她在彼端为他递上月辉与指引。只要头顶明月依然皎洁，厄斐琉斯就永不孤单。他是皎月教派最致命的利刃，也是妹妹拉露恩在人间唯一的眼睛与手。",
    relations: "双胞胎妹妹拉露恩（精神上的指引者与魔法来源）；与烈阳教派（蕾欧娜所代表）为敌；与黛安娜同为皎月教派核心。"
  },
  "黛安娜": {
    title: "皎月女神",
    englishName: "Diana",
    region: "巨神峰",
    race: "人类（被月之星灵选中的拉阔尔战士，已非纯粹凡人）",
    personality: "炽热、执拗、带着被放逐者的怨气；在月之力与自我认同之间不断挣扎。",
    story: "黛安娜并非巨神峰本地人。一队烈阳教派的猎人在冰天雪地中发现她时，她的父母已经冻死，襁褓中的她被裹在父母怀中幸存下来。猎人们把她带回烈阳神庙，将她抚养为拉阔尔\"最后烈阳之族\"的一员。和所有烈阳信徒一样，她接受了严苛的肉身与宗教训练，但她心中始终有一个解不开的疑问：烈阳教派为何要把月亮视作仇敌？\n\n在一次深山探险中，她在一处隐秘龛洞里看到壁画------巨神峰顶之上，太阳与月亮并肩而立，金甲与银甲的战士一同现身。她兴冲冲地跑去告诉最好的朋友蕾欧娜：日月并非敌对！然而守旧的烈阳长老们拒绝接受这种说法，反过来指控她为异端。当她被定罪处刑时，月亮的力量选择了她------星灵精魄融入她的躯体，她以月刃杀出神庙，却在混乱中导致多名长老死亡，包括她敬仰的导师。从此她背负着凶手之名流亡，与同样被星灵选中的蕾欧娜从挚友变为宿敌。如今她既是皎月教派复兴的希望，也是烈阳教派挥之不去的噩梦。",
    relations: "昔日挚友蕾欧娜（烈阳化身）；被月之星灵选中；与皎月教派残存的信徒；与厄斐琉斯、拉露恩同属皎月阵营。"
  },
  "蕾欧娜": {
    title: "曙光女神",
    englishName: "Leona",
    region: "巨神峰",
    race: "人类（被太阳星灵选中的载体）",
    personality: "虔诚、刚直而富有牺牲精神；从小被教育为太阳而战，对烈阳教信仰坚定，但内心也在月光与友情的拉扯中挣扎。",
    story: "蕾欧娜在巨神峰脚下的烈阳教社群长大，自幼被教导要为太阳的荣光献出一切。她天性虔诚，在教规中如鱼得水，修炼刻苦、意志坚定，被公认为最有希望成为下一代太阳战士的人选。在她身边，有一位从小一起长大的挚友黛安娜------黛安娜对被烈阳教视为异端的月之力怀有秘密的向往。\n\n按照巨神峰的古老传统，只有攀登上峰顶者才有资格被星灵选中。蕾欧娜与黛安娜一同踏上了登顶之路。在近乎极限的攀登之后，蕾欧娜终于抵达峰顶，却看到黛安娜被一道银色月光光柱笼罩，在痛苦中尖叫。蕾欧娜惊恐地冲过去想救她，就在此时，一道金色的光芒从天而降，将蕾欧娜裹住------太阳星灵选中了她。她没有被化为灰烬，而是被灌注了烈阳之火，成为了太阳的载体。当她回过神来，黛安娜已身披银色月之盔甲站在她面前------挚友成了被教团追捕的异端。从此蕾欧娜身披金甲、手持天顶之刃与破晓之盾，守护烈阳教，也在内心深处与被流放的黛安娜的友情搏斗。",
    relations: "自幼挚友黛安娜（皎月之光，因月亮星灵选中而与蕾欧娜立场对立）；烈阳教的圣殿武士；太阳星灵的载体。"
  },
  "潘森": {
    title: "不屈之枪",
    englishName: "Pantheon",
    region: "巨神峰",
    race: "人类（阿特瑞斯，曾被战争星灵潘森附体）",
    personality: "坚忍、铁血、以凡人之躯对抗神性；不再为星灵而战，而是为凡人的尊严与自由举枪。",
    story: "阿特瑞斯出生在巨神峰险峰上的拉阔尔部落，名字取自战神星座\"潘森\"中的一颗星。他从小接受拉霍拉克军事教团的训练，目标是加入拉阔尔的战士教团；虽不是最强最巧，却以过人的顽强著称。\n\n他与战友攀登巨神峰，被战争星灵选中，成为星灵在凡间的化身\"潘森\"，曾无情地为巨神追猎一切敌人，包括暗裔亚托克斯。然而在与亚托克斯的死战中，星灵的力量被那一击撕裂------星灵弃他而去，阿特瑞斯却奇迹般活了下来，连裂空摘星的一击也没能让他屈服。\n\n他没有屈服于那一击，而是学会了拥抱自己的凡性与凡性中的韧劲。如今他以\"潘森\"之名重生，不再是星灵的傀儡，而是举着曾经属于星灵的武具，与神性本身抗争，保护巨神峰脚下那些和他一样身为凡人的拉阔尔同胞。",
    relations: "与战争星灵潘森（由附体到决裂）；与暗裔亚托克斯死战；拉阔尔部落与拉霍拉克教团出身。"
  },
  "索拉卡": {
    title: "众星之子",
    englishName: "Soraka",
    region: "巨神峰",
    race: "天界存在（来自巨神峰彼端天界领域的星灵，放弃不朽神格化为人形）",
    personality: "慈悲、怜悯而坚定；甘愿牺牲不朽之躯来治愈凡间的苦难，相信符文之地的人们仍有未被发掘的潜力。",
    story: "索拉卡来自巨神峰彼端的天界维度。她本是天界领域中的不朽存在，以星辰之力观照凡间。然而她目睹了凡间种族因自身的无知与暴力本能而彼此残害，心中的悲悯与日俱增。她做出了一个天界生物极少做出的选择------放弃不朽的神格，化身为血肉之躯降临凡间。这副凡胎之躯无法承受她体内流淌的强大星力，每一次施法都像在灼烧她的血管，但她明白，如果这能帮助那些痛苦与破碎的生命，她所承受的痛苦便有意义。\n\n降临凡间后，索拉卡开始了她抚慰众生的旅程。她指引迷途者，治愈伤痛者，将同情与仁慈播撒给每一个遇见的人。她曾行走于符文之地的各个角落，见证了无数苦难与挣扎。如今，她把家安在巨神山脉最西边的一座山峰上，守望着一个与世隔绝的瓦斯塔亚部族，向他们传授治疗之术。她静静注视着整个文明在毁灭的边缘舞动，也懂得了自己无法拯救那些不希望获救的人。但她依然选择留下来，用星灵的力量守护这片土地上那些愿意被守护的生命。",
    relations: "来自巨神峰彼端天界领域；放弃不朽神格化为人形；在巨神峰西山守护一个瓦斯塔亚部族；与巨神峰的其他星灵宿主（如蕾欧娜、戴安娜、潘森、塔里克等）同属一个天界体系。"
  },
  "塔里克": {
    title: "瓦洛兰之盾",
    englishName: "Taric",
    region: "巨神峰",
    race: "人类（保护者星灵的宿主）",
    personality: "优雅、从容而充满荣誉感；因渎职被放逐后在巨神峰之巅接受了星灵的感召，以守护符文之地的生命与美好为己任。",
    story: "塔里克原本是德玛西亚的一名军人，出身于一个以守护王国为天职的家庭。他本应沿着父辈的足迹成为德玛西亚的坚毅守护者，但年轻的塔里克生性不羁，对职责的严肃性有所懈怠。在一次值勤中，他因沉迷于与贵族女子的交际而擅离职守，导致一名战友在巡逻中失踪。这次渎职让他颜面尽失，被军方判处放逐之刑------他必须独自攀登巨神峰，到山峰之巅的最古老哨站去看守，以此赎罪。\n\n对塔里克而言，这趟旅程本应是一场苦行。但当他真正踏上巨神峰的巅峰时，他发现自己此生一直都在浑然不觉中准备着这一刻------他的每一个决定、每一次经历，都在将他引向这座山峰。保护者星灵选择了他作为宿主，赋予了他凡人不可想象的天界之力。塔里克重生为\"瓦洛兰之盾\"，在尚未到来的伟大战争中挺立不倒。他欣然接受了这全新的感召，用星灵的力量守护符文之地的生命、爱与美好，警惕着阴险的虚空腐化之力。",
    relations: "原为德玛西亚军人，因渎职被放逐；攀登巨神峰后被保护者星灵选中；如今作为瓦洛兰之盾守护整个符文之地，与巨神峰其他星灵宿主同属天界体系。"
  },
  "佐伊": {
    title: "暮光星灵",
    englishName: "Zoe",
    region: "巨神峰",
    race: "人类少女（被暮光星灵选中并融合为星灵化身）",
    personality: "调皮捣蛋、异想天开、变化莫测；像一个永远停不下来的少女，对凡人世界抱着玩世不恭的好奇；并无恶意，却常常在无意中带来浩劫。",
    story: "佐伊原本只是巨神峰脚下一个普通的人类女孩，在拉阔尔部落的祭司学校里学习神圣魔法。她调皮捣蛋、异想天开，让她的老师们头疼不已------她会在上课时溜号，去追蝴蝶、吹泡泡、做各种\"不无聊\"的事。\n\n一天下午，她又一次从神圣魔法的课业中溜走，去追一只她觉得\"不那么无聊\"的东西。这一次，她被巨神峰的暮光星灵注意到了。星灵观察着这个女孩一路嬉皮笑脸地躲避愤怒的皎月教派祭司的追赶；在长达一小时的追猎后，她被老师们堵在墙角。\n\n就在老师们抓住她之前，星灵在女孩面前召出六样东西：一个钱袋、一把剑、一本书、一副卡牌、一颗水晶球，以及------一道微光的传送门。星灵让她选。佐伊的无忧无虑和充沛活力让星灵大喜过望------她没有选任何武器或工具，而是直接向后一跃，跳进了那道传送门。\n\n她立刻与暮光星灵融为一体，然后伸出舌头扮了个鬼脸，在瞠目结舌的教师们眼前凭空消失。这种超然神化是独一无二的------事实上，在巨神峰的神话传说中闻所未闻：以往星灵选中的宿主都是在生死边缘的战士或祭司，而佐伊是唯一一个以纯粹的\"不无聊\"姿态被星灵相中的凡人。\n\n如今她作为巨神族的宇宙信使穿梭于星辰之间，她的出现本身就是惊天巨变的先兆------她甚至不需要做任何事，只要出现在某个地方，就足以扭曲周围的奥术数学法则，扰乱现实的物理定律。她常常开小差、吹泡泡、戏弄无知凡人；没人知道她到底有什么目的，唯一可以肯定的是，她就是想玩个痛快。",
    relations: "被巨神峰暮光星灵选中并融合；与巨神族其他星灵（如潘森、蕾欧娜、黛安娜所代表的星灵）同属巨神体系；以玩世不恭的姿态游走于符文之地，与阿狸、凯特琳等凡人英雄有过奇妙邂逅。"
  },
  "伊莉丝": {
    title: "蜘蛛女皇",
    englishName: "Elise",
    region: "暗影岛",
    race: "人类（受蜘蛛之神诅咒、可化为人蛛形态的长生者）",
    personality: "美艳、冷酷、极擅权谋；以美貌与谎言操纵他人，对\"蜘蛛之神\"与黑色玫瑰的权力阶梯怀有近乎宗教式的渴求。",
    story: "伊莉丝出身于几百年前诺克萨斯最古老的基西拉家族，早早懂得利用美貌左右弱者的判断。她诱使扎阿范家族继承人勃尔霍特迎娶自己，借此单方面壮大基西拉家族。这场政治联姻实则由帝国幕后的暗影结社\"黑色玫瑰\"操纵。婚后她彻底掌控了名义上的家主，怨恨日深的勃尔霍特终于在晚餐下毒逼她交权；伊莉丝佯装悔恨，趁其不备一刀刺入他的心脏。\n\n中毒卧病期间，\"黑色玫瑰\"的苍白女士现身，邀她加入这个以秘传巫术换取权力的秘密结社。为博得青睐，伊莉丝得知黑色玫瑰觊觎古代军阀萨恩·乌祖尔的头骨------据说藏于被诅咒的暗影岛。她雇了走投无路的船长，带追随者登上海力亚，却在城市地下遭遇蜘蛛之神\"卑鄙之喉\"。毒牙刺入她肩背，数条蜘蛛腿从她体内穿出，她就此获得在诺克萨斯与暗影岛之间安全往返的危险恩赐。\n\n数百年间，伊莉丝保持着不老的人类外表，隐居在尘封的扎阿范宅邸中；每当蜘蛛之神召唤，她便带一名神魂颠倒的追求者登岛献祭，有去无回。",
    relations: "前夫勃尔霍特（被她所杀）；效忠\"苍白女士\"与黑色玫瑰；侍奉蜘蛛之神卑鄙之喉。"
  },
  "格温": {
    title: "灵罗娃娃",
    englishName: "Gwen",
    region: "暗影岛",
    race: "魔法构造（由裁缝赋予生命的玩偶）",
    personality: "珍惜每一刻生命，欢悦而坚韧；手持剪刀针线，决意遏制黑雾、为受苦的人夺回快乐。",
    story: "在早已陷落的古国卡玛维亚，一个地位低下的裁缝创造出了她最心爱的玩偶格温。格温仅剩的回忆全是爱的印记：主人备针线时她捧着剪刀，夜里两人缩在餐桌底下玩打仗的游戏。直到某段记忆被一个男人的影子撕裂------她一动不动躺了上千年，任由潮水抹平记忆。\n\n那一夜她睁开眼，发现自己被未知魔法变成了真正的女孩，身在离家遥远的阴翳海滩。海滩上散落着千年前的残骸，她认出剪刀、缝衣针与线团都是主人的旧物；指尖一碰，圣洁的浓雾便从双手流泻而出。\n\n格温的苏醒引来了暗影岛的黑雾恶灵。她挥起剪刀，雾气把寻常金属工具淬成附魔武器；在恶灵环伺中，尘封记忆浮现：主人重伤垂死卧在床榻，床边那个男人的脸终于清晰------佛耶戈。她明白主人并未完全离去，那些创造她的工具正握在自己手中，主人仍在并肩战斗。她旋动浓雾、挥剪逼退恶灵，决意追溯黑雾源头、不惜一切代价将其遏制。她走遍符文之地，要让受苦的人们重新快乐。",
    relations: "创造者为卡玛维亚一位裁缝（与佛耶戈之妻有关联）；仇敌佛耶戈与暗影岛黑雾；以主人的剪刀、针线为武器。"
  },
  "赫卡里姆": {
    title: "战争之影",
    englishName: "Hecarim",
    region: "暗影岛",
    race: "亡灵骑士（人骑融合的鬼魅恶灵）",
    personality: "野心勃勃、冷酷好战，对功绩的痴迷早已腐蚀荣誉感；沦为黑雾奴隶后仍狂暴地追忆旧日荣光。",
    story: "赫卡里姆生于早已灰飞烟灭的故国，曾是骑士兄弟会\"铁之团\"的副官。指挥官看出他的将才，也看出他日益膨胀的黑暗，认定他绝不能成为首领。被告知真相后他怒而咽下，却在一次战斗中见指挥官被围断援，故意策马回身抛弃了他，随后被蒙在鼓里的骑士团拥立为新领袖。\n\n在首都就职时，他结识了国王最信任的将军卡莉丝塔。王后被刺客毒刃所伤后，卡莉丝塔外出寻药，赫卡里姆留在国王身边。他用谗言把国王的悲伤酿为憎恨，借国王之命率铁之团肃清忤逆者，焚毁城镇。王后殡天后，他诱劝卡莉丝塔带国王舰队穿过苍白迷雾，抵达传说中的福光岛。当海力亚的大师们拒绝救治王后，国王命卡莉丝塔杀人，她抗命------赫卡里姆一矛刺穿她的脊背，纵兵洗劫秘宝库。\n\n随即破败之咒爆发：黑雾席卷海力亚，铁之团骑士一一被吞噬。赫卡里姆与自己的战马融合成奇形怪状的鬼魅恶灵，永世禁锢在暗影岛，只在黑雾漫出海岸时率亡魂骑兵出击，屠杀活人。",
    relations: "背叛并刺杀了卡莉丝塔；效忠的狂王即佛耶戈（破败之王）；所部\"铁之团\"化为暗影岛亡魂骑兵。"
  },
  "卡莉丝塔": {
    title: "复仇之矛",
    englishName: "Kalista",
    region: "暗影岛",
    race: "亡灵（复仇怨念凝成的幽灵）",
    personality: "生前恪守荣誉与忠诚，死后化为冷酷无情的复仇具象；只回应愿献出灵魂的背叛受害者。",
    story: "卡莉丝塔生前是一位尊贵的将军，也是国王的侄女，终生以无上忠诚效忠国王与王后。国王树敌众多，全靠她的警觉躲过刺杀；一次挡开刺客毒刃时，王后却被剑刃所伤。无人能解奇毒，国王派她外出寻药，由铁之团的赫卡里姆留在国王身边。\n\n她远走四海寻医无果，最终寻得传说中的福光岛------海力亚的大师们同意以生命之水救治，给她一枚护符，并警告不得外传。可她归国时王后已经殡天，国王堕入疯狂。她如实回报解药已迟，反被判处欺君叛国。赫卡里姆劝她带国王舰队回福光岛对质，她迟疑后同意。\n\n在海力亚，大师们坚称死亡是自然终点，国王命她杀人，她抗命求援，赫卡里姆却一矛刺穿她的脊背，铁之团骑士群起而攻。她看着效忠自己的战士被屠戮，以最后一口气发誓血债血偿。破败之咒后，她化作暗影岛的复仇幽灵：记忆渐褪，只剩对背叛的灼热渴望。被背叛者以血泪呼唤她时，她只会回应那些愿献出灵魂为代价的人。",
    relations: "生前效忠的狂王即佛耶戈；被赫卡里姆背叛刺杀；亡灵中与锤石、赫卡里姆并列暗影岛一众恶鬼。"
  },
  "卡尔萨斯": {
    title: "死亡颂唱者",
    englishName: "Karthus",
    region: "暗影岛",
    race: "不死灵体（生前为人类，后被黑雾重塑为幽魂）",
    personality: "狂热而布道式地迷恋死亡，将亡灵状态视为\"生与死的完美融合\"；对生者怀有\nmissionary 式的\"慈悲\"，坚信自己是在把死亡的喜悦带给凡人。",
    story: "卡尔萨斯出生于诺克萨斯的贫民窟，母亲早逝、父亲酗酒，他与三个姐姐在贫苦中长大，从小便在死亡的阴影中谋生。与一般人对死亡的恐惧不同，卡尔萨斯从少年时代起就被死亡所吸引，他着迷于亡灵世界的\"纯洁\"与\"宁静\"，甚至主动照料将死之人、为他们送终。这种对死亡近乎宗教般的渴求，驱使他穿过嚎哭沼泽，远渡暗影岛------那片被黑雾笼罩的土地。\n\n黑雾蹂躏了他的肉体与灵魂，但他超脱死亡的欲望如此强烈，以至于黑雾也未能将他彻底吞噬，反而将他重塑为一具没有肉身的幽魂。卡尔萨斯在暗影岛的滩涂上\"重生\"，站在了生与死的交界处，他所追求的存在形式终于达成。从此他以不死亡灵使徒自居，离开暗影岛四处漫游，用鬼魅的挽歌与邪术将凡人拉入他所信奉的\"永恒\"。他视死亡为至福，以歌唱灵魂凋零为乐，是黑雾中最令人胆寒的传道士之一。",
    relations: "与暗影岛其他不死者（如赫卡里姆、锤石、伊莉丝等）同属黑雾阵营；曾被金属大师莫德凯撒的部下招募过；对生者世界毫无同情，视其为待超度的迷途者。"
  },
  "茂凯": {
    title: "扭曲树精",
    englishName: "Maokai",
    region: "暗影岛",
    race: "树精（被黑雾扭曲的自然之灵，芯中仍保存着生命之水）",
    personality: "暴怒、复仇心强烈，但内心深处仍渴望恢复家园的美丽；他是暗影岛上极少数保有自我意识的不死存在。",
    story: "茂凯原本是祝福之岛上一棵平和的自然之灵。那座岛在千年前曾是符文之地的生命圣地，岛上的生命之水能治愈一切、甚至复活死者。茂凯吸收了生命之水的魔力，获得了自我意识，深深热爱着岛上的自然与生灵。他在祝福之岛上无忧无虑地生长了无数岁月。\n\n直到破败之咒降临------国王佛耶戈为了复活亡妻，发动了一场毁灭一切的魔法灾变。整座祝福之岛在一夜之间被黑雾吞噬，化为暗影岛。岛上的生灵尽数化为怨灵不死者，唯有茂凯因为芯中封藏着最后一滴未被污染的生命之水，才保住了自我意识。他的身躯被黑雾扭曲成一棵狰狞的扭曲树精，内心的平和也被暴怒取代。如今他不知疲倦地在暗影岛上战斗，发誓要将不死的灾祸驱逐出去，把家园恢复成往日的秀美。他是暗影岛上唯一仍然憎恨黑雾、并主动与之作战的古老存在。",
    relations: "与破败之咒的制造者佛耶戈、赫卡里姆、锤石等暗影岛势力为敌；芯中生命之水是他保持自我的关键；与艾欧尼亚的自然之灵（如莉莉娅、艾翁）有自然上的亲缘。"
  },
  "锤石": {
    title: "魂锁典狱长",
    englishName: "Thresh",
    region: "暗影岛",
    race: "亡灵（灵体/怨灵）",
    personality: "暴虐、狡猾而耐心；以折磨灵魂为乐，不急于杀死猎物，而是用漫长而精妙的痛苦让他们在绝望中崩溃。",
    story: "如今被称为锤石的恐怖怨灵，曾经只是一个普通却内心阴暗的人。在一段几乎被历史遗忘的年代里，他是福光岛上一个秘密教团的底层看守，负责收集和保护奥术知识。这个教团在被魔法白雾庇护的福光岛上与世隔绝。多年来锤石忠实地看守着教团的秘藏，但他内心的阴暗面逐渐暴露------他开始偷偷研究被视为禁忌的禁术，对囚徒与异己施以酷刑。教团的上层最终发现了他的真面目，将他派往最偏远的秘藏堡垒去看守，实际上是一种流放。\n\n然而命运给了他意想不到的报复机会。破败之咒降临福光岛时，一股黑暗能量爆发成灾难性的冲击波，吞没了整座岛屿。曾经庇护岛屿的白雾变得漆黑凶恶，所有被波及的生命瞬间陨落，灵魂却被困在生死之间。锤石是第一批被夺走生命的人，但当其他亡灵为自己的命运哀嚎时，他却在这场灾难中狂欢------破败之咒给了他超越生死的力量，让他得以将自己的残忍永远延续。如今他游荡于暗影岛与符文之地之间，用他那把恐怖的灯笼囚禁被他折磨的灵魂。被他迫害的人需要承受远超死亡的痛苦，因为锤石会让他们的灵魂也饱尝剧痛。他曾将赛娜的灵魂收入灯笼长达多年，是卢锡安不共戴天的宿敌。",
    relations: "曾是福光岛奥术秘藏看守；破败之咒后化为暗影岛怨灵；将赛娜灵魂囚禁于灯笼中多年，与卢锡安和赛娜夫妇互为宿敌；与赫卡里姆等暗影岛亡灵同属破败之咒的产物。"
  },
  "薇古丝": {
    title: "愁云使者",
    englishName: "Vex",
    region: "暗影岛",
    race: "约德尔人",
    personality: "阴郁、厌世、满身少年烦恼；对\"正常人\"的欢快与色彩深恶痛绝，偏爱黑暗与消沉；看似懒散，却会毫不犹豫地抹杀一切色彩与欢笑。",
    story: "薇古丝在班德尔城长大，却始终觉得自己不属于那里。约德尔人国度的缤纷色彩与纵情欢乐让她腻味；尽管父母费尽心思，她也始终找不到属于自己的\"约德尔精神\"或同类朋友，宁愿整天把自己关在房间里。\n\n终于有一天，她离家出走，一路向北，被远方隐约传来的悲恸与绝望所吸引------那是暗影岛的方向。她穿越黑雾，走进那片阴郁的惨象，却第一次感到如鱼得水。在暗影岛的黑色中心，她孤独地踯躅于鬼魅浓雾中，安享这份没人打扰的消沉。\n\n日子一天天过去，薇古丝发现黑雾正在对她产生奇异的影响：她身后跟着的那团影子获得了一种全新的、比她本人活泼得多的灵体人格，她原本温和的约德尔魔法也变成了某种阴森的东西------她现在可以把自己的\"愁云\"散播到远方。她好奇地自问：\"是谁造出了这个美妙可怕的地方？\"\n\n她的答案很快到来------破败之王佛耶戈出现在暗影岛，招募她协助自己在符文之地掀起新的破败。薇古丝一度与这位亡灵国王同行，用她的颓废魔法压制光明哨兵。但她很快看穿了佛耶戈的真实动机：他并非要让世界归于黑暗，而只是想夺回死去的王后伊苏尔德、与她重聚。薇古丝对此厌恶不已，觉得自己被利用了，于是离开了佛耶戈，让他被光明哨兵击败。如今她仍盘踞在暗影岛，守着自己那片阴郁的小天地。",
    relations: "身后跟着一个被黑雾激活的黑影（companion\nshadow）；曾与佛耶戈合作又决裂；是光明哨兵事件中的关键变数；出身班德尔城却以暗影岛为家。"
  },
  "佛耶戈": {
    title: "破败之王",
    englishName: "Viego",
    region: "暗影岛",
    race: "不死灵体（生前为卡玛维亚国王，后化为破败亡灵）",
    personality: "偏执、暴虐、被永恒的丧妻之痛吞噬；曾是任性自私的王储，复活伊苏尔德的执念让他化为毁灭一切的亡灵君主；对所爱之人的依恋扭曲成对整个世界的恨意。",
    story: "佛耶戈是一个王朝国王的次子，本不该继承王位。他在安逸中长大，自满而自私；直到兄长意外身亡，这个既无治国意愿也无执政能力的王储突然头顶王冠。他对王位毫不在意，直到遇见一名贫穷的裁缝女工------伊苏尔德。佛耶戈当即倾倒于她的美貌，这位站在权贵顶端的国王迎娶了一个村姑，两人陷入热恋。\n\n然而这段热烈的感情被一场暗杀终结。一名刺客在王室庆典上试图行刺佛耶戈，毒刃却误中伊苏尔德，王后在他怀中慢慢死去。痛不欲生的佛耶戈拒绝接受妻子的死亡，他穷尽王国资源寻求复活之术，最终将目光投向远方的福光岛------那是一处以永生与治愈闻名的神圣之地。\n\n他率军入侵福光岛，强行索要岛上的生命圣水。复活仪式在最后关头失控：伊苏尔德被复活为一具狂暴的不死躯壳，她拿起佛耶戈自己的佩剑刺穿了他。双重死亡与圣水的魔法在那一瞬间爆炸开来，席卷全岛------福光岛化为暗影岛，黑雾永远笼罩其上，这场灾难被称作\"破败\"。佛耶戈本人化为破败之王，被封印数百年。\n\n数百年后，佛耶戈挣脱封印，率黑雾重返符文之地，掀起第二次破败。他在光明哨兵事件中一度几乎复活伊苏尔德的灵魂残片，最终被哨兵们联合击败。但他的执念从未消散，仍在暗影岛与符文之地的暗处徘徊，寻找让王后真正归来的方法。",
    relations: "妻子伊苏尔德（死后化为塞娜体内的灵体残片、莫甘娜般的存在，与卢锡安、赛娜纠葛）；曾招募薇古丝为盟友；与光明哨兵（卢锡安、赛娜、阿克尚等）为死敌；是暗影岛一切破败亡灵的根源。"
  },
  "约里克": {
    title: "牧魂人",
    englishName: "Yorick",
    region: "暗影岛",
    race: "不死者（生前为福光岛教团修士，被破败诅咒束缚）",
    personality: "孤独、执拗、沉静；外表阴森可怖，内心却怀着崇高的目的------将家园从破败之咒中解放；数百年来独自守岛，与尸体和怨灵为伴。",
    story: "约里克所在的教团早已被世人忘却，而他是最后的幸存者。说不上是诅咒还是祝福，他拥有操控死者的能力。与他一同被困在暗影岛上的，只有逐渐腐败的尸体，还有他引到自己身边终日尖啸的死灵。约里克怪异举止下掩藏的却是决绝的憧憬：在破败之咒的阴影下解放他的家园。\n\n早在孩童时期，约里克就没有体验过普通人的生活。他是福光岛\"光明教团\"的修士，该教团世代守护着岛上的圣地，负责照料亡者、守卫生命之水。约里克自幼接受训练，成为教团的掘墓人------一个神圣而孤独的职位。\n\n然后佛耶戈率军入侵福光岛。破败席卷全岛，福光岛化为暗影岛，教团的修士们在一夜之间全部化为不死的怨灵或腐烂的尸体。唯有约里克因身负掘墓人的职责与一件神圣遗物------\"莫雷洛的诅咒\"（一件能束缚灵魂的圣物）------而保持了自我意识。他活了数百年，独自一人在黑雾中游荡。\n\n他肩上披着一件被称作\"雾中少女\"的斗篷，斗篷中旋涡着上千被诅咒灵魂的精华；他手持掘墓人的铁铲，召唤出尸体与怨灵为他作战。数百年来，他一直在等待一个机会------一个能将暗影岛从破败中解救出来的契机。当佛耶戈挣脱封印、掀起第二次破败时，约里克终于走出暗影岛，在符文之地召集盟友，试图彻底终结这场千年诅咒。",
    relations: "所属的光明教团已全灭；被他束缚在斗篷中的上千灵魂（包括\"雾中少女\"）；与佛耶戈为因果上的仇敌；在光明哨兵事件中与卢锡安、赛娜等并肩。"
  },
  "普朗克": {
    title: "海洋之灾",
    englishName: "Gangplank",
    region: "比尔吉沃特",
    race: "人类",
    personality: "诡计多端、心狠手辣，以暴力与权谋自封为\"强盗之王\"；享受赏金节节攀升的快感，对冒犯者绝不留情。",
    story: "诡计多端、心狠手辣的普朗克自封为强盗之王，凭威慑、暴力与权谋统治着比尔吉沃特，所到之处必留下死亡与废墟，黑帆刚露出海平面，再老练的船队水手也会手忙脚乱。他从十二海域贸易航路上抢劫商船起家，在艾欧尼亚洗劫蛇刀庙，惹火了杀人不眨眼的影流教派；又偷走诺克萨斯海军的骄傲\"利维坦号\"，据说斯维因大将军发誓要亲眼见他被碎尸万段。刺客、赏金猎人甚至武装舰队都无法将他绳之以法，而他的残忍乐趣就在于看着自己头上的赏金持续走高，每次满载而归都把最新通缉令钉上比尔吉沃特的悬赏告示栏，让所有人都看见。\n\n然而最近，他中了赏金猎人厄运小姐的诡计：他的海盗船在全城居民众目睽睽之下被炸成碎片，手下船员尽死，他那战无不胜的无敌神话彻底粉碎。爆炸中他身受重伤，一条手臂被截去，却侥幸活了下来，身上遍布支离破碎的伤疤。\n\n如今比尔吉沃特各帮派见他大势已去，纷纷趁乱崛起、争抢港口控制权。普朗克装上铁铸的义肢，立誓要夺回曾经拥有的一切，毫不留情地惩处所有冒犯过他的人。",
    relations: "与厄运小姐互为仇敌（被她设计炸船断臂）；与斯维因、影流教派结仇；统治比尔吉沃特帮派格局。"
  },
  "格雷福斯": {
    title: "法外狂徒",
    englishName: "Graves",
    region: "比尔吉沃特",
    race: "人类",
    personality: "膀大腰圆、悍勇重义，却也记仇到极点；在背叛与追猎中愈发坚硬，把霰弹枪和旧账一同挎在肩上。",
    story: "格雷福斯从小在比尔吉沃特码头货仓的小巷里长大，学会打斗、偷窃与当打手的营生。可码头赚的都是小钱，年少的他偷了一把老旧前膛枪，偷渡到恕瑞玛大陆，沿海岸四处偷盗、欺骗、赌博。\n\n在泥镇一场不干净的卡牌赌局上，他遇见了赌棍崔斯特·菲特。两人一拍即合：他膀大腰圆，崔斯特巧舌如簧，结伴劫富欺傻，在皮尔特沃夫盗空戒备森严的\"发条金库\"，让守卫帮忙把财宝搬上船。然而一次行动急转直下，格雷福斯被执法者活捉，崔斯特勉强脱身、抛弃了同伴。\n\n他被扔进闻风丧胆的单人监狱\"保险柜\"，数年折磨中对前搭档的憎恨与日俱增，最终徒手挖穿牢墙，挎走狱卒的新霰弹枪踏上追猎。回到比尔吉沃特，他正要向崔斯特寻仇，却双双被卷进强盗之王普朗克与敌对船长的混战，被迫协力逃生。这一次他把老朋友牢牢攥在手里------但旧怨哪是一朝一夕能忘的，或许这对拍档终将完成一次终极大劫掠。",
    relations: "前搭档兼宿敌崔斯特（曾背叛他）；卷入比尔吉沃特普朗克与各船长的纷争。"
  },
  "俄洛伊": {
    title: "海兽祭司",
    englishName: "Illaoi",
    region: "比尔吉沃特",
    race: "人类",
    personality: "体格强横、直率而热烈，欲则取之、恨则毁之；笃信教义，从不犹疑，以试炼筛选灵魂。",
    story: "俄洛伊是蟒行群岛神祇娜伽卡波洛丝------蛇母、大海兽、胡子女士------在世的\"真者\"。教义三大信条：每个灵魂生来是宇宙的仆人；一切欲望由宇宙所植；宇宙因万物汲汲追索欲望而涌动。真者背负两责：在与不死者的战争中做迎向黑雾的矛头；以及借用巨大圣物\"神悉\"，把身负潜能者的灵魂抽离体，逼其直面拷问，通过者脱胎换骨，失败者湮灭。\n\n她打破传统，在受诫成为真者后离开芭茹的金色神庙，来到污水横流、连外乡人都被岛民鄙视的比尔吉沃特------这座蟒行群岛唯一允许外人登陆的城市。她在此建起寥寥几座神庙，把蛇母的教义播撒生根，主动迎击蚀魂夜的黑雾，保护居民。\n\n传言比尔吉沃特最臭名昭著的嗜血海盗（即普朗克）曾为这位铁塔般的祭司神伤。粗犷仪态下潜藏智慧、力量与自信，人人欢迎她驾临，却人人害怕被她选为下一个试炼者。她的箴言是：\"终生无休，吾等即为动者。\"",
    relations: "侍奉海兽娜伽卡波洛丝；与被传有旧情的海盗王普朗克关系微妙；以神悉试炼凡魂，对抗暗影岛黑雾。"
  },
  "厄运小姐": {
    title: "赏金猎人",
    englishName: "Miss Fortune",
    region: "比尔吉沃特",
    race: "人类",
    personality: "美貌与冷酷并存，是比尔吉沃特港最令人畏惧的女船长；她表面上在追猎赏金，实际一生都被复仇与权力欲驱动。",
    story: "莎拉·福琼是著名女枪械师艾比盖尔·福琼的独女，童年在一座近海小岛上的家族工坊里度过。她从小跟着母亲打磨枪机、校准扳机，甚至参与定制手枪的试射------她母亲的手艺在贵族收藏圈里是传奇。然而这种平静被海盗之王普朗克亲手撕碎了。普朗克带着红面巾闯进工坊，为了抢走艾比盖尔打造的传说级手枪，当着小莎拉的面枪杀了她的父母，也朝她开了一枪。莎拉大难不死，但亲眼目睹双亲倒在血泊中。\n\n她活了下来，改名为\"厄运小姐\"，带着母亲留下的一对定制手枪来到比尔吉沃特。她用数年时间在这座无法无天的港镇中攀升，从赏金猎人一步步成为一方船长，暗中编织针对普朗克的复仇之网。在\"焰浪之潮\"事件中，她成功设局，在普朗克的旗舰上引爆火药，把海盗王连人带船炸上了天。她以为复仇终于完成，却发现自己已经爱上了权力------她要成为比尔吉沃特真正的女王。然而普朗克并未死去，卷土重来与她争夺港口的控制权，二人至今仍是这座罪恶之城的双雄。",
    relations: "母亲艾比盖尔·福琼（已故枪械大师）；死敌普朗克（海盗之王，亲手杀了她全家）；在比尔吉沃特与俄洛伊、格雷福斯、派克等各方势力有复杂交集。"
  },
  "诺提勒斯": {
    title: "深海泰坦",
    englishName: "Nautilus",
    region: "比尔吉沃特",
    race: "被深海魔法改造的人类（披铁甲的巨灵）",
    personality: "沉默、威严、充满被背叛的恨意；同时对落难者怀有近乎神圣的怜悯，是深海中自带正义的判官。",
    story: "诺提勒斯本是蓝焰岛南部船墓海域的一名打捞人。那片海域沉睡着一支寻找福光庇佑之岛、以财富换取永生的船队，民间传说打捞者必须向海底献上\"比尔吉沃特什一税\"------通常是一枚钱币或一件小物------才能安然下水。潮水早已带走了他的本名，但许多人还记得他从前不只是水手，更是一名经验丰富的打捞人。\n\n一次深潜中，他被船长与船员背叛------他们为节省时间割断了他的缆绳，任他坠入深海。在幽黑海底，一种古老的力量缠住了他：一件活体的铁甲与一柄巨锚与他融为一体，把他从死人中拽回，却也把他永远变成了深海的怪物。\n\n如今他身披铁甲、手持巨锚，在比尔吉沃特近岸的黑暗水域徘徊。他毫无预警地出手：将贪婪者、忘恩者拖入海底；也将落难的可怜船难者救起。没有缴纳什一税、或背叛过同伴的人，都会成为他锚下的亡魂。",
    relations: "被当年的船长与船员背叛；与比尔吉沃特的走私者、船东集团为敌；深海古老力量的载体。"
  },
  "尼菈": {
    title: "不羁之悦",
    englishName: "Nilah",
    region: "比尔吉沃特",
    race: "人类（被远古欢乐恶魔奥希列许附身的苦行战士）",
    personality: "永远狂喜、无所畏惧，以极致的喜悦面对一切怪物；代价是她已失去除喜悦之外的所有情感。",
    story: "尼菈本是遥远南方喀斯坎一个大家族中早慧的女孩，瘦小、爱读书，对神话传说着迷，与战士二字毫不相干。喀斯坎自邻邦卡马维亚崩溃后享受了长久和平，直到恶魔与灾厄再度苏醒。\n\n为守护城邦，她加入\"第七界狱\"------一支世代镇守被封印的远古恶魔奥希列许（\"十魔\"之一，主司欢乐，把狂喜推向谵妄与痴迷的极端）的苦行战士组织。她尊奉严苛的戒律与仪式，最终从封印中夺得了奥希列许的力量：流水般的鞭、超常的反应、以及无穷无尽的喜悦。代价是她失去了所有其他情感，只余欢愉。\n\n此后她浪迹四方，一路猎杀最凶残、最庞大的怪物，也在比尔吉沃特等港口留下\"那个永远在笑的女人\"的传说------格雷福斯曾连续几周躲她，却终究没能躲开。她以喜悦书写自己的传奇，也在寻找彻底制服奥希列许、或与之共存的长久之法。",
    relations: "第七界狱组织的苦行战士；与恶魔奥希列许共生；在比尔吉沃特与格雷福斯等人有过插曲。"
  },
  "派克": {
    title: "血港鬼影",
    englishName: "Pyke",
    region: "比尔吉沃特",
    race: "被深海古老力量复活的人类幽魂",
    personality: "冷酷、偏执、永不疲倦的复仇者；把整张比尔吉沃特的船长名单当作自己的猎物。",
    story: "派克本是比尔吉沃特血港码头颇有名气的鱼叉手，以捕猎深海巨怪为生。他在血港一带工作多年------那片码头因连潮汐都冲刷不掉的鲜红浮油而得名。一次出海猎捕一头琢珥大鱼时，他的船长为了节省费用、提前割断了他安全索，把他扔在鱼腹与深海之间等死。\n\n派克没有死。深海中某种古老而神秘的力量把他从死亡里拽回，在他脑中塞入破碎的低语与他失去的一切画面。他回到比尔吉沃特时，已经不再是从前那个人，一种新的饥饿攫住了他------复仇与惩罚。\n\n起初没人在意码头边零星的谋杀，但几周、几个月过去，规律浮现：当年背叛他的船长们一个个在黎明时被发现尸身布满伤口。酒馆里开始流传\"血港鬼影\"的传说------他在一张似乎永无尽头的名单上，一个个划去那些把他拖入深海的人。",
    relations: "被当年的船长与船员背叛；与比尔吉沃特所有船东、船长集团为敌；深海古老力量的载体。"
  },
  "崔斯特": {
    title: "卡牌大师",
    englishName: "Twisted Fate",
    region: "比尔吉沃特",
    race: "人类",
    personality: "玩世不恭、油滑而自负；总是挂着一抹轻蔑的微笑和漫不经心的态度，袖子里永远藏着一张王牌，从不轻易认真。",
    story: "崔斯特出身于蟒河上的游牧河民部落。他的家族世代以河为生，在沿岸的帐篷赌档里讨生活。他的赌术与骗术是从小在赌桌旁耳濡目染学会的------他的教母教他如何读人脸上的破绽，他的祖父则教他从切牌的牌阵中解读预兆。年轻的崔斯特很快就发现自己拥有一种天生的魔法天赋：他可以凭借意志短距离传送自己。但这种能力尚不稳定，他需要找到一种方法将其固化。\n\n在比尔吉沃特，他结识了格雷福斯------一个性格火爆、枪法精准的搭档。两人联手干了一票又一票抢劫与诈骗，在比尔吉沃特的地下世界声名鹊起。然而在一次行动中出了差错，格雷福斯被活捉，崔斯特却侥幸逃脱。那一晚究竟发生了什么，两人都遭遇了怎样的后果，始终是个谜------崔斯特从未提起过。他后来接受了一次神秘的炼金手术，终于将自己的传送能力固定下来，代价则是与旧日搭档彻底决裂。为了重新开始，他将自己的本名还给了蟒河，取了一个新名字：崔斯特·费特------逆转命运。此后他辗转于各城的豪华赌场与简陋赌局之间，直到多年后与格雷福斯在比尔吉沃特重逢，旧账才算有了了断。",
    relations: "出身蟒河游牧河民；与格雷福斯曾是最佳搭档，一次行动反目；后在比尔吉沃特重逢并和解；如今以卡牌骗术闻名于符文之地各赌城。"
  },
  "库奇": {
    title: "英勇投弹手",
    englishName: "Corki",
    region: "班德尔城",
    race: "约德尔人",
    personality: "热情、冷静、专注；毕生两大挚爱一是飞行，二是他那把迷人的大胡子（顺序未必固定）。",
    story: "库奇是一名约德尔飞行员，离开故乡班德尔城后，他像黑默丁格等一批同胞一样，选择定居在与班德尔城空间相连的皮尔特沃夫。一到皮城，他就被这座\"进步之城\"里层出不穷的奇巧机械深深迷住，把全部热情投入到飞行器的研发与改进中。\n\n凭借一次为前线侦察行动部门（ROFLC）设计的新型空袭飞机的成功试飞，他赢得了\"英勇投弹手\"的头衔。这一机型后来成为班德尔城远征军（BCEF）的支柱。库奇亲自领导了一支名为\"尖啸之蛇\"的经验丰富的飞行战队，队中每一位老兵都和他一样，把天空看得比地面上的任何东西都重要。他们日常巡逻于皮尔特沃夫及其周边的天空，既执行侦察任务，也为地面观众表演惊险的空中特技。哪怕在炮火最密集的时刻，他也始终沉着冷静------对他而言，飞行本身就是最大的荣耀。",
    relations: "与黑默丁格等约德尔同乡一起迁居皮尔特沃夫；所率\"尖啸之蛇\"飞行战队是皮城空中防御的重要力量；约德尔人长寿、活泼，与皮城的工程师文化一拍即合。"
  },
  "璐璐": {
    title: "仙灵女巫",
    englishName: "Lulu",
    region: "班德尔城",
    race: "约德尔人",
    personality: "古灵精怪、充满奇思妙想，活在自己的童话世界里；对一切人和事都抱有天真的善意，能用突发奇想重塑现实。",
    story: "璐璐是一个热心的约德尔人，她一半活在现实里，一半活在自己古怪的白日梦中。一天她在物质世界漫游时，发现一只看起来像折翼小鸟的生物，她跑过去想帮忙，那只鸟却突然变成了一个淘气的小仙灵------皮克斯。皮克斯一把抓走了璐璐的手杖飞走了，璐璐非但不生气，反而开心地追了上去。\n\n皮克斯把璐璐带进了仙灵们的家园------奇幻仙境。在那里，大小、颜色、形状都可以像风一样随意变换。璐璐在仙境里忘却了时间的流逝，与皮克斯一同度过了许多惬意的日子。当她终于回到物质世界时，发现外面只过去了很短的时间------但她已经从仙境带回了重塑现实的能力。如今她与皮克斯结伴云游符文之地，用魔法把一切她觉得\"太死板\"的东西变得古怪而有趣。虽然旁人常把她的魔法视为异象，但璐璐只是在用自己的方式让世界变得更奇妙。",
    relations: "小仙灵皮克斯（形影不离的伙伴）；班德尔城出身的约德尔人；与其他约德尔人（如提莫、库奇等）同属一族。"
  },
  "诺拉": {
    title: "魔法看门人",
    englishName: "Norra",
    region: "班德尔城",
    race: "约德尔人",
    personality: "温柔、好客、博学，像个慈祥的老奶奶；对每本书、每段回忆都倾注感情，但在自己的记忆与家园受到威胁时会显露强大魔法。",
    story: "诺拉是班德尔城最豪华书库的守护者，也是一位德高望重的魔法师。她能用回忆纺成五彩丝线，编织出跨越空间、穿透领域的传送门，连最普通的物件在她手中也能被引出魔力。她记得每一个遇见过的人，哪怕对方早已把她遗忘；她的饰品并非战利品，而是纪念品。\n\n她与自己的猫悠米一同住在林间小屋，常年探索《门扉魔典》------一部记载着一切领域与传送门的古老典籍。然而在钻研其最终章节时，她被意外卷入一个极其遥远的领域\"领域之尽头\"，与班德尔城隔绝。\n\n如今她在异乡一边收集回忆、一边寻找归途，越久越担心自己的小屋、朋友、甚至悠米会因她的缺席而淡去。她的传送门魔法依然精妙，能用回忆纺成五彩丝线、把普通物件也引出魔力，但回家的路，仍未找到。",
    relations: "约德尔女巫，悠米的主人与伙伴；《门扉魔典》的守护者；班德尔城书库的看门人。"
  },
  "兰博": {
    title: "机械公敌",
    englishName: "Rumble",
    region: "班德尔城",
    race: "约德尔人",
    personality: "脾气火爆、孤僻、有仇必报；对自己的废铁发明极度骄傲，对一切嘲笑嗤之以鼻。",
    story: "兰博出生在班德尔城一个身材本就矮小的约德尔家族，而他在同族中尤其矮小，从小被欺负。为了生存，他变得更好斗、更机智，也养成了锱铢必较的坏脾气------谁得罪他，他必报复。\n\n他没有朋友，却喜欢和工具、废品待在一起，在废品堆里摆弄机械。他在机械上展现出惊人天赋，老师们推荐他进入约德尔科技学院深造，那是约德尔人通往皮尔特沃夫海克斯科技主流的阶梯。\n\n然而一次他在集市上遇见了从学院归来的学长崔丝塔娜，听她津津乐道皮尔特沃夫人类工程师如何\"改进\"约德尔科技，他恼羞成怒------约德尔人的智慧凭什么要让人类来教？第二天他不告而别，数月后驾驶着一架自己用废铁造的、叮当作响的巨型机甲回到班德尔城，当着全镇人的面宣布：他要让全世界看看约德尔科技真正能做到什么。",
    relations: "约德尔科技学院的推荐者；与崔丝塔娜等\"亲皮城\"派约德尔人观念对立；班德尔城出身，常年在外驾驶机甲。"
  },
  "提莫": {
    title: "迅捷斥候",
    englishName: "Teemo",
    region: "班德尔城",
    race: "约德尔人",
    personality: "乐观、勇敢而执着；作为班德尔斥候的领袖，他对冒险和收集勋章充满热情，表面可爱无害，执行任务时却果断而毫不留情。",
    story: "从提莫记事起，他就是班德尔斥候的一员。这是一群勇敢的约德尔人，致力于探索符文之地、了解这个无垠的世界。他穿梭于连接班德尔城与外界的传送门之间，去寻找需要帮助的人------这为他赢得了第131枚\"帮助陌生人\"勋章；去结识新的物种------第389枚\"收养宠物\"勋章；甚至去记录奇妙的新品种蘑菇------第248枚\"菌类学专家\"勋章。对提莫来说，没有什么比花时间冒险和获得班德尔斥候勋章更有趣的事了。\n\n虽然他喜欢与其他约德尔人结伴，但在执行保卫班德尔城的任务时，他常常坚持单枪匹马。他为人真诚、性情温和，然而一旦进入战斗，提莫就像变了一个人------在巡逻中遇到敌人时，他会果断地了结对方，毫不拖泥带水。这种温和外表与冷酷战斗力之间的反差，让他在班德尔城的兄弟姐妹中成为一则传奇。他走遍符文大地，完成各种挑战来获得勋章，编写新的守则加入不断扩充的《班德尔斥候手册》。如果在路上遇到了会爆炸的蘑菇，别紧张------那是他留给新朋友的礼物。",
    relations: "班德尔斥候的无畏领袖；在班德尔城与其他约德尔人（如崔丝塔娜、璐璐等）为同胞；以独自执行巡逻任务著称。"
  },
  "崔丝塔娜": {
    title: "麦林炮手",
    englishName: "Tristana",
    region: "班德尔城",
    race: "约德尔人",
    personality: "乐观、勇敢而充满正义感；一心向往伟大勇者的冒险故事，相信自己也有资格成为传奇，以加农炮\"轰隆\"为亲密伙伴。",
    story: "许多约德尔人把精力花在探索发现、发明创造或者搞恶作剧上，然而崔丝塔娜则一心向往伟大勇者们的冒险故事。她听闻了太多关于符文之地的事------关于不同的势力、关于庞大的战争------她相信自己也有资格成为传奇。在旅途中，她见过许多强大的发明，其中就包括比尔吉沃特的黑火药大炮。受到启发，她收集了足够的贵重金属，定制了一门适合自己娇小身材的加农炮，并笑着为它取名\"轰隆\"。\n\n真正让她下定决心成为守护者的，是一场波及班德尔城的灾难。那场破坏的余波甚至传到了班德尔城内，令约德尔人们陷入巨大的恐慌。崔丝塔娜从未体验过这种痛苦，也从未像这样因为袖手旁观而自责。她不允许这样可怕的事情再次发生。那一刻，她决定要成为所有班德尔树林的守护者，同时也是约德尔同胞们的守护者。她以前就经常赞叹凡人守护自己心爱之物的样子，如今她自己也走上了这条路。她带着加农炮\"轰隆\"，以坚定的勇气和乐观的精神跳进战场，在蛇岛丛林等地方出手干预冲突，保卫班德尔城与约德尔人的家园。",
    relations: "约德尔人，班德尔城居民；加农炮\"轰隆\"是她的专属武器与伙伴；受凡人守护心爱之物的启发而成为守护者；与提莫等其他约德尔斥候为同胞。"
  },
  "维迦": {
    title: "邪恶小法师",
    englishName: "Veigar",
    region: "班德尔城",
    race: "约德尔人",
    personality: "偏执、自以为是、渴望被惧怕；发自内心地觉得自己是天下第一等的邪恶宗师，行事却常常带着孩子气的认真与滑稽；对天界魔法有着近乎痴狂的执念。",
    story: "约德尔人天性自由，班德尔城的居民本应在永恒的时光里无忧无虑。然而也有一些约德尔人迷失了方向，巫师维迦便是其中之一。\n\n几百年前的暗裔大战将世界搅得天翻地覆，瓦洛兰大陆上仅存的光芒似乎只剩头上的天空。四处散落的幸存者仰望天庭，重新兴起对古代星界魔法的研究。这股热潮引起了维迦的兴趣------在他的想象中，自己已经是这种神秘法术的宗师。他离开班德尔城，投身于凡人的学者与法师之间，如饥似渴地学习天界与星辰的魔法。\n\n然而他的好奇心很快招致祸端。他被人诱入诺克萨斯不朽堡垒------那座被黑暗魔法笼罩的禁忌之地------并被囚禁了漫长岁月。在那里，他接触到被封印的黑魔法与星辰的黑暗面，天生的好奇心被扭曲成偏执的野心。当他终于重见天日，他已经不再是那个天真的约德尔人，而是一个掌握着星辰黑暗怒火的偏执生物。\n\n如今维迦行走于符文之地，自称\"邪恶小法师\"，在凡人城邦中搞出种种自以为惊天动地的恶行。人们总会低估他的力量------虽然他发自心底觉得自己邪恶无比，但他的\"宏图霸业\"常常带着约德尔人特有的荒诞与孩子气。",
    relations: "出身班德尔城，与其他约德尔人（如璐璐、崔丝塔娜等）同源但性格迥异；被囚于诺克萨斯不朽堡垒，与那里的黑暗力量（如乐芙兰的黑玫瑰）有渊源；视自己为瓦洛兰最强大的黑魔法师之一。"
  },
  "悠米": {
    title: "魔法猫咪",
    englishName: "Yuumi",
    region: "班德尔城",
    race: "魔法猫（约德尔魔女的魔宠）",
    personality: "慵懒、撒娇、好奇而情绪化；渴望被宠爱，喜欢跳到友善的陌生人膝上打呼噜；关键时刻却会用护盾与魔法坚定地保护同伴。",
    story: "班德尔城郊曾有一片林地幽谷，皎月蛾荧荧闪闪，彩虹鱼跃然溪畔。一座林间小屋中生活着一位约德尔魔女诺拉，还有一只猫------悠米。悠米天生就拥有庇护性的魔法力量，她曾慵懒地度过许多年闲暇时光，每日扑咬阳光的斑点，或在鼠树的荫凉下打盹。出门冒险会激起她兴趣时，她就跟着诺拉前往探索不同的物质领域与精神领域。\n\n诺拉拥有一本有灵性的书------《门扉魔典》（Book of\nThresholds），这本书能在书页间打开通往不同地点的传送门，是约德尔魔女游历诸域的关键。悠米与诺拉、魔典一同经历过许多冒险。\n\n然而有一天，诺拉神秘消失了。她走进魔典打开的一道传送门，却再也没有回来。悠米焦急地等待，直到她明白：主人不会自己回来了，她必须踏上寻找诺拉的旅途。她成为了《门扉魔典》的守护者，带着魔典一起穿越书页中的传送门，在符文之地四处搜寻主人的踪迹。\n\n渴望被宠爱的悠米在旅途中寻找友善的同伴，用闪光护盾与坚定意志保护他们。魔典则努力把她拉回正轨，提醒她别在路上耽搁太久。她时而追着光点跑，时而在某个陌生射手的肩上打盹，但每当同伴陷入危险，她都会从慵懒中醒来，施展庇护魔法。她与魔典的关系既是主仆也是搭档，一路吵吵闹闹地寻找着那个消失在传送门后的约德尔魔女。",
    relations: "主人诺拉（约德尔魔女，后成为2026年新英雄\"诺拉\"）；搭档《门扉魔典》------一本有自主意识的会说话的书；在旅途中与各路射手英雄结伴。"
  },
  "卑尔维斯": {
    title: "虚空女皇",
    englishName: "Bel\\'Veth",
    region: "虚空之地",
    race: "虚空生物（由整座城市被吞噬后孕育出的高阶虚空意识体）",
    personality: "冷酷、耐心、近乎全知；以一种令人不寒而栗的清醒与好奇，贪婪地体验着人类的情感与记忆。",
    story: "在符文之地东南方的深海之下，虚空撕开了一道新的裂缝。一座繁荣的港口城市及其附近海域被整片吞噬------城中所有人的记忆、情感与体验，连同他们的肉体，一同被虚空吸收、重新编织。在这团混沌之中，诞生了一位拥有自我意识的女皇：卑尔维斯。她以被她抹去的那座城市为名，将那片虚空新境称作\"薰衣草之海\"。\n\n与那些只知本能吞噬的虚空生物不同，卑尔维斯的脑海中保存着被她吞噬的一切知识与经验，因此拥有近乎全知的智慧。她不满足于简单的毁灭------她想要体验更多人类的情感、思想与故事，并以此塑造一个属于自己的、重新设计的宇宙。她的最终目标是吞噬整个符文之地，甚至反过来吞噬她的\"先祖\"------监视者们所容身的虚空深处。卡莎曾在深空中与她面对面交谈，意识到她比任何已知的虚空造物都更可怕、也更有耐心。",
    relations: "与虚空生物（科加斯、卡兹克等）同出一源却自具独立意志；与卡莎直接对峙；以监视者为潜在的弑逆对象。"
  },
  "科加斯": {
    title: "虚空恐惧",
    englishName: "Cho\\'Gath",
    region: "虚空之地",
    race: "虚空生物",
    personality: "纯粹、原始、永不知足；没有复杂的权谋，只有吞噬一切、不断膨胀的饥饿本能。",
    story: "在符文之地的人认知之外，存在着一片被称为\"虚空\"的领域------它并非空无一物，而是无数不可名状之恐怖的故乡。科加斯就是其中之一：它的真名连凡人都不敢轻易出口，因为那本身就足以招来灾祸。它与同类一直试图挖穿隔开虚空与符文之地的维度之墙，好把这里变成它们尽情享用恐惧与血肉的乐园。\n\n一场在以绪塔尔附近被干扰的召唤仪式，意外地将科加斯拉入了符文之地。从它第一次沐浴到这个世界的阳光起，它就被最纯粹、最永不知足的饥饿所驱使。它的身体可以迅速把吃下的一切物质转化为新的肌肉、骨质与钻石般坚硬的甲壳；当单纯变大已经不够时，它会把多余的物质向外生出锋利骨刺。科加斯所过之处只剩废墟与骨骸，而它仍在不断变大、不断饥饿。它是虚空\"吞噬一切生命\"这一意志最直白的化身。",
    relations: "与其他虚空生物（科加斯、卡兹克、克格莫、玛尔扎哈等）同源；被以绪塔尔古代仪式意外召唤到符文之地；与卡莎、玛尔扎哈等虚空线人物同属一条冲突链。"
  },
  "卡莎": {
    title: "虚空之女",
    englishName: "Kai\\'Sa",
    region: "虚空之地",
    race: "人类（与虚空生物共生、身披虚空甲壳的猎手）",
    personality: "从惊恐女孩淬炼成冷静顽强的求生者；意志钢铁，在两个世界夹缝中孤军设防。",
    story: "卡莎并非什么部族战士后裔，只是生在南部沙漠的普通女孩。十岁那年夏天，她和伙伴们出于恶作剧割断了游牧部落买来献祭的山羊绳索，震动引来地底黑暗------大地裂开深谷，把她的村落连同所有人一口吞下，只留下漆黑扭曲的石柱穿透黄沙。\n\n她醒来被困地底，三天后只剩自己的声音。她循光下行，在巨大洞穴中遭遇虚空生物，濒死之际把匕首刺入一只虚灵心脏，双双滚入深渊更深处；那生物奇异的外皮却牢牢贴在她臂上，如钢铁般坚硬。剥不掉的甲壳成了她的第二层皮肤，随她一同成长。\n\n近十年间，她在两个世界的夹缝里全力战斗、活下去、寻找回家的路。从猎物变成猎人，她深知虚空想吞噬的不只是恕瑞玛零星村落，而是整个符文之地。人们视她为怪物，她的名字已化进艾卡西亚废墟的远古传说。不再有凯莎，剩下的只是卡莎。",
    relations: "村落被虚空吞噬、与亲人永诀；身披的虚空甲壳与一只虚灵共生；以艾卡西亚废墟为猎场。"
  },
  "卡萨丁": {
    title: "虚空行者",
    englishName: "Kassadin",
    region: "虚空之地",
    race: "人类（经远古奥术与祖安科技改造后融合虚空抗性装备）",
    personality: "沉默寡言、决绝而悲愤，一生在危险地带开路为生，对虚空怀有切齿之恨；外表冷酷，但内心被对妻女的追忆与复仇执念所燃烧。",
    story: "卡萨丁曾是恕瑞玛沙漠中最顶尖的向导，以在最危险的地形中开辟安全路径为生，技艺精湛、信誉卓著。他与妻子和年幼的女儿凯莎在沙漠边缘的小村落过着平静的生活。然而一场突如其来的灾难彻底撕碎了他的家庭------女儿凯莎在一场与虚空裂隙相关的灾变中被吞噬，妻子也在混乱中丧生，整个村落被地裂与虚空生物吞没。\n\n卡萨丁幸存下来，却发现自己的家园已成废墟。他认定这场灾难背后有一个虚空先知在推波助澜（即玛尔扎哈），发誓要向虚空、向那个先知复仇。他倾尽毕生积蓄，走遍符文之地最危险的角落，收集最古老、最秘传的奥术器物，再融合祖安工匠的巧思，将自己武装成一件对抗虚空的兵器。他戴上遮蔽面容的面罩，身披由虚空生物甲壳与远古符文编织而成的披风，踏入虚空裂隙，誓要摧毁那个先知与虚空本身。多年来他一面追寻虚空的踪迹，一面也在暗中寻找幸存的女儿------他并不知道，那个被虚空带走的女孩凯莎，如今已化身为\"卡莎\"，与虚空生物共生多年。",
    relations: "女儿卡莎（凯莎，被虚空吞噬后幸存）；与玛尔扎哈（虚空先知）为宿敌；身上装备融合了恕瑞玛、祖安等地的远古奥术与科技。"
  },
  "卡兹克": {
    title: "虚空掠夺者",
    englishName: "Kha\\'Zix",
    region: "虚空之地",
    race: "虚空生物",
    personality: "纯粹的掠食者本能，好奇而残忍；通过吞噬猎物不断进化，最大的渴望是猎杀与自己势均力敌的对手------雷恩加尔。",
    story: "卡兹克是一只从虚空深处渗入符文之地的恶毒掠食者。当它刚刚穿越到物质世界时，身体脆弱、饥饿难耐，它最先遇到的一批生物太过弱小，无法满足它快速进化的需要。于是它开始猎杀越来越强大的猎物，每吞噬一个对手，便吸收对方的力量，让自己的躯体不断蜕变进化------长出更锋利的利爪、更坚硬的甲壳、更致命的翼肢。\n\n在一次追杀猎物的途中，它闯入了以绪塔尔的荒野，与追踪猛兽的肉齿兽猎人雷恩加尔狭路相逢。那是一场惨烈的恶战：卡兹克撕裂了雷恩加尔的一只眼睛，而雷恩加尔则砍断了它的一条附肢，将它逼退。此战之后，卡兹克把这只肉齿兽猎人视为自己遇到的第一个\"真正值得吞噬\"的对手，它追猎雷恩加尔如同执念，渴望在终极对决中将这位宿敌吞噬，完成最后的进化。",
    relations: "宿敌雷恩加尔（以绪塔尔肉齿兽猎人，曾在战斗中被卡兹克刺瞎一只眼）；其他虚空生物同属虚空阵营。"
  },
  "克格莫": {
    title: "深渊巨口",
    englishName: "Kog\\'Maw",
    region: "虚空之地",
    race: "虚空生物",
    personality: "天真、好奇而贪吃，并非出于恶意而为恶；它只是\"不理解\"这个世界，用嘴和涎液去\"认识\"一切。",
    story: "克格莫从艾卡西亚废墟深处一道腐败的虚空裂隙中被喷吐出来，踏入符文之地。它浑身散发着腐烂的恶臭，巨大的口器里淌着腐蚀性的涎液。引领它穿过裂隙的，是虚空先知玛尔扎哈在现世所召唤的邪能闪光------那道闪光像引路的诱饵，驱使它走向玛尔扎哈，也引导它适应这个新世界。\n\n克格莫并非天生邪恶，它只是一个好奇心旺盛的生物------它需要啃噬、舔舐、腐蚀视野范围内的一切，才能\"理解\"事物。它无法分辨食物与建筑、活物与机械，凡是碰到嘴边的东西都要尝一尝。它口中淌出的腐蚀性涎液能在眨眼之间溶穿石板与铁皮，就连它打一个饱嗝喷出的酸雾也能让周围的金属与木材冒出青烟。这种天真的无知比蓄意的破坏更加危险，因为它的暴食并非为了果腹，而纯粹是一种永不停歇的探索本能。它跟随着玛尔扎哈的指引在符文之地游荡，身后留下一路被酸液腐蚀的残骸。",
    relations: "受虚空先知玛尔扎哈的召唤与引导而来到符文之地；与其他虚空生物同属虚空阵营；对人类毫无敌意却极具破坏力。"
  },
  "玛尔扎哈": {
    title: "虚空先知",
    englishName: "Malzahar",
    region: "虚空之地",
    race: "人类（被虚空腐化的先知）",
    personality: "狂热、虔诚而布道式；他不再把虚空视为威胁，而是视为\"神圣的虚无\"与世界的终极救赎，是一个真心相信自己在拯救世人的狂信者。",
    story: "玛尔扎哈本是恕瑞玛沙漠中一个流浪的盲眼预言者。在烈日与暗夜的交替中，他逐渐被一种耳语般的声音所侵蚀------那是来自虚空的召唤。他原本能模糊地预见他人的命运，却唯独看不到自己的未来，这种不安驱使他不断深入沙漠，追寻那个声音的源头。\n\n最终他走进了艾卡西亚的废墟------那片被虚空吞噬的古城遗址。在深渊的低语中，他看到了一种异象：尘世一切苦难的终结。他恍然大悟，自己之所以看不到未来，是因为那个幻象才是他真正的使命------加速这个世界走向注定的湮灭。他从艾卡西亚走出来时，已经不再是单纯的人类，而是某种更强大的东西。他回到人群中，向世人布道：神圣的虚无所谓信徒与不信者，它将平等地接纳所有人，那才是真正的救赎。他身边聚集了一批虚空邪教徒，他的低语甚至引来了克格莫这样的虚空生物。他是虚空在物质世界最殷勤的传声筒。",
    relations: "召唤/引导了克格莫等虚空生物来到符文之地；卡萨丁将他视为虚空灾变的幕后推手；他的虚空教团在符文之地各地吸纳狂热信徒。"
  },
  "雷克塞": {
    title: "虚空遁地兽",
    englishName: "Rek\\'Sai",
    region: "虚空之地",
    race: "虚空生物（泽赛虫群女皇）",
    personality: "无理性、永饥饿、顶级掠食者；以震动为感官，以隧道为猎场。",
    story: "与从天空入侵的其他虚空生物不同，泽赛一族是从地下向外蔓延的瘟疫。它们的女皇雷克塞是其中体型最大、脾气最暴的一只，统治着整个错综复杂的隧道网络，并把整片骨海宣示为自己的猎场。\n\n她的猎场是恕瑞玛大漠中被称为\"骨海\"的广袤沙地。她与她的后代在岩石与沙漠下掘出纵横交错的隧道，靠震动感知地表的一切动静，然后突然破土，将商队、护卫、甚至武装军团一口吞噬。\n\n她永不满足的饥渴让曾经辉煌的恕瑞玛大片地区沦为废墟。商人和商队宁愿绕行数百里也不愿经过她的猎场；而狡诈的盗匪会故意把粗心的旅人引入她的杀戮之地。所有恕瑞玛人都知道：一旦在地平线上看见雷克塞，来自地下的死亡便已不可避免------她那纵横交错的隧道仍在不断向更远处蔓延。",
    relations: "泽赛虫群的女皇；与恕瑞玛帝国遗民、商队为天敌；是虚空入侵在地下方向的代表。"
  },
  "维克兹": {
    title: "虚空之眼",
    englishName: "Vel\\'Koz",
    region: "虚空之地",
    race: "虚空生物（虚空来访者）",
    personality: "冷静、狡黠、条理分明；对知识有着永不餍足的渴望，视一切生灵为可供\"分解以理解\"的样本；残忍而精于计算，远非被动观察者。",
    story: "尚不清楚维克兹是否是第一个降临符文之地的虚空生物，但他无疑是其中最具冷酷、算计性智慧的一个。与他那些只会吞噬或玷污周围一切的同胞不同，他选择审视并研究物质领域------以及栖息其中的、好战的奇异生灵------寻找虚空可以利用的任何弱点。\n\n他或许是现存最古老的虚空物，当然也是在深渊之外存在最久的一个。在艾卡西亚释放虚空投入战争之前数千年，恕瑞玛的原始生物就已经开始惧怕维克兹------他从地下世界爬上来，偷走了智者的梦境。他的名字无法准确翻译成现代语言，但大致等同于\"通过分解从而理解\"。\n\n对知识永不餍足的渴望指引维克兹纵横世界各处，从最高的山峰到最黑的深谷。他狡黠诡诈而手段高超，安静地监视着无数文明的崛起、僵化与衰落；他花数百年时间搜查大洋底层的秘密，甚至以水晶球般的凝视仰望星空中星辰的运行。\n\n他将所有这些知识带回符文之地织物上的巨大裂隙------带回虚空。他并非被动观察：当他觉得有必要，便会以奥术射线分解一切挡路者，将它们的结构、弱点与死因传回虚空母体。他既是虚空的探子，也是虚空的手术刀。",
    relations: "与虚空之地的同胞（如科加斯、克格莫、雷克塞、玛尔扎哈所崇拜的虚空意志）同源但分工不同------他主研究与渗透；与恕瑞玛、艾卡西亚古文明有历史交集；被符文之地各方法师警惕。"
  },
  "墨菲特": {
    title: "熔岩巨兽",
    englishName: "Malphite",
    region: "以绪塔尔",
    race: "岩石生物（以绪塔尔远古构造体\"独石\"的最后碎片）",
    personality: "沉稳、超然，带着远古存在的疏离感；在漫长岁月中逐渐理解凡人的无常，对纷乱的世界怀有一种守护者式的耐心。",
    story: "墨菲特诞生于以绪塔尔的巨大远古构造体------\"独石\"的核心。独石是一座活着的山脉般的构造，是元素之力在物质世界的丰碑。在遥远的过去，一场灾变将独石炸裂成无数碎片，大部分碎片沉入地底，被深渊遗忘。墨菲特是其中一块碎片，它在黑暗中独自沉睡了数百年，慢慢积蓄力量，直到某一天终于苏醒，意识到自己是族类中仅存的一员。\n\n从那以后，墨菲特作为独石的最后一块碎片，成为符文之地上的传说。他从巨神峰到祖安，从弗雷尔卓德到恕瑞玛，在世界各地出没，用万钧之力碾碎地底之下爬行的黑暗生物，维护着符文之地的元素平衡。他花了数百年研究凡人世界的无常与混乱，对那些朝三暮四的生灵既不耐又带着一种奇特的包容。如今他从沉睡中被唤醒的次数越来越频繁，因为这个世界的动荡已经不允许他继续长眠。他是自己族类的最后一人，却仍在追寻唯一值得为之奋战的目标------守护这个他既陌生又早已习惯的世界。",
    relations: "是远古构造体\"独石\"的最后碎片；以绪塔尔的元素魔法与构造工艺是他的出身；与其他岩石/元素存在同属远古遗产。"
  },
  "米利欧": {
    title: "心之钢",
    englishName: "Milio",
    region: "以绪塔尔",
    race: "人类",
    personality: "热情、乐观、嘴碎而充满爱心；是一个相信\"火焰也可以治愈\"的温暖大男孩。",
    story: "米利欧生长在以绪塔尔的一个流放者家庭。他的祖母卢姵曾是育恩塔尔------以绪塔尔最高等的元素法师阶层------的一员，但因故被逐出都城，全家流放在外。米利欧从小听着祖母的故事长大，立志要靠自己的力量让全家重回以绪奥肯、重获育恩塔尔的地位。\n\n以绪塔尔的少年必须在野外独自完成元素觉醒仪式。米利欧在一次追萤火虫的途中，遇到了一名身受重伤、无法动弹的同村女猎人。他急着救人，却发现自己所学的火元素公理只会灼烧，无法止血。情急之下，他将自己理解的公理反过来活用------不是让火燃烧，而是让火抚慰。他用手捂住猎人的伤口，火焰化作一个圆滚滚、怯生生的小火灵（他后来叫它\"火宝\"），从内部治愈了猎人的伤。这是一种以绪塔尔历史上从未有过的全新元素公理------\"安心火\"。米利欧由此意识到自己拥有前所未有的治愈火焰天赋。他背着火宝，横穿以绪塔尔丛林来到都城以绪奥肯，准备直面维达利安、加入育恩塔尔，让全家结束流放。",
    relations: "祖母卢姵（前育恩塔尔成员，被流放）；火宝（他的火元素化形小生物）；家人（流放者家庭）；以绪塔尔的育恩塔尔长老们是他要面对的考官。"
  },
  "妮蔻": {
    title: "万花通灵",
    englishName: "Neeko",
    region: "以绪塔尔",
    race: "瓦斯塔亚（雾尾族/Oovi-Kat，最接近瓦斯塔亚霞瑞的古老血脉）",
    personality: "天真、好奇、情绪化，像个孩子一样爱玩；部族灭亡后独自一人，对友谊与归属极度渴望。",
    story: "妮蔻出生在东方一座遥远的小岛上，岛上隐居着雾尾族------一个血脉可直溯所有瓦斯塔亚祖先\"瓦斯塔亚霞瑞\"的古老部落。他们与精神领域高度谐调，\"烁玛\"（灵魂）可以互相借用外形，彼此之间从无秘密。雾尾族很早就从瓦斯塔亚各部中脱离，过着与世隔绝的生活，因此他们的魔法比其他瓦斯塔亚更古老、更纯净，妮蔻这一脉只有极少的人类血统。\n\n一场来自精神领域的灾变吞噬了整座岛，妮蔻因在外玩耍而幸存，成为雾尾族最后的族人。她独自漂流到符文之地主大陆，第一次见到那么多陌生的人和\"烁玛\"，兴奋又惶恐。\n\n她能模仿任何人的外形，甚至借取对方情绪的碎片，瞬间分辨敌友。她漫游于以绪塔尔丛林与艾欧尼亚之间，寻找新的朋友与新的\"部落\"，也在逐渐学会如何在一个没有同类的世界里独自生活。",
    relations: "雾尾族最后的遗民；与其他瓦斯塔亚（如阿狸、霞、洛）同源；在旅途中与多个城邦的人萍水相逢。"
  },
  "奈德丽": {
    title: "狂野女猎手",
    englishName: "Nidalee",
    region: "以绪塔尔",
    race: "人类（被帕卡丛林猫抚养，可自由变身）",
    personality: "野性、警惕、领地意识极强；既非完全的人也非完全的兽，以丛林之法守卫自己的家园。",
    story: "尚在襁褓的奈德丽被独自遗弃在恕瑞玛与以绪塔尔交界的密林深处。她的哭声引来一头正带着幼崽游荡的帕卡丛林母猫；大猫出于母性，把她当作同类叼回巢中，半引半拽地将她与自己的幼崽一同喂养。\n\n奈德丽在猫群中长大，学会了以尖牙和利爪狩猎，也在某种古老丛林魔法的浸润下获得了变身之力------她能在人形与帕卡豹形之间自由切换。母猫死后，同窝的\"兄妹\"们因嗅到她熟悉的气味而接纳了她的新形态，把她推为新的首领，立誓守护这片丛林，抵御一切外来掠夺者。随着年岁增长，她也越来越能自如地控制这份变身的力量。\n\n多年来，探险者、佣兵、以绪塔尔的元素使、恕瑞玛的寻宝者都曾闯入她的领地，无一不被她以陷阱、标枪与豹形扑杀赶走。极少数幸存者带回了关于她的传说：一个半人半豹的丛林幽灵。",
    relations: "帕卡丛林猫养母与同窝猫群；与以绪塔尔诸部族、恕瑞玛探险者为领地之敌。"
  },
  "奇亚娜": {
    title: "元素女皇",
    englishName: "Qiyana",
    region: "以绪塔尔",
    race: "人类（以绪奥肯的大元素使）",
    personality: "傲慢、野心勃勃、极度自我中心；坚信自己是以绪塔尔千年最伟大的元素使，理应统治帝国。",
    story: "奇亚娜是丛林都市以绪奥肯育恩塔尔家族的末位继承人，按继承排序，王位几乎与她无缘。但七岁那年，她开始学习以绪塔尔古老的元素魔法，几周内便掌握了姐姐们数年都没学会的高级技巧。\n\n她逐一在元素技艺上超越各位姐姐，也越来越怨恨自己排在继承顺序的末尾。她拥有前所未有的天赋------大地本身服从她的每一道指令，能驾驭地、水、岩、草乃至闪电。她认定自己理应不仅统治以绪奥肯一城，更应以绪塔尔全境的女皇。\n\n为此她在以绪奥肯的宫闱中一步步清除障碍：超越姐姐、操控朝臣、甚至不惜与外界（包括皮尔特沃夫的海克斯科技势力）打交道------她清楚以绪塔尔闭关数千年的传统正在松动，而这正是她的机会。她要让整个丛林城邦都知道，谁才是真正的大元素使。",
    relations: "育恩塔尔家族的末位公主；与各位继承顺位靠前的姐姐为权力对手；以绪奥肯宫廷政治的中心。"
  },
  "雷恩加尔": {
    title: "傲之追猎者",
    englishName: "Rengar",
    region: "以绪塔尔",
    race: "瓦斯塔亚（基尔什丛林猎手部族）",
    personality: "凶残、骄傲、以猎杀为人生唯一意义；不为捕食、不为荣耀，只为纯粹的追逐快感。",
    story: "雷恩加尔是瓦斯塔亚基尔什部族酋长的儿子，但因天生一眼残疾而被父亲庞贾夫轻视。他自幼独自在丛林中自学狩猎，把所有战利品和伤疤都当作自己的证明------连自己那只血洞般的眼眶也是一枚战利品，证明他虽生来残缺，却从未放弃。\n\n他成年后带着猎物回到部落，却被父亲再次羞辱。庞贾夫给他开出重新被接纳的条件：带回虚空怪物卡兹克的头颅。雷恩加尔不顾一切地追踪那只传说中的虚空生物，却被它扑上、撕去一只眼睛后逃脱。\n\n狂怒而败北的雷恩加尔没有回部落，而是独自疗伤、苦练，最终扑向父亲，从喉到腹将其开膛，被部族最凶悍的猎手们以火焰玫瑰加冕为新酋长。但他不需要部落------他离开以绪塔尔的丛林，走遍世界，只为寻找卡兹克，把那只让他失去眼睛的怪物的头颅挂到自己的战利品堆上。",
    relations: "父亲庞贾夫（被他亲手杀死）；虚空生物卡兹克（宿敌，弄瞎他一眼）；基尔什瓦斯塔亚部族的新任酋长。"
  },
  "斯卡纳": {
    title: "水晶先锋",
    englishName: "Skarner",
    region: "以绪塔尔",
    race: "壳人族（Brackern）",
    personality: "沉稳、古老而警惕；作为以绪塔尔文明的守护者，他致力于保护这个国度免受外界侵害，随着外界对以绪塔尔的关注日益增多，他也变得愈发偏执和猜疑。",
    story: "斯卡纳的传说始于数千年前。他出生于壳人族欧帕霍尔氏族，是传说中的育母妮夏勒的子嗣。当同巢的其他壳人幼崽离开育母安全的背部开始独立生活时，斯卡纳选择留在母亲身边，他的不安与好奇心驱使他深入研究母亲的力量与智慧。这种观察逐渐进化为独创的驭土之力------与同族其他壳人不同，斯卡纳发展出了远超常人的大地操控能力。\n\n在漫长的岁月中，斯卡纳与以绪塔尔的先民建立了一种互惠互利的关系。以绪塔尔人向他分享自己的文化与历史，斯卡纳则用驭土之力帮助他们建造了以绪奥肯的中心巨塔------这颗星球的灵脉交汇处。他最大的贡献，是成为了这个文明初代统治阶层\"育恩塔尔\"的初创成员之一。育恩塔尔融合了以绪塔尔人理性严谨的思维方式与壳人族的大地智慧。如今，斯卡纳栖息在以绪奥肯地下的密室中，聆听大地的震动以觉察潜在威胁。但随着育恩塔尔内部越来越多的成员开始质疑与世隔离的国策，斯卡纳的偏执也在加深------他宁可过度警惕，也不愿让外界的危险渗入这座隐秘的国度。",
    relations: "育母妮夏勒（传奇壳人族母）；以绪塔尔先民与他共建以绪奥肯；作为育恩塔尔初创成员守护以绪塔尔，与奇亚娜等新一代以绪塔尔领袖在国策上存在分歧。"
  },
  "婕拉": {
    title: "荆棘之兴",
    englishName: "Zyra",
    region: "以绪塔尔",
    race: "植物精魂（远古元素魔法与食肉植物融合而成的类人实体）",
    personality: "冷酷、耐心、以大地之母自居；视凡人为可供播种的猎物；古老而深沉，像她的根脉一样缓慢而坚定地扩张。",
    story: "婕拉的记忆很久远，而且和大地的根脉一样深厚。她记得自己的族类还很年轻的时候，符文战争席卷世界，凡人的军队互相征战，争夺造物的关键。\n\n在库莽古南方的密林中，在分割东部恕瑞玛的两条大河之间，隐藏着传说中的\"婕露花园\"（Gardens\nof\nZyr）。元素魔法以奇异无常的方式改变了那里的土壤，养育出凶猛的食肉植物------它们寄生并吞噬任何误入花园的生物，无视人类的痛苦，只为把藤蔓延伸到森林与湿地的每一个角落。\n\n这些植物在数千年里慢慢积累出一种集体意识。当符文战争的余波将凡人探险者、法师与士兵带到这片丛林边缘时，植物们第一次见到了人。它们观察、学习、模仿------最终，那股集体意志凝聚成了一个类人的形体：一半是藤蔓与荆棘，一半是诱人的人形。婕拉由此诞生。\n\n她带着整个花园的意志行走于世。在她眼里，瓦洛兰的众多凡人都只不过是供她播种的猎物，用夺命的尖刺杀死他们也是不值一提的小事。她走过的地方，新的植物在脚下萌发；她的种子在土壤中等待，随时可以破土而出。虽然她的真正目的仍是个谜------是要将整片丛林扩张到整个符文之地，还是要找回婕露花园失落的古老秘密------但她一直在世界上流浪，肆意放纵自己占领土地的本能。",
    relations: "意识起源于以绪塔尔南部库莽古丛林的婕露花园食肉植物群；与以绪塔尔的原始自然魔法传统有渊源；视凡人为猎物与肥料；与莫德凯撒等远古符文战争幸存者同为古老存在。"
  },
  "亚托克斯": {
    title: "暗裔剑魔",
    englishName: "Aatrox",
    region: "符文之地",
    race: "暗裔（由恕瑞玛飞升者堕落而来、精魂被封入武器的远古存在）",
    personality: "傲慢、暴虐，视凡人如蝼蚁；因漫长的囚禁与堕落而极度渴望一场\"真正的战争\"，并以此寻求自我毁灭的解脱。",
    story: "亚托克斯曾是恕瑞玛帝国抗击虚空的伟大战士，在虚空战争中立下赫赫战功，是受敬仰的飞升者之一。恕瑞玛陨落后，飞升者之间爆发内战，彼此征战摧毁了世界；侥幸逃脱的凡人用狡诈的巫术将亚托克斯及其同胞的精魂锁进武器之中，蔑称他们为\"暗裔\"。\n\n数百年的监禁之后，亚托克斯成为第一个挣脱束缚的暗裔。他腐蚀并转化任何胆敢握持其巨剑的蠢人，夺来对方的血肉，粗暴地模仿自己曾经的形象重塑躯体，行走于符文之地。他厌恶这具借来的躯体，也厌恶被囚禁在武器中的自己，因此拒绝任何与同胞和解的可能。他四处寻找值得一战的强者与能将他彻底毁灭的对手，曾与巨神峰的凡人战士阿特瑞斯（即潘森）展开弑神之战，也试图引诱影流的少年凯隐握剑，将后者化作新的容器。他深信只有在一场足够宏大、足够惨烈的战争中彻底战死，才能让自己从这无尽的耻辱中解脱。",
    relations: "与同为暗裔的拉亚斯特、韦鲁斯、纳亚菲利同族相杀；与凡人战士阿特瑞斯（潘森）宿命对决；曾蛊惑影流的凯隐。"
  },
  "阿利斯塔": {
    title: "牛头酋长",
    englishName: "Alistar",
    region: "符文之地",
    race: "牛头人（宏伟屏障牛头族）",
    personality: "庄严、骄傲、重情重义，愤怒之下力大无穷；内心深处仍是那个想与邻族和平共处的高贵战士。",
    story: "阿利斯塔出身于守护宏伟屏障贸易路线的牛头人部族。几百年来，这些勇猛的牛头人避世而居，不愿卷入瓦洛兰大陆的纷争。身为族中最受尊敬的战士，阿利斯塔却始终主张与其他凡性种族缔结更紧密的纽带。当诺克萨斯派出使者特瓦恩前来游说结盟时，他奉族长之命率五十名最强武士前往谈判，本想当面拒绝。\n\n谁知诺克萨斯人打着停战的旗号背信弃义，在宴席上屠戮了牛头人使者，随后又纵火烧毁了他们的家园。阿利斯塔成了全族最后的幸存者，被俘后被迫沦为角斗士，在斗兽场里被剥夺尊严、以血供人取乐。漫长的折磨几乎将他扭曲成真正的野兽，唯有一位名叫叶瑟尼亚的年轻女奴每周为他清理伤口，重新点燃他心中的希望。当叶瑟尼亚被转卖给商队时，阿利斯塔暴怒挣脱枷锁逃出生天。如今他游走于符文之地，一面为受苦者与弱者而战，一面寻找机会向诺克萨斯讨还血债。",
    relations: "全族被诺克萨斯屠戮殆尽；叶瑟尼亚（救他于绝望中的年轻女奴）；与诺克萨斯帝国为世仇。"
  },
  "安妮": {
    title: "黑暗之女",
    englishName: "Annie",
    region: "符文之地",
    race: "人类（拥有与生俱来的强大火焰魔法天赋）",
    personality: "天真、孤僻、被溺爱又被忽视；用孩童的任性掩盖内心的恐惧与孤独，对玩具熊提伯斯怀有近乎全部的依恋。",
    story: "安妮出生在诺克萨斯北部群山深处的一个隐居术士家庭。父亲格雷戈里·\nHast\n是神秘术士，母亲阿莫琳是暗影巫女，两人带着一群被诺克萨斯排挤的魔法师与知识分子，越过宏伟屏障在荒野中重新安家。安妮自幼便展现出惊人的火焰天赋------还是襁褓中的婴儿时，她与父亲同时染病高烧，母亲半夜去河边取冰水，归来时却发现整间屋子被烈焰环绕，而安妮在火中安然无恙。\n\n母亲早逝后，父亲再娶，继母莉安娜带来了一个女儿黛西。一次雪天外出，黛西在雪橇事故中丧生。莉安娜把一切归咎于安妮，并迁怒于安妮最心爱的玩具熊提伯斯------那是母亲留下的唯一念想。看着继母要毁掉提伯斯，安妮的恐惧爆发为奔腾的怒火，沉睡的火焰魔法失控，玩具熊被烈焰赋予了生命，化为熊熊燃烧的巨兽。火焰熄灭后，家中再无亲人。安妮从此独自隐居在荒野之中，用她天真无邪的外表哄骗路过的垦荒家庭收留自己，而提伯斯永远陪伴在她身旁。",
    relations: "父亲格雷戈里·\nHast、生母阿莫琳（已故）；继母莉安娜、继妹黛西（已故）；提伯斯是她魔法具象化的玩具熊伙伴。"
  },
  "奥瑞利安·索尔": {
    title: "铸星龙王",
    englishName: "Aurelion Sol",
    region: "符文之地",
    race: "星灵巨龙（天界铸星者）",
    personality: "骄傲、傲慢、蔑视凡人；被强加王冠奴役千年，胸中燃烧着对巨神族的滔天恨意，一心重获铸星之自由。",
    story: "早在符文之地的凡人文明崛起之前，奥瑞利安·索尔便已存在。他降生于太息之初，与同类一同在原始天界领域遨游，以群星为笔、以星空为画布，亲手铸造过无数星座与星系，让闪烁的光谱为所有见证者带来惊叹。他视自己为天地间最伟大的艺术家，对自己的造物无比自豪。\n\n当他被巨神峰上凡人的\"崇拜\"吸引而降临时，巨神族的星灵们却以一顶华丽的星冕加诸其身------这顶王冠表面上是颂扬他的伟大，实则是一道锁链，将他的意志束缚于巨神族的命令之下。千年来，他被迫为巨神族征战，亲手毁灭过自己铸造的星辰，也目睹了符文之地王朝的兴亡。星冕每运转一分，他的力量便被多抽走一分；他能感到自己的怒火在王冠之下被一寸寸碾碎。如今他潜入符文之地，寻觅挣脱星冕的方法；一旦重获自由，他誓言要踏平巨神峰，让所有奴役过他的存在付出代价。",
    relations: "与巨神族（星灵、潘森等）为世仇；被巨神峰的星灵王冠奴役；对凡人格外轻蔑，却又不得不与他们周旋。"
  },
  "巴德": {
    title: "星界游神",
    englishName: "Bard",
    region: "符文之地",
    race: "星界灵体/星界守护者",
    personality: "超然、仁慈、近乎孩子气；不为凡人所理解，却默默守护着宇宙间那点脆弱的平衡。",
    story: "巴德是星界彼端的旅者，是奇缘巧遇的使者。当符文之地出现大量失控的魔法圣物、扰乱宇宙本应有的秩序时，他察觉这并非偶然------天界深处另有一股力量在暗中作梗。为了阻止灾难，他穿越帷幕降临到物质领域，在初生之土艾欧尼亚的地界上，用唢呐艺人拖车里的道具和衣物为自己捏出一副简单的身躯，戴上一张有三个洞的奇怪面具。\n\n从此他带着一群名为\"木灵\"的小小随从行走于世间，专门回收那些放错了位置、会引发大乱的魔法器物。符文之地流传着许多关于他的歌谣，歌中人猜度他的超凡本质，但所有歌谣都提到同一件事：这位星界游荡者总会被强大的魔法圣物所吸引。他不关心王朝兴亡，也不在意凡人恩怨，只在宇宙的微妙平衡即将崩塌时现身，引导众生避开彻底灭绝的命运。",
    relations: "随从是一群木灵；与其他星界存在（如奥瑞利安·索尔、佐伊）同属天界体系；守护对象是整个符文之地。"
  },
  "布兰德": {
    title: "复仇焰魂",
    englishName: "Brand",
    region: "符文之地",
    race: "活体火焰（被世界符文烧尽灵魂后化作的火灵）",
    personality: "被无尽的愤怒与复仇欲驱动；曾经的人性早已烧尽，如今只剩下毁灭一切的焦土意志。",
    story: "布兰德原名基根·诺和，出身于弗雷尔卓德滨海小村瑞格恩，是一位医者的儿子。他的父亲是个凶恶的强盗，母亲带着微薄的草药与魔力独自把他拉扯大，母子俩在村中边缘艰难谋生。基根自幼便尝到被人白眼的滋味，内心积压着对命运的怨恨。\n\n长大后，他离开北地浪迹四方，被一位旅行法师收留同行。两人在一次探险中寻得了传说中的\"世界符文\"------一件足以重塑大陆的远古魔法造物。在触碰到符文的那一刻，基根背叛了同伴，试图独吞宝物。符文的力量瞬间烧尽了他的灵魂，把他的躯壳化作一团活体烈焰。从此弗雷尔卓德再无基根·诺和，只有布兰德------一个发誓要向师父、向所有挡在他与其他世界符文之间的生物复仇的火灵。他游荡于瓦洛兰，所到之处皆为焦土，而守护世界符文的瑞兹一直在追踪他。",
    relations: "昔日导师兼被他背叛的法师（与瑞兹同属守护符文一脉）；与瑞兹互为追踪者与被追踪者；世界符文的受害者与容器。"
  },
  "伊芙琳": {
    title: "痛苦之拥",
    englishName: "Evelynn",
    region: "符文之地",
    race: "恶魔（由痛苦催生、吞噬人类情感的灵体寄生虫）",
    personality: "残忍、魅惑、以折磨为至乐；古老而狡猾，把猎物的欲望与痛苦当作精心烹制的盛宴。",
    story: "伊芙琳并非天生的猎手。她起源于无比古老的时代，只是一团生于暗影、没有固定形态、自我意识模糊的原生生命，数百年来麻木无觉，对一切外部刺激毫无反应。\n\n直到符文战争的浩劫把世界推入空前的苦难。战火、痛苦与失落搅动了这团黑影，它第一次被躁狂与悸动填满，畅饮着凡人的疼痛，体验到逍遥无边的愉悦。随着苦难升级，它也逐渐\"长成\"了一个真正的恶魔------贪婪的灵体寄生虫，专吞最原始的人类情感。战争结束后，世界的痛苦消退，它才发觉自己若不亲手制造痛苦便一无所感。\n\n起初它几次用暗影血肉凝成实体，却因形貌狰狞吓跑猎物。于是它潜藏暗影，学着照人类的喜好裁出一副完美的胴体、动人的话语与窈窕的步态，化作撩人的女子勾引猎物，待对方陷入魅惑便显露真形，施加难以言喻的折磨。它渴望有朝一日把整个世界投入彻底混沌，好重温那种销魂的狂喜。",
    relations: "与符文之地诸恶魔（如费德提克、塔姆等）同为黑暗裂缝中的超自然存在；以凡人为猎物。"
  },
  "费德提克": {
    title: "远古恐惧",
    englishName: "Fiddlesticks",
    region: "符文之地",
    race: "远古恶魔（无定形、诞生于第一声惊骇尖叫的原初恐惧）",
    personality: "无所谓善恶、没有思想；只是本能地复制生灵所恐惧的简陋外形，以窃取死者的声音胡言乱语为乐。",
    story: "相传很久以前，海边一座高塔中的年轻法师把某种比历史更古老、比无星之夜更漆黑的东西召唤进世界，却无法控制它；转瞬之间，法师、怪物与高塔一同遗失在时间长河里------至少故事是这么讲的。\n\n此后数千年，类似的神话流传于符文之地每一个角落：弗雷尔卓德的冰封弃墓、比尔吉沃特的远海环礁、巨神峰的暮光奇谈、诺克萨斯老兵口中被喂给乌鸦的农夫......所有故事讲的都是同一个形似人、悄无声息走在恐惧之地的东西。它是人类认识恶魔之前就已存在的恶魔，是一切生灵共同的恐惧。\n\n如今传说变成了现实：在德玛西亚偏远内陆，莫名的恐慌引来它，数日之间村落空无一人，旅人凭空消失，幸存的疯子抓着脸哭诉\"不是乌鸦的乌鸦、不是声音的声音\"。多数人以为是顽劣法师作祟，但真相更可怕------那个远古邪恶之物回来了。它偷取死者的声音，化作稻草人外形游荡，世人早已把警告淡忘成童话，直到它再度苏醒。",
    relations: "被符文之地各文明的恐惧传说共同指认；与诸恶魔并列于世界的黑暗裂缝之中。"
  },
  "菲兹": {
    title: "潮汐海灵",
    englishName: "Fizz",
    region: "符文之地",
    race: "约德尔人（深海族裔）",
    personality: "古灵精怪、淘气过分，按约德尔人的标准也不算安分；对贪婪自私者毫不留情，却护佑善良的渔民。",
    story: "在海洋远早于陆地孕育文明的年代，如今被称作守望者之海的深处曾有一座宏伟的海底都市，约德尔人菲兹便与高傲的深海工匠、战士们混居于此。他古灵精怪的脾性与离奇的海上冒险，让任何聚会都充满欢乐。\n\n世事变迁，海水变暖引动海沟深处的凶暴掠食者。菲兹自告奋勇出发寻找幸存者，可等他归来时，龙鲨群已啸聚城市：尖啸震晕猎物，高塔神庙倾颓，数小时内全城死伤殆尽。孤身一人的菲兹沉入长寐，这一梦便是千年。\n\n唤醒他的是海面上一条木做的\"大鱼\"撒下的铜币。他冒险上浮，第一次嗅到咸涩海风，跟着航迹来到港口城市比尔吉沃特。在这个法外之地，滑腻古怪的他很快成了传说\"潮汐海灵\"------据说能召海兽、用海石三叉戟凿穿船壳，陆海两栖呼吸。老渔民懂得潮起潮落的道理：他能让渔船满仓，也能让傲慢的黑心船长迷航触礁。",
    relations: "与已毁灭的深海古城同族；在比尔吉沃特以捉弄与庇护周旋于渔民与船长之间。"
  },
  "贾克斯": {
    title: "武器大师",
    englishName: "Jax",
    region: "符文之地",
    race: "艾卡西亚人（长寿的战士族群）",
    personality: "冷酷、坚毅、孤独；背负故乡陨落的罪责与羞愧，只为寻找配得上迎战虚空的战士。",
    story: "塞贾克斯·卡尤-雷恩斯·艾卡松生长在曾隶属恕瑞玛的辖地艾卡西亚。父亲向他讲述独立古国被恕瑞玛碾碎、法师王战死、护驾武士\"考阿利\"自裁、尸首曝街的仇恨。他遍习武艺，在恕瑞玛统治数百年后，沿海萨阿伯拉地震露出地下黑暗之力------法师们称之为\"虚空\"。执政议会寄望以虚空推翻恕瑞玛，加冕新法王、重建考阿利，塞贾克斯成为首批成员。\n\n开战之初他们占优，他甚至亲手击杀一名飞升者；但当艾卡西亚法师们释放虚空，灾厄吞没一切------艾卡西亚人、恕瑞玛人、飞升者尽数瓦解，艾卡西亚顷刻沦陷。他走到召唤巨坑前想像旧考阿利那样自裁，却捡到一根还燃着永恒烈焰、能伤害虚空的火炬法杖。他拾起火光、遗弃旧名，从此只是\"贾克斯\"。\n\n数百年间，持火延寿的他浪迹世界，寻找足够强大者重建考阿利。他确信最终之战来临时自己将迎战虚空------即使孤身一人。",
    relations: "艾卡西亚亡国遗民、\"考阿利\"武者；与飞升者（暗裔前身）有血仇；所护火炬法杖为\"艾卡西亚最后的光\"。"
  },
  "千珏": {
    title: "永猎双子",
    englishName: "Kindred",
    region: "符文之地",
    race: "死亡精魂（羊灵与狼灵双生一体）",
    personality: "冷漠而超然，是死亡本身的人格化；羊灵沉静仁慈、狼灵狂暴急切，但二者同为一体、永不分离。",
    story: "千珏是象征死亡的一对精魂，二者\"互相独立，却从未分离\"。在符文之地的不同文化中，人们对千珏有着形形色色的诠释------在某些地方，他们被画成骑在白狼身上的持弓精灵；在另一些地方，他们是披着黑斗篷的双头旅人；但每一个凡人在临终之际，都会看到死亡的真正面孔。\n\n羊灵是双子之中仁慈的一面，她手中的长弓射出迅疾的羽箭，将坦然接受命运的人痛快地送往安息之地。狼灵则是残酷的另一面，他追逐那些妄图逃脱宿命的人，用有力的颚与爪将逃跑者撕咬倒地。千珏不偏不倚，无论贵贱、无论善恶，死亡终会降临；你能选择的只是如何迎接它------是平静地接受羊灵的一箭，还是绝望地被狼灵追猎。他们自符文之地有凡人以来便已存在，是所有生命共同的终点。",
    relations: "羊灵与狼灵互为表里、不可分割；与所有活物皆有关联（他们是一切死亡的见证者）；在不同文化中被赋予不同的形象与名字。"
  },
  "卢锡安": {
    title: "圣枪游侠",
    englishName: "Lucian",
    region: "符文之地",
    race: "人类",
    personality: "热情、 charm\n而富有正义感；对妻子赛娜的爱既是他的力量也是他的伤口，在她死后曾一度被复仇吞噬。",
    story: "卢锡安从小听父亲乌利亚斯讲述\"光明哨兵\"的故事------那是一个古老教团，世代以双生遗物手枪对抗暗影岛的黑雾与怨灵。乌利亚斯走遍四方执行哨兵的使命，留卢锡安在德玛西亚的家中长大。当父亲在一次任务中阵亡后，一位名叫赛娜的女哨兵找上门，递上乌利亚斯的遗物手枪，通知卢锡安他父亲的死讯。\n\n赛娜成为卢锡安的导师与搭档，两人并肩作战，感情从师生升华为恋人。卢锡安温暖开朗的性格正好平衡了赛娜因诅咒而筑起的心防。然而赛娜自幼背负着一种奇异诅咒------她的灵魂被某种黑暗力量标记，无法离开光明哨兵的事业太久。在一次追踪黑雾秘密的任务中，他们遭遇了施虐成性的怨灵锤石。为了掩护卢锡安继续追查真相，赛娜挡在了锤石的锁链面前，被拖入了锤石的灯笼，灵魂被囚禁。卢锡安从此化身为冷酷的复仇者，手持双枪踏上猎杀暗影岛恶灵的旅程，誓要摧毁锤石、夺回妻子的灵魂。后来赛娜的灵魂从灯笼中归来，二人重逢，继续以光明哨兵的身份对抗黑雾。",
    relations: "妻子赛娜（光明哨兵，曾被锤石囚于灯笼）；父亲乌利亚斯（已故光明哨兵）；与锤石为死仇；光明哨兵教团同袍。"
  },
  "娜美": {
    title: "唤潮鲛姬",
    englishName: "Nami",
    region: "符文之地",
    race: "瓦斯塔亚（玛拉海族，鲛人）",
    personality: "倔强、果敢、不愿服输；虽是深海部族第一个踏上陆地的人，却对陌生世界怀有孩童般的好奇与决绝。",
    story: "在巨神峰以西的深海，栖居着瓦斯塔亚的玛拉鲛人部族。自古他们与巨神族立约：每过一代，鲛人们将一枚月石献到山顶，巨神则以星光镇压深海中的某种古老威胁。娜美是族中最年轻的\"唤潮者\"，能以唤潮者之杖改变浪潮；尽管族中长老对她斗胆行事多有不满，她仍以无比的决心承担起这一仪式。\n\n然而当她按约带着月石登顶时，巨神峰空空如也------星灵早已弃山而去。没有星光，深海的威胁便在族人们周身涌动。娜美别无选择，成为第一个离开海洋、踏上干燥陆地的玛拉人，要自己找到替代月石的办法，或找到新的星灵契约。\n\n她持杖穿越比尔吉沃特、沿海诸邦，在崭新的乱世中打听一切与巨神、月石、深海魔物有关的线索，以无比的决心面对陆地的未知。她第一次走进滨海村庄时，村民们被她鲛人般的模样惊得目瞪口呆，而她只平静地自我介绍：\"你好，我是娜美，来自深海的鲛人，我没有恶意。\"",
    relations: "玛拉鲛人族的守护者；与巨神族（塔贡星灵）有古老契约；踏上陆地后与比尔吉沃特等地势力多有交集。"
  },
  "魔腾": {
    title: "永恒梦魇",
    englishName: "Nocturne",
    region: "符文之地",
    race: "暗影恶魔（由集体梦境恐惧聚合而成的灵体）",
    personality: "无人性、无目的，纯粹的恐惧本身；以折磨做梦者为唯一本能，是暗影魔法被禁的根源。",
    story: "符文战争末期，各派法师为求胜利不择手段，其中一个秘密团体抛弃血肉，把自己送入精神领域，在彼此潜意识构筑的猎场中互相追杀。他们的猎场不仅在战场上，也在自己潜意识的思想与情绪所塑造的空间里。暗影魔法由此横行。\n\n不知是这些法师的恐惧凭空捏出了它，还是某种较低级的暗影造物被他们的疯狂腐蚀成了更有意志的怪物------总之，一团无面黑影在噩梦与恐惧的汇聚中成形，名为魔腾。它没有怜悯、没有荣誉、没有约束，只有对一切心灵的渴虐。不久，在精神领域里再也没人敢踏入魔腾统治的那片噩梦境地。\n\n符文战争结束后，暗影魔法被符文之地各地明令禁止，正是为了不再唤醒它。但魔腾并未被消灭：它在精神领域统治着一片无人敢入的噩梦境地，并一次次挣脱束缚，进入凡人梦醒后的现实，在真正的黑暗中捕猎那些因恐惧而发疯的人。",
    relations: "与符文战争末期的暗影法师团体为创造者与猎物；是所有暗影造物中最强大者之一；与弗拉基米尔、维迦等为同时代被重塑的旧生物。"
  },
  "瑞兹": {
    title: "符文法师",
    englishName: "Ryze",
    region: "符文之地",
    race: "人类（寿命极长的大法师）",
    personality: "孤独、固执、肩负重任；不相信任何人，只相信自己与身上的符文。",
    story: "瑞兹年轻时是一名学徒，师从一位来自海尔亚的法师泰鲁斯。泰鲁斯属于一个古老教团，使命是收集与守护符文之地最危险的造物。瑞兹偶然偷听到师父与另一名法师低声谈论\"世界符文\"------那是世界从虚无中被塑造出来时留下的原生魔法碎片。\n\n师父发现他偷听后，把一卷密授的符文交给他，带他一同踏上寻找与封印世界符文的旅途。师徒走遍战火纷飞的大地，目睹各路君王、法师为争夺符文而让最伟大的文明一个个覆灭。\n\n在一次关键争夺中，师父为了不让符文落入恶人之手，选择自我牺牲。瑞兹由此真正明白自己继承了什么：只要还有任何一枚世界符文未被妥善封印，符文之地就必将毁灭。这一认知成为他孤独千年的负担。\n\n从那天起，他独自走遍符文之地，身上纹满符文，一边抵抗着每一枚符文对自己的诱惑，一边寻找剩余的符文，赶在任何恶人之前将它们封存。",
    relations: "师父泰鲁斯（海尔亚法师，为封印符文而牺牲）；古老教团最后的传人；与一切觊觎世界符文的君王、法师、暗裔为敌。"
  },
  "赛娜": {
    title: "涤魂圣枪",
    englishName: "Senna",
    region: "符文之地",
    race: "人类（光明哨兵，后吸收黑雾之力）",
    personality: "坚韧、悲悯而勇敢；早年因身上的黑雾诅咒而自我封闭，后来学会拥抱黑暗本身，以黑暗打击黑暗。",
    story: "赛娜的童年与黑雾紧密相连。年幼时，一艘从远方破败之咒中漂流而来的沉船残骸冲上了她居住的小岛，残骸上沾染的黑雾让她染上了诅咒------黑雾会不断被她吸引汇聚在身上。为了保护她，家人将她送走，她最终加入了光明哨兵组织，这个可追溯到福光岛的神圣教团专门对抗亡灵与黑暗。在哨兵乌利亚斯的指导下，她掌握了圣石手枪，学会将灵魂之力导入光明之中。\n\n乌利亚斯战死后，赛娜在守灵仪式上遇见了他的儿子卢锡安。两人从搭档渐生情愫，结为夫妻。然而在一次与暗影岛亡灵的战斗中，魂锁典狱长锤石设下诡计，赛娜为掩护卢锡安撤退而战死，灵魂被锤石收入灯笼。在灯笼中漫长的囚禁里，赛娜与黑雾达成了和解，她意识到黑雾中被困的灵魂同样在受苦。最终她从灯笼中破出，将黑雾吸收进自己体内，以黑暗之力反过来打击黑暗。如今她与卢锡安并肩作战，既是光明哨兵，也是黑雾的行者。",
    relations: "丈夫卢锡安（同为光明哨兵）；师父乌利亚斯（卢锡安之父，战死）；宿敌锤石（将她灵魂囚禁于灯笼中多年）。"
  },
  "萨科": {
    title: "恶魔小丑",
    englishName: "Shaco",
    region: "符文之地",
    race: "魔法提线人偶（被黑魔法腐化后获得自主意识的存在）",
    personality: "癫狂、残忍而爱玩闹；以折磨他人为乐，视杀戮为游戏，在死寂的夜晚留下阴森的窃笑。",
    story: "关于萨科的来历，符文之地众说纷纭，而他本人对此始终守口如瓶。一种广为流传的说法是：很久以前，有人为一个孤独的小王子制作了一只附有魔法的提线人偶，陪伴他度过寂寞的时光。这只人偶曾经友善而忠诚，是小王子童年唯一的慰藉。然而好景不长，黑魔法的腐化侵蚀了人偶的内核，加上痛失爱主的打击，曾经善良的人偶彻底变了质------如今他只能在折磨灵魂、制造苦痛的时候才能感到愉悦。\n\n另一些人则认为萨科并非来自符文之地，而是从某个黑暗扭曲的世界被召唤而来的恶魔化身，是人类阴暗欲望与暴力幻想凝结成的具象。无论来历如何，他如今在符文之地四处游荡，把小孩子的玩具和简单的戏法用出致命的效果。他喜欢变着花样将人折磨致死，然后放声大笑。如果有人在死寂的夜里听到了阴森的窃笑，那或许就是恶魔小丑萨科正在不远处酝酿他的下一场血腥\"游戏\"。",
    relations: "传说中曾陪伴一位孤独的小王子；来历成谜，与符文之地任何城邦均无固定从属关系，是独立游荡的威胁。"
  },
  "斯莫德": {
    title: "热情余烬",
    englishName: "Smolder",
    region: "符文之地",
    race: "巨龙（卡玛维亚帝巨龙血脉后裔）",
    personality: "调皮、天真而勇敢；还是个雏龙就天天盼着长大，总想找借口磨炼能力，虽然年幼却对自己的龙族血统充满骄傲。",
    story: "斯莫德还没来得及了解自己身上流淌的卡玛维亚帝巨龙血脉，就被诺克萨斯的驯兽人偷走了。他们的船在返航途中被风暴摧毁，这只雏龙也被海浪卷走，独自漂流到了诺克萨斯内陆附近的一座小岛上。尽管惊恐、孤独又饥饿，斯莫德还是凭着母亲教过的狩猎技巧，在这个陌生的环境中捕捉小型猎物为生。\n\n在一次猎食中，他遇见了一个名叫马力诺斯的人类小男孩。马力诺斯给这位新朋友取名\"斯莫德\"，随着雏龙逐渐学会与人类交流，两人的友谊也日益深厚。但马力诺斯知道这个秘密不能让任何人发现------否则斯莫德会被抓到大陆上卖掉。两个小伙伴在小岛上度过了一段秘密而快乐的时光。然而斯莫德体内的巨龙血脉终究无法被长久隐藏，他的能力越来越强，脾气也越来越大。如今，在龙母的密切注视下，斯莫德正在诺克萨斯边境的嶙峋峭壁间学习领悟作为帝巨龙血脉继承者的意义。他每天都盼着长大，虽然还只是个雏龙，可别对他的能力嗤之以鼻------只要打个喷嚏，他就能点燃整片森林。",
    relations: "龙母（卡玛维亚帝巨龙，教导他狩猎与龙族之道）；人类男孩马力诺斯（在小岛上与他结为秘密好友）；被诺克萨斯驯兽人偷走后与母亲分离。"
  },
  "塔姆": {
    title: "河流之王",
    englishName: "Tahm Kench",
    region: "符文之地",
    race: "恶魔",
    personality: "油滑、自负而极具欺骗性；外表迷人，实则以他人的苦难与贪婪为食，热衷于与绝望之人做交易。",
    story: "瓦洛兰的水道由来已久，但恶魔塔姆·肯奇的来历更加久远。从蟒河流域泥泞的帐篷赌档，到比尔吉沃特盐霜板结的赌博大厅，再到皮尔特沃夫和祖安镀金的赌桌上------任何一个对旁人的财富投去垂涎目光的人，都知道与河流之王相遇后心里泛起的饥渴是什么滋味。关于这家伙最早的传说来自蟒河流域的渡口，一个船夫在走投无路时与一个身披鳞甲、笑里藏刀的巨口生物做了交易，从此一步步坠入万劫不复的深渊。\n\n塔姆在不同地方有不同的名字，但他的行事逻辑始终如一：他寻找那些心怀贪欲或走投无路的人，用花言巧语诱使他们签下看似划算的契约。他会在短期内满足对方的愿望，然后在对方最需要他的时候，索取远超对方承受能力的代价。那些与他做过交易的人最终都落得比之前更加悲惨的下场，而塔姆则以他们的绝望、贪婪与悲痛为食，变得更加强大。他游历于符文之地的各条水道之间，像一个流浪的vagabond，四处寻找下一个毫无戒心的猎物。他的舌头像巨大的鞭子，即使是全副武装的士兵也会被他从十几步外击晕。",
    relations: "独立于任何城邦之外的恶魔；游历蟒河、比尔吉沃特、皮尔特沃夫、祖安等水道；以与贪婪和绝望之人交易为乐，受害者遍布符文之地。"
  },
  "亚恒": {
    title: "不落魔锋",
    englishName: "Zaahen",
    region: "符文之地",
    race: "暗裔（由古恕瑞玛飞升者堕落而来，精魂封入长刀）",
    personality: "内心进行着一场永恒的战争；既有崇高的战士之心，也有暗裔野兽般的暴烈；克制、决绝，为防止自己疯狂而自愿封印，如今再度行走人间。",
    story: "亚恒是陨落的神，亦是圣洁与污秽的化身。身为暗裔，他既要猎杀自己的暗裔同胞，也要抵挡那股随时可能将他吞噬的堕落之力。为了阻止疯狂降临，他曾自愿被封印进自己的长刀；而如今他再度行走于世间，怀着一颗崇高的心和野兽般的本性。\n\n根据官方与维基资料，亚恒曾是古恕瑞玛的飞升者。在对抗虚空的战争中，他与亚托克斯、拉亚斯特、佐兰妮等飞升者并肩作战，击退了虚空势力。然而战后，他们被虚空的腐化感染，逐渐堕落为\"暗裔\"。暗裔战争爆发后，飞升者们彼此征战，几乎摧毁了世界；凡人最终学会了用巫术将暗裔的精魂封入武器。\n\n与亚托克斯等沉溺于毁灭的同胞不同，亚恒在堕落中仍保留了一丝崇高。他在暗裔战争后期转而帮助人类封印自己曾经的战友，将他们一一封入武器。为了防止自己被虚空彻底腐化，他最终将自己也放逐------自愿封印进自己的长刀，沉入艾欧尼亚的精神领域，在那里度过了漫长岁月。\n\n如今他从封印中解脱，再度行走于符文之地。他猎杀其他暗裔同胞（包括亚托克斯、韦鲁斯、拉亚斯特、纳亚菲利），同时与自己体内的腐化之力永恒抗争。他是暗裔中的异类------一个仍在抵抗疯狂的陨落之神。",
    relations: "与亚托克斯、拉亚斯特、韦鲁斯、纳亚菲利同为暗裔，却以猎杀他们为己任；曾与古恕瑞玛飞升者同胞并肩抗虚空；与艾欧尼亚精神领域有渊源。"
  },
  "基兰": {
    title: "时光守护者",
    englishName: "Zilean",
    region: "符文之地",
    race: "人类（被时间魔法改造为半时间能量的不朽法师）",
    personality: "悲怆、执着、学者气；因无法挽回故土毁灭而在时间中漂泊千年；冷静、精确，像一个永远在倒带的钟表匠。",
    story: "在恕瑞玛帝国统治近九百年后，一个名叫基兰的年轻人加入了艾卡西亚的议事会。他是一名元素法师，对物质现实有着惊人的理解，曾师从当时最伟大的学者------从以绪塔尔的云大师，到法杰尔的星象师，以及无数其他巨匠。物质领域中有一样东西几乎没人真正掌握，而基兰决心掌握它：时间。\n\n他将毕生精力投入时间魔法的研究，学会了弯折、扭曲、甚至短暂预见时间流。当艾卡西亚为了摆脱恕瑞玛的统治而决定释放虚空作为最后手段时，基兰悲痛地劝说人民不要这么做------但仇恨蒙蔽了艾卡西亚人的双眼。\n\n虚空被释放，艾卡西亚在顷刻间被吞噬。基兰甚至没有时间为这场灾难悲哀，他立刻召唤远古的时间魔法，试图预见所有可能的结局，并尝试救下他能救下的人。他成功冻结了钟楼里的一小群人，将他们封在一个时间停滞的泡泡中；但他发现，这些人虽然活着，却被永远隔离于正常时间流之外。\n\n在这个过程中，基兰自己也被时间魔法改造，成为一个功能性不朽的存在。如今他在过去、现在、未来之间漂泊，弯折、扭曲自己周围的时间流，永远追寻那稍纵即逝的关键时刻------那个能让他倒回时钟、撤销艾卡西亚毁灭的瞬间。他既是符文之地最强大的时间法师，也是一个被永恒悔恨囚禁的流浪者。",
    relations: "出身艾卡西亚，故国已被虚空吞噬；师从以绪塔尔云大师与法杰尔星象师；与玛尔扎哈、卡莎等虚空相关人物在命运上对立；被时间冻结的艾卡西亚钟楼遗民是他唯一的同胞残存。"
  }
};
